import { BehaviorManager } from "../behaviours/BehaviorManager";
import { CircleBehavior } from "../behaviours/CircleBehavior";
import { SegmentedEntity } from "./SegmentedEntity";

export class InkstormLeviathanEnemy extends SegmentedEntity {
  behaviorManager: BehaviorManager;

  constructor(
    hp: number,
    armor: number,
    moveSpeed: number,
    attackDamage: number,
    attackSpeed: number,
    attackRange: number,
    meleeRange: number,
    meleeDamage: number,
    magicResist: number,
    magicPower: number,
    evasion: number,
    xp: number,
    projectileScale: number,
    projectileSpeed: number,
    flying: boolean = false
  ) {
    super(
      "inkstorm_leviathan",
      45, // 45 segments for massive leviathan
      450, // segment radius (match enemy radius)
      0x191970, // midnight blue color
      hp,
      armor,
      moveSpeed,
      attackDamage,
      attackSpeed,
      attackRange,
      meleeRange,
      meleeDamage,
      magicResist,
      magicPower,
      0,
      0,
      0,
      0,
      0,
      0,
      0,
      0,
      0,
      evasion,
      1,
      1,
      0,
      1,
      flying
    );

    this.behaviorManager = new BehaviorManager(
      new CircleBehavior(this.attackRange, this.moveSpeed, 600, 0.1, true, true)
    );
  }
}
