import React, { useState, useEffect, useRef } from 'react';

interface Upgrade {
  name: string;
  shortdescription: string;
  longdescription: string;
  category: string;
  rarity: number;
  apply: (scene: any) => void;
}

interface MatchTwoProps {
  isOpen: boolean;
  onClose: () => void;
  onReward: (rewards: Upgrade[]) => void;
  upgrades: Upgrade[];
}

interface Card {
  id: number;
  upgrade: Upgrade;
  isFlipped: boolean;
  isMatched: boolean;
  isSelected: boolean;
}

// Helper to convert numbers to Roman numerals
function toRoman(num: number): string {
  if (num <= 0) return '';
  const romanNumerals = [
    ['M',1000],['CM',900],['D',500],['CD',400],['C',100],['XC',90],['L',50],['XL',40],['X',10],['IX',9],['V',5],['IV',4],['I',1]
  ];
  let result = '';
  for (const [roman, value] of romanNumerals as [string, number][]) {
    while (num >= value) {
      result += roman;
      num -= value;
    }
  }
  return result;
}

