import React, { useState } from 'react';
import {
  BasePanel,
  Panel,
  Button,
  Input,
  ScrollBar,
  Modal,
  Tooltip,
  ProgressBar,
} from './index';

export const UIDemo: React.FC = () => {
  const [modalOpen, setModalOpen] = useState(false);
  const [inputValue, setInputValue] = useState('');
  const [progressValue, setProgressValue] = useState(65);

  const handleProgressChange = () => {
    setProgressValue(Math.floor(Math.random() * 100));
  };

  return (
    <div style={{ padding: '20px', backgroundColor: '#4a4a4a', minHeight: '100vh', color: '#ffffff' }}>
      <h1 style={{ textAlign: 'center', marginBottom: '40px', textTransform: 'uppercase', letterSpacing: '2px' }}>
        UI Component System Demo
      </h1>

      {/* Panel Hierarchy Demo */}
      <Panel title="Panel Hierarchy" variant="primary" size="large" fullWidth style={{ marginBottom: '20px' }}>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
          <Panel title="Nested Panel 1" variant="secondary" size="medium">
            <p>This is a nested panel with secondary variant.</p>
            <BasePanel style={{ backgroundColor: '#3a3a3a', marginTop: '8px' }}>
              This is a base panel inside a nested panel.
            </BasePanel>
          </Panel>
          
          <Panel title="Nested Panel 2" variant="accent" size="medium">
            <p>This is a nested panel with accent variant.</p>
            <Panel title="Deep Nested" variant="dark" size="small" style={{ marginTop: '8px' }}>
              Deep nesting example
            </Panel>
          </Panel>
        </div>
      </Panel>

      {/* Button Demo */}
      <Panel title="Button Variants" variant="secondary" size="large" fullWidth style={{ marginBottom: '20px' }}>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '12px', marginBottom: '16px' }}>
          <Button variant="primary" size="small">Primary Small</Button>
          <Button variant="primary" size="medium">Primary Medium</Button>
          <Button variant="primary" size="large">Primary Large</Button>
        </div>
        
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '12px', marginBottom: '16px' }}>
          <Button variant="secondary">Secondary</Button>
          <Button variant="accent">Accent</Button>
          <Button variant="danger">Danger</Button>
          <Button variant="success">Success</Button>
        </div>
        
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '12px' }}>
          <Button disabled>Disabled</Button>
          <Button fullWidth>Full Width</Button>
          <Button onClick={() => setModalOpen(true)}>Open Modal</Button>
        </div>
      </Panel>

      {/* Input Demo */}
      <Panel title="Input Components" variant="accent" size="large" fullWidth style={{ marginBottom: '20px' }}>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
          <Input
            label="Text Input"
            placeholder="Enter text here..."
            value={inputValue}
            onChange={setInputValue}
            fullWidth
          />
          
          <Input
            label="Password Input"
            type="password"
            placeholder="Enter password..."
            fullWidth
          />
          
          <Input
            label="Number Input"
            type="number"
            placeholder="Enter number..."
            fullWidth
          />
          
          <Input
            label="Email Input"
            type="email"
            placeholder="Enter email..."
            fullWidth
          />
        </div>
      </Panel>

      {/* Progress Bar Demo */}
      <Panel title="Progress Bars" variant="dark" size="large" fullWidth style={{ marginBottom: '20px' }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          <div>
            <p>Primary Progress Bar:</p>
            <ProgressBar value={progressValue} variant="primary" size="large" showLabel fullWidth />
          </div>
          
          <div>
            <p>Secondary Progress Bar:</p>
            <ProgressBar value={75} variant="secondary" size="medium" showLabel fullWidth />
          </div>
          
          <div>
            <p>Accent Progress Bar:</p>
            <ProgressBar value={45} variant="accent" size="small" fullWidth />
          </div>
          
          <div>
            <p>Danger Progress Bar:</p>
            <ProgressBar value={90} variant="danger" size="large" showLabel fullWidth />
          </div>
          
          <div>
            <p>Success Progress Bar:</p>
            <ProgressBar value={30} variant="success" size="medium" fullWidth />
          </div>
          
          <Button onClick={handleProgressChange} style={{ alignSelf: 'flex-start' }}>
            Randomize Progress
          </Button>
        </div>
      </Panel>

      {/* Scroll Bar Demo */}
      <Panel title="Scroll Bar Demo" variant="primary" size="large" fullWidth style={{ marginBottom: '20px' }}>
        <ScrollBar height="200px" fullWidth>
          <div style={{ padding: '16px' }}>
            <h3>Scrollable Content</h3>
            {Array.from({ length: 20 }, (_, i) => (
              <p key={i} style={{ marginBottom: '12px' }}>
                This is scrollable content item {i + 1}. The scrollbar will appear when content exceeds the container height.
                Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.
              </p>
            ))}
          </div>
        </ScrollBar>
      </Panel>

      {/* Tooltip Demo */}
      <Panel title="Tooltip Demo" variant="secondary" size="large" fullWidth style={{ marginBottom: '20px' }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
          <div>
            <h4 style={{ color: '#ffffff', margin: '0 0 12px 0', fontSize: '1rem' }}>Directional Tooltips with Arrows:</h4>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '12px' }}>
              <Tooltip content="⬆️ Tooltip pointing up with arrow" position="top">
                <Button variant="primary">Top Arrow</Button>
              </Tooltip>
              
              <Tooltip content="⬇️ Tooltip pointing down with arrow" position="bottom">
                <Button variant="primary">Bottom Arrow</Button>
              </Tooltip>
              
              <Tooltip content="⬅️ Tooltip pointing left with arrow" position="left">
                <Button variant="primary">Left Arrow</Button>
              </Tooltip>
              
              <Tooltip content="➡️ Tooltip pointing right with arrow" position="right">
                <Button variant="primary">Right Arrow</Button>
              </Tooltip>
            </div>
          </div>

          <div>
            <h4 style={{ color: '#ffffff', margin: '0 0 12px 0', fontSize: '1rem' }}>Custom Styled Tooltips:</h4>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '12px' }}>
              <Tooltip content="🔥 Danger tooltip with red background" style={{ backgroundColor: '#8a2a2a' }}>
                <Button variant="danger">Danger Tooltip</Button>
              </Tooltip>
              
              <Tooltip content="✅ Success tooltip with green background" style={{ backgroundColor: '#2a8a2a' }}>
                <Button variant="success">Success Tooltip</Button>
              </Tooltip>
              
              <Tooltip content="💙 Accent tooltip with blue background" style={{ backgroundColor: '#2a4a8a' }}>
                <Button variant="accent">Accent Tooltip</Button>
              </Tooltip>
            </div>
          </div>

          <div>
            <h4 style={{ color: '#ffffff', margin: '0 0 12px 0', fontSize: '1rem' }}>Interactive Elements:</h4>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '12px', alignItems: 'center' }}>
              <Tooltip content="This input field accepts text input" position="top">
                <Input placeholder="Hover me" size="small" />
              </Tooltip>
              
              <Tooltip content="This progress bar shows completion status" position="bottom">
                <ProgressBar value={65} variant="primary" size="small" />
              </Tooltip>
              
              <Tooltip content="This panel contains grouped content" position="left">
                <Panel title="Hover Me" variant="dark" size="small" style={{ cursor: 'help' }}>
                  <p style={{ margin: 0, fontSize: '0.8rem' }}>Panel content</p>
                </Panel>
              </Tooltip>
            </div>
          </div>
        </div>
      </Panel>

      {/* Modal */}
      <Modal
        isOpen={modalOpen}
        onClose={() => setModalOpen(false)}
        title="Modal Demo"
        size="medium"
      >
        <div style={{ padding: '16px' }}>
          <p>This is a modal dialog. You can close it by clicking the X button, pressing Escape, or clicking outside the modal.</p>
          <p>The modal supports different sizes: small, medium, large, and fullscreen.</p>
          <div style={{ display: 'flex', gap: '12px', marginTop: '20px' }}>
            <Button onClick={() => setModalOpen(false)}>Close</Button>
            <Button variant="secondary" onClick={() => alert('Action performed!')}>
              Perform Action
            </Button>
          </div>
        </div>
      </Modal>
    </div>
  );
};
