import { Team } from "./Team";

export interface Targetable {
  x: number;
  y: number;
  team: Team;
  hp?: number;
  isAlive?: () => boolean;
  // For segmented entities
  isSegmented?: boolean;
  segmentedEntity?: any;
  // For visual representation
  active?: boolean;
}

export interface TargetAcquisitionOptions {
  maxTargets?: number;
  maxRange?: number;
  prioritizeClosest?: boolean;
  includeSegments?: boolean;
  filterFunction?: (target: Targetable) => boolean;
}

export class TargetAcquisition {
  private scene: any;

  constructor(scene: any) {
    this.scene = scene;
  }

  /**
   * Get valid targets for a given entity based on team relationships
   * @param source The entity seeking targets
   * @param options Targeting options
   * @returns Array of valid targets
   */
  getValidTargets(
    source: Targetable,
    options: TargetAcquisitionOptions = {}
  ): Targetable[] {
    const {
      maxTargets = 1,
      maxRange = Infinity,
      prioritizeClosest = true,
      includeSegments = true,
      filterFunction,
    } = options;

    const validTargets: Targetable[] = [];
    const sourceTeam = source.team;

    // Get all potential targets from the scene
    const allTargets = this.getAllTargets();

    // Filter targets based on team relationships and other criteria
    for (const target of allTargets) {
      if (
        !this.isValidTarget(
          source,
          target,
          sourceTeam,
          maxRange,
          filterFunction
        )
      ) {
        continue;
      }

      // Handle segmented entities
      if (includeSegments && target.isSegmented && target.segmentedEntity) {
        const segmentTargets = this.getSegmentTargets(target, source, maxRange);
        validTargets.push(...segmentTargets);
      } else {
        validTargets.push(target);
      }
    }

    // Sort by distance if prioritizing closest
    if (prioritizeClosest) {
      validTargets.sort((a, b) => {
        const distA = this.getDistance(source, a);
        const distB = this.getDistance(source, b);
        return distA - distB;
      });
    }

    // Limit number of targets
    return validTargets.slice(0, maxTargets);
  }

  /**
   * Get the closest target for a given entity
   * @param source The entity seeking a target
   * @param options Targeting options
   * @returns The closest valid target or null
   */
  getClosestTarget(
    source: Targetable,
    options: TargetAcquisitionOptions = {}
  ): Targetable | null {
    const targets = this.getValidTargets(source, {
      ...options,
      maxTargets: 1,
      prioritizeClosest: true,
    });
    return targets.length > 0 ? targets[0] : null;
  }

  /**
   * Get multiple targets for abilities that can target multiple enemies
   * @param source The entity seeking targets
   * @param count Number of targets to find
   * @param options Targeting options
   * @returns Array of targets
   */
  getMultipleTargets(
    source: Targetable,
    count: number,
    options: TargetAcquisitionOptions = {}
  ): Targetable[] {
    return this.getValidTargets(source, {
      ...options,
      maxTargets: count,
      prioritizeClosest: true,
    });
  }

  /**
   * Check if a target is valid for a given source
   */
  private isValidTarget(
    source: Targetable,
    target: Targetable,
    sourceTeam: Team,
    maxRange: number,
    filterFunction?: (target: Targetable) => boolean
  ): boolean {
    // Basic validation
    if (!target || !target.active) return false;
    if (target.hp !== undefined && target.hp <= 0) return false;
    if (target.isAlive && !target.isAlive()) return false;

    // Team relationship check
    if (!this.areTeamsHostile(sourceTeam, target.team)) return false;

    // Range check
    const distance = this.getDistance(source, target);
    if (distance > maxRange) return false;

    // Custom filter function
    if (filterFunction && !filterFunction(target)) return false;

    return true;
  }

  /**
   * Check if two teams are hostile to each other
   */
  private areTeamsHostile(team1: Team, team2: Team): boolean {
    // Friendly units don't attack each other
    if (team1 === Team.Friendly && team2 === Team.Friendly) return false;

    // Enemy units don't attack each other (unless we want friendly fire)
    if (team1 === Team.Enemy && team2 === Team.Enemy) return false;

    // Neutral units don't attack anyone
    if (team1 === Team.Neutral || team2 === Team.Neutral) return false;

    // Friendly vs Enemy and Enemy vs Friendly are hostile
    return true;
  }

  /**
   * Calculate distance between two entities
   */
  private getDistance(source: Targetable, target: Targetable): number {
    const dx = source.x - target.x;
    const dy = source.y - target.y;
    return Math.sqrt(dx * dx + dy * dy);
  }

  /**
   * Get all potential targets from the scene
   */
  private getAllTargets(): Targetable[] {
    const targets: Targetable[] = [];

    // Add enemies
    if (this.scene.enemies) {
      this.scene.enemies.getChildren().forEach((enemy: any) => {
        if (enemy.active) {
          targets.push({
            x: enemy.x,
            y: enemy.y,
            team: Team.Enemy,
            hp: enemy.hp,
            active: enemy.active,
            isSegmented: (enemy as any).isSegmented,
            segmentedEntity: (enemy as any).segmentedEntity,
          });
        }
      });
    }

    // Add player
    if (this.scene.player && this.scene.playerCharacter) {
      targets.push({
        x: this.scene.player.x,
        y: this.scene.player.y,
        team: Team.Friendly,
        hp: this.scene.playerCharacter.hp,
        isAlive: () => this.scene.playerCharacter.isAlive(),
        active: this.scene.player.active,
      });
    }

    // Add friendly units (dummies, etc.)
    if (this.scene.friendlyUnits) {
      this.scene.friendlyUnits.getChildren().forEach((unit: any) => {
        if (unit.active && (unit as any).isDummy) {
          targets.push({
            x: unit.x,
            y: unit.y,
            team: Team.Friendly,
            hp: (unit as any).hp,
            active: unit.active,
          });
        }
      });
    }

    return targets;
  }

  /**
   * Get segment targets for segmented entities
   */
  private getSegmentTargets(
    segmentedTarget: Targetable,
    source: Targetable,
    maxRange: number
  ): Targetable[] {
    if (
      !segmentedTarget.segmentedEntity ||
      !segmentedTarget.segmentedEntity.segments
    ) {
      return [segmentedTarget];
    }

    const segmentTargets: Targetable[] = [];
    const segments = segmentedTarget.segmentedEntity.segments;

    for (const segment of segments) {
      const distance = this.getDistance(source, {
        x: segment.currentX,
        y: segment.currentY,
        team: segmentedTarget.team,
      });
      if (distance <= maxRange) {
        segmentTargets.push({
          x: segment.currentX,
          y: segment.currentY,
          team: segmentedTarget.team,
          hp: segmentedTarget.hp,
          active: segmentedTarget.active,
          isSegmented: true,
          segmentedEntity: segmentedTarget.segmentedEntity,
        });
      }
    }

    return segmentTargets;
  }

  /**
   * Get the closest segment for a segmented entity
   */
  getClosestSegment(
    source: Targetable,
    segmentedTarget: Targetable
  ): Targetable | null {
    if (!segmentedTarget.isSegmented || !segmentedTarget.segmentedEntity) {
      return segmentedTarget;
    }

    const segments = segmentedTarget.segmentedEntity.segments;
    let closestSegment: any = null;
    let closestDistance = Infinity;

    for (const segment of segments) {
      const distance = this.getDistance(source, {
        x: segment.currentX,
        y: segment.currentY,
        team: segmentedTarget.team,
      });
      if (distance < closestDistance) {
        closestDistance = distance;
        closestSegment = segment;
      }
    }

    if (closestSegment) {
      return {
        x: closestSegment.currentX,
        y: closestSegment.currentY,
        team: segmentedTarget.team,
        hp: segmentedTarget.hp,
        active: segmentedTarget.active,
        isSegmented: true,
        segmentedEntity: segmentedTarget.segmentedEntity,
      };
    }

    return null;
  }
}
