import { BaseMovementBehavior } from "./BaseMovementBehavior";
import { Enemy } from "../entities/Enemy";

// Hopping behavior: for frogs, rabbits, etc. - hops with deviation from straight line

export class HopBehavior extends BaseMovementBehavior {
  private hopDistance: number;
  private deviationDistance: number;
  private isHopping: boolean = false;
  private hopTargetX: number = 0;
  private hopTargetY: number = 0;
  private hopStartTime: number = 0;
  private hopDuration: number = 1000; // 1 second hop duration

  constructor(
    attackRange: number,
    moveSpeed: number,
    hopDistance: number = 150,
    deviationDistance: number = 100,
    canAttackWhileMoving: boolean = false
  ) {
    super(attackRange, moveSpeed, canAttackWhileMoving);
    this.hopDistance = hopDistance;
    this.deviationDistance = deviationDistance;
  }

  update(
    enemy: Enemy,
    playerX: number,
    playerY: number,
    deltaTime: number
  ): { targetX: number; targetY: number; shouldAttack: boolean } {
    const shouldAttack = this.shouldAttack(enemy, playerX, playerY);

    // If we can attack, stop moving and attack (regardless of hopping state)
    if (shouldAttack) {
      // If we're currently hopping, stop the hop
      if (this.isHopping) {
        this.isHopping = false;
      }
      return { targetX: enemy.x, targetY: enemy.y, shouldAttack: true };
    }

    // If we're currently hopping, continue the hop
    if (this.isHopping) {
      const currentTime = Date.now();
      const hopProgress = (currentTime - this.hopStartTime) / this.hopDuration;

      // If hop is complete, stop hopping
      if (hopProgress >= 1.0) {
        this.isHopping = false;
        // Calculate next hop target
        this.calculateNextHopTarget(enemy, playerX, playerY);
        return {
          targetX: this.hopTargetX,
          targetY: this.hopTargetY,
          shouldAttack: false,
        };
      }

      // Continue hopping to current target
      return {
        targetX: this.hopTargetX,
        targetY: this.hopTargetY,
        shouldAttack: false,
      };
    }

    // Not hopping and not in attack range - start a new hop
    this.calculateNextHopTarget(enemy, playerX, playerY);
    this.isHopping = true;
    this.hopStartTime = Date.now();

    return {
      targetX: this.hopTargetX,
      targetY: this.hopTargetY,
      shouldAttack: false,
    };
  }

  private calculateNextHopTarget(
    enemy: Enemy,
    playerX: number,
    playerY: number
  ): void {
    // 1. Draw a line between player and creature
    const directionX = playerX - enemy.x;
    const directionY = playerY - enemy.y;
    const distance = Math.sqrt(
      directionX * directionX + directionY * directionY
    );

    // Normalize the direction
    const normalizedDirX = directionX / distance;
    const normalizedDirY = directionY / distance;

    // 2. Select point on that line at hop distance
    const hopPointX = enemy.x + normalizedDirX * this.hopDistance;
    const hopPointY = enemy.y + normalizedDirY * this.hopDistance;

    // 3. Draw perpendicular line for deviation
    const perpX = -normalizedDirY;
    const perpY = normalizedDirX;

    // 4. Select a random point on the deviation line
    const deviationFactor = (Math.random() - 0.5) * 2; // -1 to 1
    const deviationX = perpX * this.deviationDistance * deviationFactor;
    const deviationY = perpY * this.deviationDistance * deviationFactor;

    // Final hop destination
    this.hopTargetX = hopPointX + deviationX;
    this.hopTargetY = hopPointY + deviationY;
  }

  getType(): string {
    return "hop";
  }

  // Get hop info for visualization
  getHopInfo(): {
    isHopping: boolean;
    hopTargetX: number;
    hopTargetY: number;
    hopProgress: number;
  } {
    if (!this.isHopping) {
      return { isHopping: false, hopTargetX: 0, hopTargetY: 0, hopProgress: 0 };
    }

    const currentTime = Date.now();
    const hopProgress = Math.min(
      (currentTime - this.hopStartTime) / this.hopDuration,
      1.0
    );

    return {
      isHopping: true,
      hopTargetX: this.hopTargetX,
      hopTargetY: this.hopTargetY,
      hopProgress,
    };
  }
}
