import React from 'react';
import { toRoman } from './App';
import { MiniTooltip } from './components/ui/MiniTooltip';
import { UPGRADE_COLORS, UPGRADE_ICONS } from './game/upgrades';

// FlipUpgradeCard component with backcard and rotation animation
export const FlipUpgradeCard = ({ upgrade, onClick, level, index, isRevealed }: {
  upgrade: any;
  onClick?: () => void;
  level: number;
  index: number;
  isRevealed: boolean;
}) => {
  const rarity = upgrade.rarity || 1;
  const rarityColors = {
    1: '#ffffff', // White for tier 1
    2: '#ffd700', // Gold for tier 2
    3: '#ff6b6b' // Red for tier 3
  };

  // Calculate font size based on text length to ensure it fits
  const titleText = `${upgrade.name} ${toRoman(level)}`;

  // More aggressive scaling for longer titles (reduced by 20%)
  let fontSize = 1.2; // Base size (was 1.5)
  if (titleText.length > 15) {
    fontSize = 1.04;
  }
  if (titleText.length > 20) {
    fontSize = 0.88;
  }
  if (titleText.length > 25) {
    fontSize = 0.72;
  }
  if (titleText.length > 30) {
    fontSize = 0.64;
  }

  return (
    <div className={`flip-card ${isRevealed ? 'revealed' : ''}`}>
      {/* Backcard */}
      <div className="flip-card-back" onClick={onClick}>
        <div style={{
          width: '100%',
          height: '100%',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          padding: '1rem',
          boxSizing: 'border-box',
          position: 'relative',
        }}>
          {/* Mystery icon */}
          <div style={{
            fontSize: '3.5rem',
            marginBottom: '1.5rem',
            color: '#666',
            textShadow: '0 0 15px rgba(255,255,255,0.4)',
            animation: 'pulse 2s ease-in-out infinite',
          }}>
            ❓
          </div>

          {/* Mystery text */}
          <div style={{
            fontSize: '1.3rem',
            fontWeight: 700,
            color: '#999',
            textAlign: 'center',
            marginBottom: '1rem',
            letterSpacing: '0.1em',
            textShadow: '0 2px 4px rgba(0,0,0,0.5)',
          }}>
            MYSTERY UPGRADE
          </div>

          {/* Click to reveal */}
          <div style={{
            fontSize: '0.9rem',
            color: '#777',
            textAlign: 'center',
            fontStyle: 'italic',
            marginBottom: '1rem',
            textShadow: '0 1px 2px rgba(0,0,0,0.3)',
          }}>
            Click to reveal
          </div>

          {/* Decorative border pattern */}
          <div style={{
            position: 'absolute',
            top: '0.5rem',
            left: '0.5rem',
            right: '0.5rem',
            bottom: '0.5rem',
            border: '1px solid #555',
            borderRadius: '6px',
            opacity: 0.3,
            pointerEvents: 'none',
          }} />

          {/* Corner decorative elements */}
          <div style={{
            position: 'absolute',
            top: '1rem',
            left: '1rem',
            fontSize: '1.2rem',
            color: '#555',
            zIndex: 1,
            pointerEvents: 'none'
          }}>
            ✦
          </div>
          <div style={{
            position: 'absolute',
            top: '1rem',
            right: '1rem',
            fontSize: '1.2rem',
            color: '#555',
            zIndex: 1,
            pointerEvents: 'none'
          }}>
            ✦
          </div>
          <div style={{
            position: 'absolute',
            bottom: '1rem',
            left: '1rem',
            fontSize: '1.2rem',
            color: '#555',
            zIndex: 1,
            pointerEvents: 'none'
          }}>
            ✦
          </div>
          <div style={{
            position: 'absolute',
            bottom: '1rem',
            right: '1rem',
            fontSize: '1.2rem',
            color: '#555',
            zIndex: 1,
            pointerEvents: 'none'
          }}>
            ✦
          </div>
        </div>
      </div>

      {/* Front card (upgrade content) */}
      <div
        className="flip-card-front"
        style={{
          background: `linear-gradient(15deg, ${UPGRADE_COLORS[upgrade.category as keyof typeof UPGRADE_COLORS]}33 0%, #23232b 100%), #23232b`
        }}
      >
        <MiniTooltip content={upgrade.longdescription || 'No description available'} upgrade={upgrade}>
          <div
            style={{
              width: '100%',
              height: '100%',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              gap: '0.7rem',
              padding: '0.3rem 0.7rem 1rem 0.7rem',
              boxSizing: 'border-box',
              justifyContent: 'flex-start',
              cursor: 'pointer',
              position: 'relative',
            }}
            onClick={onClick ? onClick : undefined}
            role="button"
            tabIndex={0}
            onKeyDown={(e) => { if ((e.key === 'Enter' || e.key === ' ') && onClick) onClick(); }}
          >
            {/* Rarity stars - centered at top */}
            <div style={{
              position: 'absolute',
              left: '50%',
              top: '0.5rem',
              transform: 'translateX(-50%)',
              display: 'flex',
              gap: '2px',
              fontSize: '1.2rem',
              zIndex: 1,
              pointerEvents: 'none'
            }}>
              {Array.from({ length: rarity }, (_, i) => (
                <span key={i} style={{ color: rarityColors[rarity as keyof typeof rarityColors] }}>
                  ⭐
                </span>
              ))}
            </div>

            <div style={{
              fontWeight: 700,
              color: UPGRADE_COLORS[upgrade.category as keyof typeof UPGRADE_COLORS],
              fontSize: `${fontSize}rem`,
              marginBottom: '0.2rem',
              marginTop: '2rem',
              textAlign: 'center',
              width: '100%',
              lineHeight: '1.2',
              height: '1.8rem',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              whiteSpace: 'nowrap',
              paddingLeft: '8px',
              paddingRight: '8px'
            }}>{titleText}</div>
            <div style={{
              fontSize: '0.65rem',
              fontWeight: '700',
              background: UPGRADE_COLORS[upgrade.category as keyof typeof UPGRADE_COLORS],
              color: '#111',
              borderRadius: 4,
              padding: '1px 5px',
              marginBottom: '0.5rem',
              marginTop: 0,
              letterSpacing: '0.04em',
              alignSelf: 'center',
              boxShadow: '0 1px 4px #0002',
              border: '1px solid #fff2',
              display: 'inline-block',
              height: '1rem',
              lineHeight: '1rem'
            }}>{upgrade.category}</div>
            <div style={{
              fontSize: '2rem',
              height: '2rem',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              marginBottom: '0.5rem'
            }}>{UPGRADE_ICONS[upgrade.name] || '✨'}</div>
            <div style={{
              fontSize: '0.95rem',
              color: '#fff',
              textAlign: 'center',
              marginTop: 0,
              flex: 1,
              display: 'flex',
              alignItems: 'flex-start',
              justifyContent: 'center',
              paddingLeft: '8px',
              paddingRight: '8px',
              minHeight: '3rem'
            }}>{upgrade.shortdescription}</div>
          </div>
        </MiniTooltip>
      </div>
    </div>
  );
};
