import { Team } from "../game/Team";

export class Character {
  hp: number;
  maxHp: number;
  armor: number;
  maxArmor?: number; // Maximum armor capacity
  moveSpeed: number;
  xp: number;
  level: number;
  xpToNext: number;
  team: Team;
  // Attack stats
  attackDamage: number;
  attackSpeed: number; // attacks per second
  attackRange: number; // distance at which they can attack
  lastAttackTime: number;
  // Melee attack stats
  meleeRange: number; // melee attack range
  meleeDamage: number; // additional melee damage
  meleeConeAngle: number; // melee attack cone angle in degrees
  lastMeleeTime: number;
  // Additional stats
  magicResist: number; // reduces magic damage
  magicPower: number; // increases magic damage dealt
  cooldown: number; // reduces ability cooldowns (percentage)
  aoe: number; // area of effect multiplier
  projectileSpeed: number; // speed of projectiles
  projectileScale: number; // size multiplier for projectiles
  // Combat mechanics as stats
  burstFire: number; // additional shots per burst
  critChance: number; // critical hit chance
  critLevel: number; // critical hit multiplier level
  lifesteal: number; // lifesteal percentage
  // Player-specific upgrade properties
  shotgun?: number; // shotgun upgrade level
  dualBerettas?: boolean; // dual berettas item effect
  pierce?: number; // piercing bullets upgrade level
  ricochet?: number; // ricochet upgrade level
  explosive?: boolean; // explosive rounds upgrade
  homing?: boolean; // homing bullets upgrade
  pureChance?: number; // pure chance upgrade level
  bloodlettingBlades?: number; // Bloodletting Blades upgrade level
  heavyStrikes?: number; // Heavy Strikes upgrade level
  arcaneEdge?: number; // Arcane Edge upgrade level
  magicLeech?: number; // Magic Leech upgrade level
  chillingTouch?: number; // Chilling Touch upgrade level
  punchOfHealth?: number; // Punch of Health upgrade level
  meleeKnockback?: number; // Melee Knockback upgrade level
  midasTouch?: number; // Midas Touch upgrade level
  boxer?: number; // Boxer upgrade level
  // Defensive stats
  regen: number; // health regeneration per second
  evasion: number; // chance to dodge attacks (percentage)
  // Utility stats
  xpBoost: number; // XP gain multiplier
  magnet: number; // magnet range multiplier
  luck: number; // luck bonus for upgrades
  goldFind: number; // gold find multiplier
  gold: number; // gold currency
  augmentedHealing: number; // healing amplification multiplier

  // Base stats for scaling calculations
  baseMaxHp: number;
  baseAttackDamage: number;
  baseMoveSpeed: number;
  baseArmor: number;
  baseAttackSpeed: number;
  baseProjectileSpeed: number;
  baseProjectileScale: number;

  // Player stat scaling constants (additive per level)
  static readonly PLAYER_SCALING = {
    HEALTH: 25, // +25 health per level (nerfed from 50)
    ATTACK_DAMAGE: 3, // +3 attack damage per level (nerfed from 6)
    MOVE_SPEED: 0.02, // +0.02 move speed per level (nerfed from 0.04)
    ARMOR: 0.15, // +0.15 armor per level (nerfed from 0.3)
    ATTACK_SPEED: 0.012, // +0.012 attack speed per level (nerfed from 0.024)
    PROJECTILE_SPEED: 0.04, // +0.04 projectile speed per level (nerfed from 0.08)
    PROJECTILE_SCALE: 0.002, // +0.002 projectile scale per level (nerfed from 0.005)
  };

  // Item system properties
  items: string[] = []; // Array of item names this character has
  itemStacks: Record<string, number> = {}; // Track stack counts for stackable items
  itemCooldowns: Record<string, number> = {}; // Track cooldowns for consumable items

  constructor(
    hp: number = 100,
    armor: number = 0,
    moveSpeed: number = 1,
    team: Team = Team.Friendly,
    attackDamage: number = 0,
    attackSpeed: number = 0,
    attackRange: number = 200,
    meleeRange: number = 0,
    meleeDamage: number = 30,
    magicResist: number = 0,
    magicPower: number = 0,
    cooldown: number = 0,
    aoe: number = 1,
    projectileSpeed: number = 4,
    projectileScale: number = 1,
    burstFire: number = 0,
    critChance: number = 0,
    critLevel: number = 0,
    lifesteal: number = 0,
    regen: number = 0,
    evasion: number = 0,
    xpBoost: number = 1,
    magnet: number = 1,
    luck: number = 0,
    goldFind: number = 1,
    augmentedHealing: number = 0,
    meleeConeAngle: number = 30
  ) {
    this.hp = hp;
    this.maxHp = hp;
    this.armor = armor;
    this.maxArmor = armor; // Initialize maxArmor to current armor value
    this.moveSpeed = moveSpeed;
    this.xp = 0;
    this.level = 1;
    this.xpToNext = 25;
    this.team = team;
    this.attackDamage = attackDamage;
    this.attackSpeed = attackSpeed;
    this.attackRange = attackRange;
    this.lastAttackTime = 0;
    this.meleeRange = meleeRange;
    this.meleeDamage = meleeDamage;
    this.lastMeleeTime = 0;
    this.magicResist = magicResist;
    this.magicPower = magicPower;
    this.cooldown = cooldown;
    this.aoe = aoe;
    this.projectileSpeed = projectileSpeed;
    this.projectileScale = projectileScale;
    this.burstFire = burstFire;
    this.critChance = critChance;
    this.critLevel = critLevel;
    this.lifesteal = lifesteal;
    this.regen = regen;
    this.evasion = evasion;
    this.xpBoost = xpBoost;
    this.magnet = magnet;
    this.luck = luck;
    this.goldFind = goldFind;
    this.augmentedHealing = augmentedHealing;
    this.meleeConeAngle = meleeConeAngle;
    this.gold = 0; // Initialize gold to 0

    // Store base stats for scaling calculations
    this.baseMaxHp = hp;
    this.baseAttackDamage = attackDamage;
    this.baseMoveSpeed = moveSpeed;
    this.baseArmor = armor;
    this.baseAttackSpeed = attackSpeed;
    this.baseProjectileSpeed = projectileSpeed;
    this.baseProjectileScale = projectileScale;
  }

  /**
   * Calculates the scaled value for a stat based on the character's level
   * @param baseValue The base value of the stat
   * @param scalingFactor The additive amount per level
   * @returns The scaled value
   */
  private calculateScaledStat(
    baseValue: number,
    scalingFactor: number
  ): number {
    if (this.team !== Team.Friendly || this.level <= 1) {
      return baseValue; // No scaling for enemies or level 1
    }

    // Apply additive scaling: baseValue + (scalingFactor * (level - 1))
    return baseValue + scalingFactor * (this.level - 1);
  }

  /**
   * Applies level-based scaling to player stats
   * This should be called whenever the player levels up
   */
  applyLevelScaling() {
    if (this.team !== Team.Friendly) {
      return; // Only apply scaling to player characters
    }

    // Calculate scaled stats
    const scaledMaxHp = this.calculateScaledStat(
      this.baseMaxHp,
      Character.PLAYER_SCALING.HEALTH
    );
    const scaledAttackDamage = this.calculateScaledStat(
      this.baseAttackDamage,
      Character.PLAYER_SCALING.ATTACK_DAMAGE
    );
    const scaledMoveSpeed = this.calculateScaledStat(
      this.baseMoveSpeed,
      Character.PLAYER_SCALING.MOVE_SPEED
    );
    const scaledArmor = this.calculateScaledStat(
      this.baseArmor,
      Character.PLAYER_SCALING.ARMOR
    );
    const scaledAttackSpeed = this.calculateScaledStat(
      this.baseAttackSpeed,
      Character.PLAYER_SCALING.ATTACK_SPEED
    );
    const scaledProjectileSpeed = this.calculateScaledStat(
      this.baseProjectileSpeed,
      Character.PLAYER_SCALING.PROJECTILE_SPEED
    );
    const scaledProjectileScale = this.calculateScaledStat(
      this.baseProjectileScale,
      Character.PLAYER_SCALING.PROJECTILE_SCALE
    );

    // Calculate health percentage before scaling
    const healthPercentage = this.hp / this.maxHp;

    // Apply scaled stats
    this.maxHp = scaledMaxHp;
    this.attackDamage = scaledAttackDamage;
    this.moveSpeed = scaledMoveSpeed;
    this.armor = scaledArmor;
    this.attackSpeed = scaledAttackSpeed;
    this.projectileSpeed = scaledProjectileSpeed;
    this.projectileScale = scaledProjectileScale;

    // Scale current HP proportionally to maintain the same health percentage
    this.hp = Math.min(this.maxHp, Math.round(this.maxHp * healthPercentage));
  }

  /**
   * Gets the current scaled value for a specific stat
   * @param statName The name of the stat to get
   * @returns The current scaled value
   */
  getScaledStat(statName: string): number {
    switch (statName) {
      case "maxHp":
        return this.calculateScaledStat(
          this.baseMaxHp,
          Character.PLAYER_SCALING.HEALTH
        );
      case "attackDamage":
        return this.calculateScaledStat(
          this.baseAttackDamage,
          Character.PLAYER_SCALING.ATTACK_DAMAGE
        );
      case "moveSpeed":
        return this.calculateScaledStat(
          this.baseMoveSpeed,
          Character.PLAYER_SCALING.MOVE_SPEED
        );
      case "armor":
        return this.calculateScaledStat(
          this.baseArmor,
          Character.PLAYER_SCALING.ARMOR
        );
      case "attackSpeed":
        return this.calculateScaledStat(
          this.baseAttackSpeed,
          Character.PLAYER_SCALING.ATTACK_SPEED
        );
      case "projectileSpeed":
        return this.calculateScaledStat(
          this.baseProjectileSpeed,
          Character.PLAYER_SCALING.PROJECTILE_SPEED
        );
      case "projectileScale":
        return this.calculateScaledStat(
          this.baseProjectileScale,
          Character.PLAYER_SCALING.PROJECTILE_SCALE
        );
      default:
        return 0;
    }
  }

  /**
   * Gets scaling information for display purposes
   * @returns Object containing scaling amounts and descriptions
   */
  getScalingInfo() {
    return {
      health: {
        multiplier: Character.PLAYER_SCALING.HEALTH,
        description: `+${Character.PLAYER_SCALING.HEALTH} per level`,
      },
      attackDamage: {
        multiplier: Character.PLAYER_SCALING.ATTACK_DAMAGE,
        description: `+${Character.PLAYER_SCALING.ATTACK_DAMAGE} per level`,
      },
      moveSpeed: {
        multiplier: Character.PLAYER_SCALING.MOVE_SPEED,
        description: `+${Character.PLAYER_SCALING.MOVE_SPEED} per level`,
      },
      armor: {
        multiplier: Character.PLAYER_SCALING.ARMOR,
        description: `+${Character.PLAYER_SCALING.ARMOR} per level`,
      },
      attackSpeed: {
        multiplier: Character.PLAYER_SCALING.ATTACK_SPEED,
        description: `+${Character.PLAYER_SCALING.ATTACK_SPEED} per level`,
      },
      projectileSpeed: {
        multiplier: Character.PLAYER_SCALING.PROJECTILE_SPEED,
        description: `+${Character.PLAYER_SCALING.PROJECTILE_SPEED} per level`,
      },
      projectileScale: {
        multiplier: Character.PLAYER_SCALING.PROJECTILE_SCALE,
        description: `+${Character.PLAYER_SCALING.PROJECTILE_SCALE} per level`,
      },
    };
  }

  /**
   * Applies damage to the character, with armor absorbing half the damage (up to the armor value).
   * @param damage The incoming damage value
   * @param isMagicDamage Whether this is magic damage (affected by magic resist)
   * @param ignoreEvasion Whether to ignore evasion (for True Hit upgrade)
   * @returns The actual damage dealt to HP, or -1 if attack was evaded
   */
  takeDamage(
    damage: number,
    isMagicDamage: boolean = false,
    ignoreEvasion: boolean = false,
    evasionBonus: number = 0
  ): number {
    // Check for evasion first
    const totalEvasion = this.evasion + evasionBonus;
    if (!ignoreEvasion && totalEvasion > 0) {
      const evasionRoll = Math.random();
      if (evasionRoll < totalEvasion) {
        return -1; // Attack was evaded
      }
    }

    let finalDamage = damage;

    // Apply magic resist if it's magic damage
    if (isMagicDamage && this.magicResist > 0) {
      finalDamage = Math.max(1, damage - this.magicResist);
    }

    // Armor absorbs up to half the damage, but not more than the current armor value
    const armorAbsorb = Math.min(this.armor, finalDamage / 2);
    this.armor -= armorAbsorb;
    const hpDamage = finalDamage - armorAbsorb;
    this.hp -= hpDamage;
    return hpDamage;
  }

  /**
   * Heals the character by the specified amount.
   * @param amount The amount to heal
   * @param maxHp The maximum HP to heal up to (defaults to current maxHp)
   * @returns The actual amount healed
   */
  heal(amount: number, maxHp?: number): number {
    // Apply Augmented Healing amplification
    let amplifiedAmount = amount;
    if (this.augmentedHealing && this.augmentedHealing > 0) {
      const amplificationPercent = 0.1 + (this.augmentedHealing - 1) * 0.1; // 10% base + 10% per level
      amplifiedAmount = amount * (1 + amplificationPercent);
      console.log(`Augmented Healing: ${amount} -> ${amplifiedAmount.toFixed(1)} (${amplificationPercent * 100}% amplification)`);
    }

    const oldHp = this.hp;
    const maxHealth = maxHp || this.maxHp || 100;
    this.hp = Math.min(maxHealth, this.hp + amplifiedAmount);
    return this.hp - oldHp;
  }

  isAlive(): boolean {
    return this.hp > 0;
  }

  gainXP(amount: number) {
    this.xp += amount;
    while (this.xp >= this.xpToNext) {
      this.xp -= this.xpToNext;
      this.level++;
      // New XP formula: XPn = 30 + n² + 5n
      this.xpToNext = 30 + this.level * this.level + 5 * this.level;

      // Apply level scaling for player characters
      if (this.team === Team.Friendly) {
        this.applyLevelScaling();
      }
    }
  }

  gainGold(amount: number) {
    let goldAmount = amount;
    if (this.goldFind) {
      goldAmount = Math.floor(goldAmount * this.goldFind);
    }
    this.gold += goldAmount;
  }

  /**
   * Applies an upgrade to the character based on the upgrade name.
   * This method handles the actual stat modifications for upgrades.
   * @param upgradeName The name of the upgrade to apply
   */
  applyUpgrade(upgradeName: string) {
    switch (upgradeName) {
      case "Rapid Fire":
        // Handled by the upgrade system directly
        break;
      case "Burst Fire":
        this.burstFire = (this.burstFire || 0) + 1;
        break;
      case "Big Bullets":
        this.projectileScale = (this.projectileScale || 1) * 1.2;
        break;
      case "Lifesteal":
        this.lifesteal = (this.lifesteal || 0) + 0.015; // 1.5% lifesteal per level (nerfed from 3%)
        break;
      case "Armor Up":
        // Add 200 to max armor capacity instead of current armor
        const oldMaxArmor = this.maxArmor || this.armor;
        if (!this.maxArmor) {
          this.maxArmor = this.armor; // Initialize maxArmor if not set
        }
        this.maxArmor += 200;
        // Also increase current armor up to the new maximum
        const oldArmor = this.armor;
        this.armor = Math.min(this.maxArmor, this.armor + 200);

        console.log(`Armor Up applied:`);
        console.log(`  Max Armor: ${oldMaxArmor} → ${this.maxArmor}`);
        console.log(`  Current Armor: ${oldArmor} → ${this.armor}`);
        break;
      case "Regeneration":
        this.regen = (this.regen || 0) + 5; // 5 HP per second
        break;
      case "Max Health Up":
        this.maxHp += 250; // +250 max HP per level
        this.hp += 250; // Also heal the character to the new maximum
        break;
      case "Move Speed Up":
        this.moveSpeed += 1;
        break;
      case "XP Boost":
        this.xpBoost = (this.xpBoost || 1) * 1.25; // 25% XP boost
        break;
      case "Magnet":
        this.magnet = (this.magnet || 1) * 1.5; // 50% magnet range increase
        break;
      case "Cooldown Reduction":
        this.cooldown = (this.cooldown || 0) + 20; // 20% cooldown reduction
        break;
      case "Area Up":
        this.aoe = (this.aoe || 1) * 1.4; // 40% area increase
        break;
      case "Luck Up":
        this.luck = (this.luck || 0) + 1;
        break;
      case "Gold Find":
        this.goldFind = (this.goldFind || 1) * 1.2; // 20% gold find increase
        break;
      case "Elusive":
        this.evasion = (this.evasion || 0) + 0.04; // 4% evasion
        break;
      case "Wide Melee":
        this.meleeConeAngle = (this.meleeConeAngle || 30) + 15; // +15 degrees per level
        break;
      case "Stronk":
        this.meleeDamage = (this.meleeDamage || 30) + 20; // +20 melee damage per level
        break;
      default:
        console.warn(`Unknown upgrade: ${upgradeName}`);
        break;
    }
  }

  /**
   * Adds an item to the character and applies its effects.
   * @param itemName The name of the item to add
   * @param scene The Phaser scene (for item effects that need scene access)
   * @param maxStack Maximum stack count for stackable items
   * @returns True if the item was successfully added
   */
  addItem(itemName: string, scene?: any, maxStack?: number): boolean {
    // Check if item is already owned (for non-stackable items)
    if (!maxStack && this.items.includes(itemName)) {
      return false; // Already have this item
    }

    // For stackable items
    if (maxStack) {
      const currentStack = this.itemStacks[itemName] || 0;
      if (currentStack >= maxStack) {
        return false; // Already at max stack
      }
      this.itemStacks[itemName] = currentStack + 1;
    }

    // Add to items array if not already there
    if (!this.items.includes(itemName)) {
      this.items.push(itemName);
    }

    // Apply item effects if scene is provided
    if (scene) {
      const { ITEMS } = require('../game/items');
      const item = ITEMS.find((i: any) => i.name === itemName);
      if (item) {
        item.apply(scene, this);
      }
    }

    return true;
  }

  /**
   * Removes an item from the character and removes its effects.
   * @param itemName The name of the item to remove
   * @param scene The Phaser scene (for item effects that need scene access)
   * @returns True if the item was successfully removed
   */
  removeItem(itemName: string, scene?: any): boolean {
    const itemIndex = this.items.indexOf(itemName);
    if (itemIndex === -1) {
      return false; // Item not found
    }

    // Remove from items array
    this.items.splice(itemIndex, 1);

    // Remove from stacks if it exists
    if (this.itemStacks[itemName]) {
      this.itemStacks[itemName] = Math.max(0, this.itemStacks[itemName] - 1);
      if (this.itemStacks[itemName] === 0) {
        delete this.itemStacks[itemName];
      }
    }

    // Remove item effects if scene is provided
    if (scene) {
      const { ITEMS } = require('../game/items');
      const item = ITEMS.find((i: any) => i.name === itemName);
      if (item && item.remove) {
        item.remove(scene, this);
      }
    }

    return true;
  }

  /**
   * Checks if the character has a specific item.
   * @param itemName The name of the item to check
   * @returns True if the character has the item
   */
  hasItem(itemName: string): boolean {
    return this.items.includes(itemName);
  }

  /**
   * Gets the stack count for a specific item.
   * @param itemName The name of the item
   * @returns The stack count (0 if not owned)
   */
  getItemStack(itemName: string): number {
    return this.itemStacks[itemName] || 0;
  }

  /**
   * Gets all items owned by this character.
   * @returns Array of item names
   */
  getItems(): string[] {
    return [...this.items];
  }

  /**
   * Consumes a consumable item if available and not on cooldown.
   * @param itemName The name of the consumable item
   * @param scene The Phaser scene
   * @returns True if the item was successfully consumed
   */
  consumeItem(itemName: string, scene?: any): boolean {
    if (!this.hasItem(itemName)) {
      return false;
    }

    // Check cooldown
    const cooldown = this.itemCooldowns[itemName];
    if (cooldown && cooldown > 0) {
      return false; // Item is on cooldown
    }

    // Apply item effect
    if (scene) {
      const { ITEMS } = require('../game/items');
      const item = ITEMS.find((i: any) => i.name === itemName);
      if (item && item.apply) {
        item.apply(scene, this);

        // For consumable items, remove after use
        if (item.isConsumable) {
          this.removeItem(itemName, scene);
        }

        return true;
      }
    }

    return false;
  }

  /**
   * Updates item cooldowns. Should be called every frame.
   * @param deltaTime Time elapsed since last update
   */
  updateItemCooldowns(deltaTime: number) {
    for (const itemName in this.itemCooldowns) {
      if (this.itemCooldowns[itemName] > 0) {
        this.itemCooldowns[itemName] -= deltaTime;
        if (this.itemCooldowns[itemName] <= 0) {
          delete this.itemCooldowns[itemName];
        }
      }
    }
  }

  /**
   * Centralized shooting method that can be used by both player and enemy
   * @param scene The Phaser scene
   * @param shooter The shooting entity (player or enemy)
   * @param targetX Target X coordinate
   * @param targetY Target Y coordinate
   * @param options Configuration options for the shot
   */
  shootAtTarget(
    scene: any,
    shooter: any,
    targetX: number,
    targetY: number,
    options: {
      bulletGroup?: Phaser.GameObjects.Group;
      bulletColor?: number;
      bulletSpeed?: number;
      bulletScale?: number;
      damage?: number;
      isEnemyBullet?: boolean;
      enableUpgrades?: boolean;
      burstDelay?: number;
    } = {}
  ) {
    const {
      bulletGroup = scene.bullets,
      bulletColor = 0xffff44,
      bulletSpeed = this.projectileSpeed || 8,
      bulletScale = this.projectileScale || 1,
      damage = this.attackDamage || 8,
      isEnemyBullet = false,
      enableUpgrades = false,
      burstDelay = 200,
    } = options;

    // Store target coordinates for potential re-acquisition after animation
    const originalTargetX = targetX;
    const originalTargetY = targetY;

    // Determine number of shots (burst fire for player)
    const burstLevel = enableUpgrades ? this.burstFire || 0 : 0;
    const totalShots = 1 + burstLevel;

    // Check for shotgun upgrade (player only)
    const shotgunLevel = enableUpgrades ? this.shotgun || 0 : 0;

    // Check for Dual Berettas item (player only)
    const hasDualBerettas = enableUpgrades && this.dualBerettas;

    // Add anticipation animation before shooting
    this.playShootingAnticipation(scene, shooter, () => {
      // Re-acquire target after animation to get updated coordinates
      let finalTargetX = originalTargetX;
      let finalTargetY = originalTargetY;

      // For enemies, try to re-acquire the player target
      if (isEnemyBullet && scene.targetAcquisition) {
        const updatedTarget = scene.targetAcquisition.getClosestTarget(
          { x: shooter.x, y: shooter.y, team: this.team },
          { maxRange: Infinity }
        );
        if (updatedTarget) {
          finalTargetX = updatedTarget.x;
          finalTargetY = updatedTarget.y;
        }
      }

      // Calculate updated angle to target after animation
      const baseAngle = Phaser.Math.Angle.Between(
        shooter.x,
        shooter.y,
        finalTargetX,
        finalTargetY
      );

      // Fire each shot with delay for burst fire
      for (let i = 0; i < totalShots; i++) {
        scene.time.delayedCall(i * burstDelay, () => {
          if (!shooter.active || !bulletGroup) return;

          // Check if shotgun upgrade is active (every shot should be shotgun if you have the upgrade)
          const isShotgun = shotgunLevel > 0;

          if (isShotgun) {
            // Shotgun: multiple bullets in a cone
            const coneBullets = 3 + (shotgunLevel - 1) * 2;
            const coneSpread =
              Math.PI / 6 + ((shotgunLevel - 1) * Math.PI) / 24;

            for (let b = 0; b < coneBullets; b++) {
              let angle = baseAngle;
              if (coneBullets > 1) {
                angle =
                  baseAngle -
                  coneSpread / 2 +
                  (coneSpread * b) / (coneBullets - 1);
              }

              this.createBullet(scene, shooter, angle, {
                bulletGroup,
                bulletColor,
                bulletSpeed,
                bulletScale,
                damage,
                isEnemyBullet,
                enableUpgrades,
                isMiddleBullet: b === Math.floor(coneBullets / 2),
              });
            }
          } else if (hasDualBerettas) {
            // Dual Berettas: two bullets side by side
            const spreadAngle = Math.PI / 96; // Reduced spread between bullets

            this.createBullet(scene, shooter, baseAngle - spreadAngle, {
              bulletGroup,
              bulletColor,
              bulletSpeed,
              bulletScale,
              damage: Math.floor(damage * 0.75), // 75% damage each
              isEnemyBullet,
              enableUpgrades,
            });

            this.createBullet(scene, shooter, baseAngle + spreadAngle, {
              bulletGroup,
              bulletColor,
              bulletSpeed,
              bulletScale,
              damage: Math.floor(damage * 0.75), // 75% damage each
              isEnemyBullet,
              enableUpgrades,
            });
          } else {
            // Single bullet
            this.createBullet(scene, shooter, baseAngle, {
              bulletGroup,
              bulletColor,
              bulletSpeed,
              bulletScale,
              damage,
              isEnemyBullet,
              enableUpgrades,
            });
          }
        });
      }
    });
  }

  /**
   * Plays a shooting anticipation animation before the actual shot
   * Character plays "20% deflate then inflate back" animation
   */
  private playShootingAnticipation(
    scene: any,
    shooter: any,
    onComplete: () => void
  ) {
    // Store original scale - always use the base scale, not current scale
    const originalScaleX = (shooter as any).originalScaleX || shooter.scaleX;
    const originalScaleY = (shooter as any).originalScaleY || shooter.scaleY;

    // Store original scale if not already stored
    if (!(shooter as any).originalScaleX) {
      (shooter as any).originalScaleX = shooter.scaleX;
      (shooter as any).originalScaleY = shooter.scaleY;
    }

    // Calculate anticipation scale (20% smaller for deflate)
    const deflateScale = 0.8;

    // Use simple tweens instead of timeline for compatibility
    scene.tweens.add({
      targets: shooter,
      scaleX: originalScaleX * deflateScale,
      scaleY: originalScaleY * deflateScale,
      duration: 300,
      ease: "Power2",
      onComplete: () => {
        // Quick inflate back to original size
        scene.tweens.add({
          targets: shooter,
          scaleX: originalScaleX,
          scaleY: originalScaleY,
          duration: 100,
          ease: "Power2",
          onComplete: onComplete,
        });
      },
    });
  }

  /**
   * Creates a single bullet with the specified parameters
   */
  private createBullet(
    scene: any,
    shooter: any,
    angle: number,
    options: {
      bulletGroup: Phaser.GameObjects.Group;
      bulletColor: number;
      bulletSpeed: number;
      bulletScale: number;
      damage: number;
      isEnemyBullet: boolean;
      enableUpgrades: boolean;
      isMiddleBullet?: boolean;
    }
  ) {
    const {
      bulletGroup,
      bulletColor,
      bulletSpeed,
      bulletScale,
      damage,
      isEnemyBullet,
      enableUpgrades,
      isMiddleBullet = true,
    } = options;

    // Calculate bullet radius with enhanced damage-based scaling
    // Updated for more reasonable 1.15 scaling progression
    let damageScaleFactor;

    if (damage <= 50) {
      // Very low damage: 0.25x to 0.5x
      damageScaleFactor = 0.25 + (damage / 50) * 0.25;
    } else if (damage <= 150) {
      // Low damage: 0.5x to 0.9x
      damageScaleFactor = 0.5 + ((damage - 50) / 100) * 0.4;
    } else if (damage <= 300) {
      // Medium damage: 0.9x to 1.4x
      damageScaleFactor = 0.9 + ((damage - 150) / 150) * 0.5;
    } else if (damage <= 600) {
      // High damage: 1.4x to 2.0x
      damageScaleFactor = 1.4 + ((damage - 300) / 300) * 0.6;
    } else if (damage <= 1200) {
      // Very high damage: 2.0x to 3.0x
      damageScaleFactor = 2.0 + ((damage - 600) / 600) * 1.0;
    } else if (damage <= 2500) {
      // Extreme damage: 3.0x to 4.25x
      damageScaleFactor = 3.0 + ((damage - 1200) / 1300) * 1.25;
    } else if (damage <= 5000) {
      // Massive damage: 4.25x to 5.5x
      damageScaleFactor = 4.25 + ((damage - 2500) / 2500) * 1.25;
    } else if (damage <= 15000) {
      // Colossal damage: 5.5x to 7.0x
      damageScaleFactor = 5.5 + ((damage - 5000) / 10000) * 1.5;
    } else if (damage <= 50000) {
      // Astronomical damage: 7.0x to 8.5x
      damageScaleFactor = 7.0 + ((damage - 15000) / 35000) * 1.5;
    } else {
      // Maximum damage: 8.5x (capped for performance)
      damageScaleFactor = 8.5;
    }

    // Reduced base size for more reasonable scaling
    const bulletRadius = bulletScale * 4 * damageScaleFactor;

    // Calculate visual enhancements based on damage
    let enhancedColor = bulletColor;
    let glowIntensity = 0;
    let strokeColor = 0xffffff;

    // Color and glow enhancement based on damage
    if (damage > 5000) {
      // Colossal damage: bright red/orange glow
      const colorObj = Phaser.Display.Color.ValueToColor(bulletColor);
      colorObj.red = Math.min(255, colorObj.red + 60);
      colorObj.green = Math.max(0, colorObj.green - 40);
      enhancedColor = colorObj.color;
      glowIntensity = Math.min(4, 2 + (damage - 5000) / 5000);
      strokeColor = 0xff6600; // Bright orange stroke for colossal damage
    } else if (damage > 2000) {
      // High damage: add red/orange tint and glow
      const colorObj = Phaser.Display.Color.ValueToColor(bulletColor);
      colorObj.red = Math.min(255, colorObj.red + 50);
      colorObj.green = Math.max(0, colorObj.green - 30);
      enhancedColor = colorObj.color;
      glowIntensity = Math.min(3, (damage - 2000) / 3000);
      strokeColor = 0xffaa00; // Orange stroke for high damage
    } else if (damage > 500) {
      // Medium damage: slight yellow tint
      const colorObj = Phaser.Display.Color.ValueToColor(bulletColor);
      colorObj.red = Math.min(255, colorObj.red + 20);
      colorObj.green = Math.min(255, colorObj.green + 20);
      enhancedColor = colorObj.color;
      glowIntensity = Math.min(2, (damage - 500) / 1500);
      strokeColor = 0xffff00; // Yellow stroke for medium damage
    }

    // Create bullet shape (triangle for player, can be customized for enemies)
    const bullet = scene.add
      .polygon(
        shooter.x,
        shooter.y,
        [
          0,
          -bulletRadius, // tip
          bulletRadius * 0.7,
          bulletRadius, // right base
          -bulletRadius * 0.7,
          bulletRadius, // left base
        ],
        enhancedColor
      )
      .setStrokeStyle(Math.max(1, Math.floor(glowIntensity + 1)), strokeColor);

    // Add glow effect for high damage bullets
    if (glowIntensity > 0) {
      const glowRadius = bulletRadius * (1 + glowIntensity * 0.3);
      const glow = scene.add.circle(
        shooter.x,
        shooter.y,
        glowRadius,
        0xffffff,
        glowIntensity * 0.3
      );
      glow.setDepth(bullet.depth - 1); // Place glow behind bullet
      (bullet as any).glow = glow; // Store reference to glow for cleanup
    }

    // Set bullet velocity
    (bullet as any).vx = Math.cos(angle) * bulletSpeed;
    (bullet as any).vy = Math.sin(angle) * bulletSpeed;

    // Calculate final damage
    let finalDamage = damage;
    if (!isMiddleBullet) {
      finalDamage = Math.floor(damage * 0.25); // Side bullets deal 25% damage
    }
    (bullet as any).damage = finalDamage;

    // Apply player upgrades if enabled
    if (enableUpgrades) {
      (bullet as any).critChance = this.critChance || 0;
      (bullet as any).critLevel = this.critLevel || 0;
      (bullet as any).pierce = this.pierce || 0;
      (bullet as any).ricochet = this.ricochet || 0;
      (bullet as any).explosive = this.explosive || false;
      (bullet as any).homing = this.homing || false;

      // Set homing target if homing is enabled
      if (this.homing && scene.enemies) {
        // Get all active enemies
        const activeEnemies = scene.enemies
          .getChildren()
          .filter(
            (enemyObj: any) => enemyObj.active
          ) as Phaser.GameObjects.Arc[];

        if (activeEnemies.length > 0) {
          // Only consider enemies within 90 degrees forward of the bullet's direction
          const forwardEnemies = activeEnemies.filter((enemy) => {
            const angleToEnemy = Phaser.Math.Angle.Between(
              shooter.x,
              shooter.y,
              enemy.x,
              enemy.y
            );
            const angleDifference = Math.abs(
              Phaser.Math.Angle.Wrap(angleToEnemy - angle)
            );
            return angleDifference <= Math.PI / 2; // 90 degrees forward
          });

          if (forwardEnemies.length > 0) {
            // Pick a random enemy from the forward cone
            const bulletIndex = Math.floor(
              Math.random() * forwardEnemies.length
            );
            const selectedEnemy = forwardEnemies[bulletIndex];

            if (selectedEnemy) {
              (bullet as any).homingTarget = selectedEnemy;
              (bullet as any).homingEnabled = true;
            }
          }
          // If no enemies in forward cone, bullet won't have a homing target (will go straight)
        }
      }
    }

    // Set bullet properties
    (bullet as any).spawnTime = scene.time.now;
    (bullet as any).isEnemyBullet = isEnemyBullet;
    (bullet as any).originalDirection = angle; // Store original direction for homing logic
    bullet.setRotation(angle + Math.PI / 2); // Point tip in direction of motion

    // Add to bullet group
    bulletGroup.add(bullet);

    // Track shots fired (for player)
    if (!isEnemyBullet && scene.shotsFired !== undefined) {
      scene.shotsFired++;
    }
  }

  /**
   * Applies pure chance bonus from upgrades
   */
  applyPureChanceBonus(baseChance: number): number {
    const pureChanceLevel = this.pureChance || 0;
    return baseChance + pureChanceLevel * 0.02; // 2% per level
  }

  /**
   * Checks if the character can attack based on attack speed and cooldown
   */
  canAttack(currentTime: number): boolean {
    const attackCooldown = 1000 / this.attackSpeed; // Convert attacks per second to milliseconds
    return currentTime - this.lastAttackTime >= attackCooldown;
  }

  /**
   * Updates the last attack time when an attack is performed
   */
  onAttackPerformed(currentTime: number) {
    this.lastAttackTime = currentTime;
  }

  /**
   * Performs a melee attack in a cone towards the closest target
   * @param scene The Phaser scene
   * @param attacker The attacking entity
   * @param closestTarget The closest target to attack
   */
  meleeAttack(scene: any, attacker: any, closestTarget: any) {
    const currentTime = scene.time.now;

    // Check if we can perform melee attack (same cooldown as regular attacks)
    if (!this.canAttack(currentTime)) {
      return;
    }

    // Calculate melee range (character radius + 15px for more reasonable melee distance)
    const meleeRange = this.meleeRange || (attacker.displayWidth / 2 + 80);
    const meleeDamage = this.attackDamage + this.meleeDamage;

    // Calculate direction to target
    const angleToTarget = Phaser.Math.Angle.Between(attacker.x, attacker.y, closestTarget.x, closestTarget.y);

    // Cone attack parameters - use dynamic cone angle from upgrades
    const coneAngle = (this.meleeConeAngle || 30) * Math.PI / 180; // Convert degrees to radians

    // Get the actual character color
    let attackerColor = 0x4444ff; // Default blue
    if (attacker.fillColor) {
      attackerColor = attacker.fillColor;
    } else if ((attacker as any).originalColor) {
      attackerColor = (attacker as any).originalColor;
    } else if (this.team === Team.Enemy && (attacker as any).color) {
      attackerColor = (attacker as any).color;
    }

    // Determine number of melee attacks (burst fire for player)
    const burstLevel = this.team === Team.Friendly ? this.burstFire || 0 : 0;
    const totalAttacks = 1 + burstLevel;

    // Perform each melee attack with delay for burst fire
    for (let i = 0; i < totalAttacks; i++) {
      scene.time.delayedCall(i * 150, () => { // 150ms delay between burst attacks
        if (!attacker.active) return;

        // Create visual effect for melee sector
        this.createMeleeConeEffect(scene, attacker, angleToTarget, meleeRange, coneAngle, attackerColor);

        // Find all targets within the melee cone
        const targetsInCone = this.getTargetsInMeleeCone(scene, attacker, angleToTarget, coneAngle, meleeRange);

        // Deal damage to all targets in cone using standard damage application
        for (const target of targetsInCone) {
          // Calculate damage with potential crit
          let finalDamage = meleeDamage;
          if (Math.random() < (this.critChance || 0)) {
            finalDamage *= (this.critLevel || 1) + 1; // Default 2x crit multiplier
          }

          // Apply Arcane Edge upgrade - bonus magic damage
          if (this.arcaneEdge && this.arcaneEdge > 0 && this.team === Team.Friendly) {
            const magicBonusPercent = 0.1 + (this.arcaneEdge - 1) * 0.1; // 10% base + 10% per level
            const magicDamage = Math.floor(this.magicPower * magicBonusPercent);
            finalDamage += magicDamage;
          }

          // Use standard damage application pattern - check player first
          if (this.team === Team.Enemy && scene.playerCharacter && target === scene.player) {
            // Enemy attacking player - check invulnerability first (same as bullet collision)
            if (scene.invulnTimer > 0) {
              return; // Don't apply damage if player is invulnerable
            }

            // Enemy attacking player - use standard player damage pattern
            const evasionBonus = scene.evasiveManeuverBuff > 0 ? scene.evasiveManeuverAmount : 0;
            const damageResult = scene.playerCharacter.takeDamage(finalDamage, false, false, evasionBonus);

            // Show damage indicators using the centralized function
            if (damageResult > 0) {
              scene.totalDamageTaken += damageResult;

              // Use the centralized health change indicator function
              if (scene.showHealthChangeIndicator) {
                scene.showHealthChangeIndicator(scene.playerCharacter, damageResult, false);
              }
            }

            // Set invulnerability if player has the upgrade (same as bullet collision)
            let invulnLevel = scene.playerCharacter.upgrades?.Invulnerability || 0;
            if (invulnLevel > 0 && scene.invulnCooldownTimer <= 0) {
              scene.invulnTimer = 2000 * invulnLevel;
              scene.invulnCooldownTimer = scene.invulnTimer + 10000; // 10s after invuln ends
            } else if (scene.playerCharacter.invulnBonus && scene.invulnCooldownTimer <= 0) {
              scene.invulnTimer = scene.playerCharacter.invulnBonus;
              scene.invulnCooldownTimer = scene.invulnTimer + 10000;
            }

            // Handle lifesteal
            if (this.lifesteal && damageResult > 0) {
              const healAmount = Math.floor(damageResult * this.lifesteal);
              if (healAmount > 0 && this.heal) {
                this.heal(healAmount);
              }
            }

            // Check if player died (same as bullet collision)
            if (scene.playerCharacter.hp <= 0) {
              scene.handleEntityDeath({
                entity: scene.playerCharacter,
                entityType: 'player',
                scene: scene
              });
            }
          } else if (scene.applyDamageToEnemy) {
            // For enemy targets, use the standard applyDamageToEnemy method
            scene.applyDamageToEnemy(target, finalDamage, false, true); // true = is melee damage

            // Apply Bloodletting Blades upgrade - cause bleeding
            if (this.bloodlettingBlades && this.bloodlettingBlades > 0) {
              this.applyBleedingEffect(scene, target, this.bloodlettingBlades);
            }

            // Apply Heavy Strikes upgrade - knockback enemies
            if (this.heavyStrikes && this.heavyStrikes > 0) {
              this.applyKnockbackEffect(scene, target, this.heavyStrikes, attacker);
            }

            // Apply Chilling Touch upgrade - chance to stun enemies
            if (this.chillingTouch && this.chillingTouch > 0 && Math.random() < 0.25) {
              this.applyStunEffect(scene, target, this.chillingTouch);
            }

            // Apply Melee Knockback upgrade - chance to stun enemies
            if (this.meleeKnockback && this.meleeKnockback > 0) {
              const stunChance = 0.1 + (this.meleeKnockback - 1) * 0.05; // 10% base + 5% per level
              if (Math.random() < stunChance) {
                this.applyStunEffect(scene, target, this.meleeKnockback, true); // true = use melee knockback duration
              }
            }

            // Handle lifesteal manually since applyDamageToEnemy doesn't handle it
            if (this.lifesteal && this.lifesteal > 0) {
              // We can't easily get the actual damage dealt, so approximate with lifesteal
              const healAmount = Math.floor(finalDamage * this.lifesteal);
              if (healAmount > 0 && this.heal) {
                this.heal(healAmount);
              }
            }
          } else {
            // Fallback for other scenarios
            if (target.takeDamage) {
              target.takeDamage(finalDamage);
            } else if ((target as any).dataObj && (target as any).dataObj.takeDamage) {
              (target as any).dataObj.takeDamage(finalDamage);
            }
          }
        }
      });
    }

    // Update attack cooldown (only once for the burst, not per attack)
    this.onAttackPerformed(currentTime);
  }

  /**
   * Creates visual effect for melee circular arc attack with drag trail
   */
  private createMeleeConeEffect(scene: any, attacker: any, angle: number, range: number, sectorAngle: number, color: number) {
    // Create arrays to store previous arc states for trail effect
    const trailGraphics: Phaser.GameObjects.Graphics[] = [];
    const maxTrailLength = 8; // Number of trail segments

    // Create main arc graphics
    const arcGraphics = scene.add.graphics();
    arcGraphics.setDepth(attacker.depth + 1);

    // Animation variables
    let currentScale = 0;
    const animationDuration = 200;
    const startTime = scene.time.now;
    let lastScale = 0;

    // Animation function
    const animateCone = () => {
      const elapsed = scene.time.now - startTime;
      const progress = Math.min(elapsed / animationDuration, 1);

      // Use linear scaling for constant speed (no slowing down)
      currentScale = progress;

      // Only update if scale has changed significantly (for performance)
      if (Math.abs(currentScale - lastScale) > 0.02 || progress >= 1) {
        lastScale = currentScale;

        // Clear main arc
        arcGraphics.clear();

        // Set up arc visual with 25% fill and thick arc edge
        arcGraphics.fillStyle(color, 0.25); // 25% opacity fill
        arcGraphics.lineStyle(8, color, 1.0); // 4x thicker (2 -> 8)

        // Calculate circular arc with current scale
        const centerX = attacker.x;
        const centerY = attacker.y;
        const currentRange = range * currentScale;
        const startAngle = angle - sectorAngle;
        const endAngle = angle + sectorAngle;

        // Draw only arc with fill and thick edge (no radial lines)
        arcGraphics.beginPath();
        arcGraphics.arc(centerX, centerY, currentRange, startAngle, endAngle, false);
        arcGraphics.strokePath();
        arcGraphics.fillPath();

        // Create trail effect by storing previous arc states
        if (trailGraphics.length >= maxTrailLength) {
          const oldTrail = trailGraphics.shift();
          if (oldTrail) {
            scene.tweens.add({
              targets: oldTrail,
              alpha: 0,
              duration: 100,
              onComplete: () => oldTrail.destroy()
            });
          }
        }

        // Add current state to trail with 25% fill
        const trailCone = scene.add.graphics();
        trailCone.setDepth(attacker.depth);
        trailCone.fillStyle(color, 0.15); // 15% opacity for trail fill
        trailCone.lineStyle(4, color, 0.4); // Thicker trail arc

        trailCone.beginPath();
        trailCone.arc(centerX, centerY, currentRange, startAngle, endAngle, false);
        trailCone.strokePath();
        trailCone.fillPath();

        trailGraphics.push(trailCone);

        // Fade older trail segments
        trailGraphics.forEach((trail, index) => {
          const alpha = (index + 1) / trailGraphics.length * 0.3;
          trail.setAlpha(alpha);
        });
      }

      // Continue animation or fade out
      if (progress < 1) {
        // Continue growing
        scene.time.delayedCall(16, animateCone); // ~60fps
      } else {
        // Animation complete, start fade out
        scene.tweens.add({
          targets: [arcGraphics, ...trailGraphics],
          alpha: 0,
          duration: 200,
          ease: 'Power2',
          onComplete: () => {
            arcGraphics.destroy();
            trailGraphics.forEach(trail => trail.destroy());
          }
        });
      }
    };

    // Start the animation
    animateCone();
  }

  /**
   * Gets all targets within the melee cone
   */
  private getTargetsInMeleeCone(scene: any, attacker: any, angle: number, coneAngle: number, range: number): any[] {
    const targetsInCone: any[] = [];

    // Get all potential targets
    const allTargets = this.getAllTargetsForMelee(scene, attacker);

    for (const target of allTargets) {
      const distance = Phaser.Math.Distance.Between(attacker.x, attacker.y, target.x, target.y);

      if (distance <= range) {
        // Check if target is within cone angle
        const angleToTarget = Phaser.Math.Angle.Between(attacker.x, attacker.y, target.x, target.y);
        const rawDifference = angleToTarget - angle;
        const angleDifference = Math.abs(Phaser.Math.Angle.Wrap(rawDifference));

        if (angleDifference <= coneAngle) {
          targetsInCone.push(target);
        }
      }
    }

    return targetsInCone;
  }

  /**
   * Gets all potential targets for melee attacks
   */
  private getAllTargetsForMelee(scene: any, attacker: any): any[] {
    const targets: any[] = [];

    if (this.team === Team.Friendly) {
      // Player attacking enemies
      if (scene.enemies) {
        scene.enemies.getChildren().forEach((enemy: any) => {
          if (enemy.active) {
            targets.push(enemy);
          }
        });
      }
    } else {
      // Enemy attacking player
      if (scene.player && scene.player.active) {
        targets.push(scene.player);
      }

      // Enemy attacking friendly units
      if (scene.friendlyUnits) {
        scene.friendlyUnits.getChildren().forEach((unit: any) => {
          if (unit.active && (unit as any).isDummy) {
            targets.push(unit);
          }
        });
      }
    }

    return targets;
  }

  /**
   * Applies bleeding effect to an enemy (Bloodletting Blades upgrade)
   * @param scene The Phaser scene
   * @param target The enemy target
   * @param level The upgrade level
   */
  applyBleedingEffect(scene: any, target: any, level: number) {
    // Base bleeding: 5 DPS for 3 seconds
    const baseDamage = 5;
    const baseDuration = 3000; // 3 seconds in milliseconds

    // Scaling: +2 damage and +0.5 seconds per level
    const damage = baseDamage + (level - 1) * 2;
    const duration = baseDuration + (level - 1) * 500; // +0.5 seconds per level

    // Create bleeding effect
    const bleedingEffect = {
      target: target,
      damage: damage,
      maxTicks: Math.floor(duration / 1000), // 1 tick per second
      ticks: 0,
      age: 0,
      tickAge: 0,
      maxAge: duration
    };

    // Add to scene's bleeding effects array
    if (scene.bleedingEffects) {
      scene.bleedingEffects.push(bleedingEffect);
    }

    // Visual effect - red tint on the target
    if (target.setTint) {
      const originalTint = target.tint || 0xffffff;
      target.setTint(0xff6666); // Red tint for bleeding

      // Clear the tint after the bleeding duration
      scene.time.delayedCall(duration, () => {
        if (target.active) {
          target.setTint(originalTint);
        }
      });
    }
  }

  /**
   * Applies knockback effect to an enemy (Heavy Strikes upgrade)
   * @param scene The Phaser scene
   * @param target The enemy target
   * @param level The upgrade level
   * @param attacker The attacking entity
   */
  applyKnockbackEffect(scene: any, target: any, level: number, attacker: any) {
    if (!target || !target.active || !attacker) return;

    // Calculate knockback distance - scales with each level
    const baseDistance = 100; // Base 100px push distance
    const distanceBonus = 50 * level; // +50px per level
    const totalDistance = baseDistance + distanceBonus;

    // Calculate direction from attacker to target
    const angle = Phaser.Math.Angle.Between(attacker.x, attacker.y, target.x, target.y);
    const distance = totalDistance;

    // Calculate target position
    const targetX = target.x + Math.cos(angle) * distance;
    const targetY = target.y + Math.sin(angle) * distance;

    // Apply knockback tween
    scene.tweens.add({
      targets: target,
      x: targetX,
      y: targetY,
      duration: 300, // 0.3 seconds knockback duration
      ease: 'Power2',
      onComplete: () => {
        // Ensure target stays within bounds if needed
        if (target.x < 0) target.x = 0;
        if (target.x > scene.game.config.width) target.x = scene.game.config.width;
        if (target.y < 0) target.y = 0;
        if (target.y > scene.game.config.height) target.y = scene.game.config.height;
      }
    });
  }

  /**
   * Applies stun effect to an enemy (Chilling Touch or Melee Knockback upgrade)
   * @param scene The Phaser scene
   * @param target The enemy target
   * @param level The upgrade level
   * @param isMeleeKnockback Whether this is from Melee Knockback upgrade (different duration)
   */
  applyStunEffect(scene: any, target: any, level: number, isMeleeKnockback: boolean = false) {
    if (!target || !target.active) return;

    // Calculate stun duration based on upgrade type
    let stunDuration: number;
    if (isMeleeKnockback) {
      // Melee Knockback: 0.5 second base + 0.25 seconds per level
      stunDuration = 500 + (level - 1) * 250; // in milliseconds
    } else {
      // Chilling Touch: 1 second base + 1 second per level
      stunDuration = 1000 + (level - 1) * 1000; // in milliseconds
    }

    // Store original speed if not already stored
    if (typeof (target as any).originalSpeed === 'undefined') {
      (target as any).originalSpeed = (target as any).dataObj?.moveSpeed || 1.2;
    }

    // Set enemy speed to 0 (stunned)
    (target as any).speed = 0;
    (target as any).stunnedUntil = scene.time.now + stunDuration;

    // Visual effect - blue tint for stun
    if (target.setTint) {
      const originalTint = target.tint || 0xffffff;
      target.setTint(0x66ccff); // Blue tint for stun

      // Clear the tint after stun duration
      scene.time.delayedCall(stunDuration, () => {
        if (target.active) {
          target.setTint(originalTint);
          // Restore original speed
          (target as any).speed = (target as any).originalSpeed;
        }
      });
    }

    // Show stun indicator
    if (scene.add && scene.tweens) {
      const stunText = scene.add.text(target.x, target.y - 30, 'STUNNED!', {
        font: 'bold 12px Arial',
        color: '#66ccff',
        stroke: '#000',
        strokeThickness: 2,
      }).setOrigin(0.5);

      scene.tweens.add({
        targets: stunText,
        y: stunText.y - 20,
        alpha: 0,
        duration: stunDuration,
        ease: 'Cubic.easeOut',
        onComplete: () => stunText.destroy(),
      });
    }
  }
}
