import { UPGRADES, UPGRADE_ICONS, UPGRADE_CATEGORIES, UPGRADE_COLORS } from "../../game/upgrades";

// Wheel configuration - easily customizable (total should equal 16)
export const WHEEL_CONFIG = {
  upgradeCount: 5,
  bossCount: 3,
  statsCount: 4,
  spinCount: 2,
  goldCount: 2,
  specialCount: 0
};// Wheel of Fortune slice definitions - dynamically generated
export const generateWheelSlices = (config = WHEEL_CONFIG) => {
  const slices = [];

  // Add upgrades - use specific upgrades to ensure visual matches reward
  const specificUpgrades = [
    'Rapid Fire', 'Wisps', 'Lava Shot', 'Ice Shard', 'Meteor',
    'Earth Shock', 'Discoball', 'Echo', 'Armor Up', 'Regeneration',
    'Max Health Up', 'Burst Fire', 'Piercing Bullets', 'Big Bullets', 'Homing Bullets',
    'Shotgun Shot', 'Crit Chance', 'Ricochet', 'Move Speed Up', 'Magnet'
  ];

  for (let i = 0; i < config.upgradeCount; i++) {
    const upgradeName = specificUpgrades[i % specificUpgrades.length];
    const upgrade = UPGRADES.find(u => u.name === upgradeName);
    if (upgrade) {
      slices.push({
        title: upgrade.name,
        icon: UPGRADE_ICONS[upgrade.name] || '⚡', // Use specific icon or fallback
        type: 'upgrade',
        reward: { type: 'specific_upgrade', upgradeName: upgrade.name },
        color: UPGRADE_COLORS[upgrade.category as keyof typeof UPGRADE_COLORS]
      });
    }
  }

  // Add boss spawns - using real boss names from the game
  const realBosses = [
    { name: 'King Crab', icon: '🦀', type: 'king_crab' },
    { name: 'Storm Gull', icon: '🦅', type: 'storm_gull' },
    { name: 'Leviathan\'s Eye', icon: '👁️', type: 'leviathan_eye' },
    { name: 'Ent Lord', icon: '🌳', type: 'ent_lord' },
    { name: 'Boar King', icon: '🐗', type: 'boar_king' },
    { name: 'Scarecrow Fiend', icon: '🌾', type: 'scarecrow_fiend' },
    { name: 'Serpent Colossus', icon: '🐍', type: 'serpent_colossus' },
    { name: 'Ancient Totem', icon: '🗿', type: 'ancient_totem' },
    { name: 'Ape Titan', icon: '🦍', type: 'ape_titan' },
    { name: 'Stone Colossus', icon: '🗿', type: 'stone_colossus' },
    { name: 'Thunder Roc', icon: '⚡', type: 'thunder_roc' },
    { name: 'Frost Wyrm', icon: '❄️', type: 'frost_wyrm' },
    { name: 'Yeti King', icon: '🧊', type: 'yeti_king' },
    { name: 'Glacier Horror', icon: '👻', type: 'glacier_horror' },
    { name: 'Aurora Wyrm', icon: '🌈', type: 'aurora_wyrm' }
  ];

  for (let i = 0; i < config.bossCount; i++) {
    const boss = realBosses[i % realBosses.length];
    slices.push({
      title: boss.name,
      icon: boss.icon,
      type: 'boss',
      reward: { type: 'boss_spawn', count: 1, bossType: boss.type, bossName: boss.name, bossIcon: boss.icon },
      color: '#000000' // Black for boss spawns
    });
  }

  // Add stats - using real game terminology
  const statTypes = [
    { name: '+200 HP', icon: '❤️', type: 'health', amount: 200, color: '#666666' },
    { name: '+50 Armor', icon: '🛡️', type: 'armor', amount: 50, color: '#666666' },
    { name: '+1 Speed', icon: '⚡', type: 'speed', amount: 1, color: '#666666' },
    { name: '+15 Damage', icon: '⚔️', type: 'damage', amount: 15, color: '#666666' },
    { name: '+500 XP', icon: '⭐', type: 'xp', amount: 500, color: '#666666' }
  ];
  for (let i = 0; i < config.statsCount; i++) {
    const stat = statTypes[i % statTypes.length];
    slices.push({
      title: stat.name,
      icon: stat.icon,
      type: 'stats',
      reward: { type: stat.type, amount: stat.amount },
      color: stat.color
    });
  }

  // Add spins
  for (let i = 0; i < config.spinCount; i++) {
    slices.push({
      title: 'Lucky Spin',
      icon: '🍀',
      type: 'special',
      reward: { type: 'lucky_spin' },
      color: '#ffd700' // Yellow for special (Lucky Spin)
    });
  }

  // Add gold
  const goldTypes = [
    { name: 'Change', icon: '💲', amount: 20 },
    { name: '50 Gold Bag', icon: '💰', amount: 50 },
    { name: 'Jackpot', icon: '🤑', amount: 100 }
  ];
  for (let i = 0; i < config.goldCount; i++) {
    const gold = goldTypes[i % goldTypes.length];
    slices.push({
      title: gold.name,
      icon: gold.icon,
      type: 'gold',
      reward: { type: 'gold', amount: gold.amount },
      color: '#ffd700'
    });
  }

  // Add special rewards
  for (let i = 0; i < config.specialCount; i++) {
    slices.push({
      title: 'Mystery Box',
      icon: '🎁',
      type: 'special',
      reward: { type: 'random_upgrade' },
      color: '#ffd700' // Yellow for special (Mystery Box)
    });
  }

  return slices;
};
// Function to generate random wheel slices with no consecutive repeated reward types

export const generateRandomWheelSlices = (): any[] => {
  const slices: any[] = [];
  const sliceCount = 16;

  // Generate fresh wheel slices each time to ensure colors match
  const allSliceTypes = generateWheelSlices();

  for (let i = 0; i < sliceCount; i++) {
    let availableTypes = [...allSliceTypes];

    // Remove the previous slice's type to avoid consecutive repeats
    if (i > 0) {
      const previousType = slices[i - 1].type;
      availableTypes = availableTypes.filter(slice => slice.type !== previousType);
    }

    // If no types available (shouldn't happen with 16 slices), use all types
    if (availableTypes.length === 0) {
      availableTypes = [...allSliceTypes];
    }

    // Pick a random slice from available types
    const randomIndex = Math.floor(Math.random() * availableTypes.length);
    const selectedSlice = availableTypes[randomIndex];

    // For upgrades, ensure we get a specific upgrade that matches the display
    if (selectedSlice.type === 'upgrade' && selectedSlice.reward.type === 'specific_upgrade') {
      // The slice already has the correct upgrade name, so use it as-is
      slices.push(selectedSlice);
    } else {
      // For other types, use the slice as-is
      slices.push(selectedSlice);
    }
  }

  return slices;
};

