interface InventoryProps {
  isOpen: boolean;
  onClose: () => void;
  inventory: PlayerInventory;
  onInventoryChange: (inventory: PlayerInventory) => void;
  onEquipCosmetic?: (cosmetic: Cosmetic) => void;
  onUnequipCosmetic?: (cosmeticType: CosmeticType) => void;
}

interface InventorySlotProps {
  item: OutgameItem | null;
  onClick: (item: OutgameItem) => void;
  onDragStart?: (item: OutgameItem) => void;
  onDragOver?: (e: React.DragEvent) => void;
  onDrop?: (e: React.DragEvent) => void;
  isEquipped?: boolean;
  slotIndex?: number;
}

const InventorySlot: React.FC<InventorySlotProps> = ({
  item,
  onClick,
  onDragStart,
  onDragOver,
  onDrop,
  isEquipped = false,
  slotIndex
}) => {
  const handleClick = useCallback(() => {
    if (item) {
      onClick(item);
    }
  }, [item, onClick]);

  const handleDragStart = useCallback((e: React.DragEvent) => {
    if (item && onDragStart) {
      e.dataTransfer.setData('text/plain', JSON.stringify({ item, slotIndex }));
      onDragStart(item);
    }
  }, [item, onDragStart, slotIndex]);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    if (onDragOver) {
      onDragOver(e);
    }
  }, [onDragOver]);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    if (onDrop) {
      onDrop(e);
    }
  }, [onDrop]);

  const getRarityBorderColor = (rarity: number) => {
    return RARITY_COLORS[rarity as keyof typeof RARITY_COLORS] || RARITY_COLORS[1];
  };

  const getItemIcon = (item: OutgameItem) => {
    switch (item.type) {
      case OutgameItemType.COSMETIC:
        return '👑'; // Crown for cosmetics
      case OutgameItemType.RUNE:
        return '💎'; // Gem for runes
      case OutgameItemType.TOOL:
        return '🔧'; // Wrench for tools
      case OutgameItemType.COLLECTIBLE:
        return '🏆'; // Trophy for collectibles
      default:
        return '❓';
    }
  };

  return (
    <div
      className="inventory-slot"
      onClick={handleClick}
      draggable={!!item}
      onDragStart={handleDragStart}
      onDragOver={handleDragOver}
      onDrop={handleDrop}
      style={{
        width: '100%',
        height: '100%',
        maxWidth: '120px',
        maxHeight: '120px',
        border: item ? `2px solid ${getRarityBorderColor(item.rarity)}` : '2px solid #555',
        borderRadius: '4px',
        backgroundColor: item ? 'rgba(255, 255, 255, 0.05)' : 'rgba(255, 255, 255, 0.02)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        cursor: item ? 'pointer' : 'default',
        position: 'relative',
        backdropFilter: 'blur(5px)',
        transition: 'all 0.2s ease',
        margin: '2px'
      }}
      onMouseEnter={(e) => {
        if (item) {
          e.currentTarget.style.backgroundColor = 'rgba(255, 255, 255, 0.1)';
          e.currentTarget.style.transform = 'scale(1.05)';
        }
      }}
      onMouseLeave={(e) => {
        if (item) {
          e.currentTarget.style.backgroundColor = 'rgba(255, 255, 255, 0.05)';
          e.currentTarget.style.transform = 'scale(1)';
        }
      }}
      onDragEnter={(e) => {
        e.preventDefault();
        e.currentTarget.style.borderColor = '#4CAF50';
        e.currentTarget.style.boxShadow = '0 0 10px rgba(76, 175, 80, 0.5)';
      }}
      onDragLeave={(e) => {
        e.preventDefault();
        e.currentTarget.style.borderColor = item ? getRarityBorderColor(item.rarity) : '#555';
        e.currentTarget.style.boxShadow = 'none';
      }}
    >
      {item && (
        <>
          {/* Item Icon/Image */}
          {item.type === OutgameItemType.COSMETIC ? (
            (() => {
              const imagePath = (item as Cosmetic).image;
              const imageSrc = cosmeticImages[imagePath] || imagePath;
              console.log('🔍 Loading cosmetic image:', imagePath, 'Using imported image:', !!cosmeticImages[imagePath], 'Item name:', (item as Cosmetic).name);
              return (
                <div
                  style={{
                    width: '100%',
                    height: '100%',
                    position: 'relative',
                    border: '1px solid rgba(255,255,255,0.2)',
                    overflow: 'hidden',
                    backgroundColor: 'transparent',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center'
                  }}
                >
                  <img
                    src={imageSrc}
                    alt={(item as Cosmetic).name}
                    style={{
                      maxWidth: '100%',
                      maxHeight: '100%',
                      width: '100%',
                      height: '100%',
                      filter: (item as Cosmetic).color !== '#ffffff'
                        ? `brightness(0) saturate(100%) hue-rotate(${(item as Cosmetic).color === '#ff4444' ? '0deg' : (item as Cosmetic).color === '#4444ff' ? '240deg' : '120deg'})`
                        : 'none',
                    }}
                    onLoad={(e) => {
                      const img = e.target as HTMLImageElement;
                      console.log('✅ Cosmetic image loaded:', imagePath, 'Natural Size:', img.naturalWidth, 'x', img.naturalHeight, 'Container Size: 120x120', 'Item:', (item as Cosmetic).name);
                    }}
                    onError={(e) => {
                      const img = e.target as HTMLImageElement;
                      console.log('❌ Cosmetic image failed to load:', imagePath, 'Error:', e, 'Item:', (item as Cosmetic).name);
                    }}
                  />
                </div>
              );
            })()
          ) : (
            <div
              style={{
                fontSize: '48px',
                color: '#ffffff',
                lineHeight: '1',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                width: '100%',
                height: '100%'
              }}
            >
              {getItemIcon(item)}
            </div>
          )}

          {/* Equipped indicator */}
          {isEquipped && (
            <div
              style={{
                position: 'absolute',
                top: '-2px',
                right: '-2px',
                width: '24px',
                height: '24px',
                backgroundColor: '#4CAF50',
                borderRadius: '50%',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: '14px',
                color: '#ffffff',
                fontWeight: 'bold'
              }}
            >
              ✓
            </div>
          )}

          {/* Tool charges indicator */}
          {item.type === OutgameItemType.TOOL && (item as Tool).charges !== undefined && (
            <div
              style={{
                position: 'absolute',
                bottom: '2px',
                right: '2px',
                backgroundColor: 'rgba(0, 0, 0, 0.7)',
                borderRadius: '2px',
                padding: '2px 4px',
                fontSize: '14px',
                color: '#ffffff'
              }}
            >
              {(item as Tool).charges}
            </div>
          )}
        </>
      )}
    </div>
  );
};

const Inventory: React.FC<InventoryProps> = ({
  isOpen,
  onClose,
  inventory,
  onInventoryChange,
  onEquipCosmetic,
  onUnequipCosmetic
}) => {
  const [currentPage, setCurrentPage] = useState(0);
  const [selectedItem, setSelectedItem] = useState<OutgameItem | null>(null);
  const [draggedItem, setDraggedItem] = useState<OutgameItem | null>(null);
  const [dragSourceSlot, setDragSourceSlot] = useState<number | null>(null);
  const [runeInfusionTarget, setRuneInfusionTarget] = useState<Cosmetic | null>(null);
  const [showRuneSelection, setShowRuneSelection] = useState(false);
  const modalRef = useRef<HTMLDivElement>(null);

  const ITEMS_PER_PAGE = 16; // 4x4 grid
  const MAX_PAGES = 3;

  // Get items for current page
  const getCurrentPageItems = useCallback(() => {
    const startIndex = currentPage * ITEMS_PER_PAGE;
    const endIndex = startIndex + ITEMS_PER_PAGE;
    return inventory.items.slice(startIndex, endIndex);
  }, [inventory.items, currentPage]);

  // Handle item click
  const handleItemClick = useCallback((item: OutgameItem) => {
    setSelectedItem(item);
  }, []);

  // Handle item actions
  const handleItemAction = useCallback((action: string, item: OutgameItem) => {
    switch (action) {
      case 'equip':
        if (item.type === OutgameItemType.COSMETIC) {
          const newInventory = equipCosmetic(inventory, item as Cosmetic);
          onInventoryChange(newInventory);
          if (onEquipCosmetic) {
            onEquipCosmetic(item as Cosmetic);
          }
        }
        break;

      case 'unequip':
        if (item.type === OutgameItemType.COSMETIC) {
          const cosmeticType = (item as Cosmetic).cosmeticType;
          const newInventory = unequipCosmetic(inventory, cosmeticType);
          onInventoryChange(newInventory);
          if (onUnequipCosmetic) {
            onUnequipCosmetic(cosmeticType);
          }
        }
        break;

      case 'delete':
        const newInventory = removeItemFromInventory(inventory, item.id);
        onInventoryChange(newInventory);
        break;
    }
    setSelectedItem(null);
  }, [inventory, onInventoryChange, onEquipCosmetic, onUnequipCosmetic]);

  // Handle drag and drop
  const handleDragStart = useCallback((item: OutgameItem, slotIndex?: number) => {
    setDraggedItem(item);
    setDragSourceSlot(slotIndex || null);
  }, []);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
  }, []);

  // Handle dropping on cosmetic slots
  const handleDropOnCosmetic = useCallback((e: React.DragEvent, cosmeticType: CosmeticType) => {
    e.preventDefault();

    if (!draggedItem) {
      return;
    }

    // Check if the dragged item is a cosmetic
    if (draggedItem.type !== OutgameItemType.COSMETIC) {
      setDraggedItem(null);
      setDragSourceSlot(null);
      return;
    }

    const cosmetic = draggedItem as Cosmetic;

    // Check if the cosmetic type matches the slot
    if (cosmetic.cosmeticType !== cosmeticType) {
      setDraggedItem(null);
      setDragSourceSlot(null);
      return;
    }

    // Handle equipping the cosmetic
    const currentlyEquipped = inventory.equippedCosmetics[cosmeticType];

    // If there's a currently equipped item, put it back in inventory
    let updatedItems = [...inventory.items];
    if (currentlyEquipped) {
      updatedItems.push(currentlyEquipped);
    }

    // Remove the dragged item from inventory if it was there
    if (dragSourceSlot !== null) {
      const sourceIndex = dragSourceSlot + (currentPage * ITEMS_PER_PAGE);
      if (sourceIndex < updatedItems.length) {
        updatedItems.splice(sourceIndex, 1);
      }
    } else {
      // If not from inventory, remove it from inventory by finding it
      const itemIndex = updatedItems.findIndex(item => item.id === cosmetic.id);
      if (itemIndex !== -1) {
        updatedItems.splice(itemIndex, 1);
      }
    }

    // Update equipped cosmetics
    const updatedEquippedCosmetics = {
      ...inventory.equippedCosmetics,
      [cosmeticType]: cosmetic
    };

    onInventoryChange({
      ...inventory,
      items: updatedItems,
      equippedCosmetics: updatedEquippedCosmetics
    });

    setDraggedItem(null);
    setDragSourceSlot(null);
  }, [draggedItem, dragSourceSlot, currentPage, inventory, onInventoryChange]);

  const handleDrop = useCallback((e: React.DragEvent, targetSlotIndex?: number) => {
    e.preventDefault();

    if (!draggedItem || targetSlotIndex === undefined) {
      setDraggedItem(null);
      setDragSourceSlot(null);
      return;
    }

    const targetIndex = targetSlotIndex + (currentPage * ITEMS_PER_PAGE);

    // Handle dropping from equipped cosmetics (dragSourceSlot is null)
    if (dragSourceSlot === null) {
      // Find and remove the item from equipped cosmetics
      const equippedType = Object.entries(inventory.equippedCosmetics).find(
        ([, equipped]) => equipped?.id === draggedItem.id
      )?.[0] as CosmeticType;

      if (equippedType) {
        const newItems: (OutgameItem | null)[] = [...inventory.items];

        // Extend array if necessary
        while (newItems.length <= targetIndex) {
          newItems.push(null);
        }

        // Place the item in the target slot
        newItems[targetIndex] = draggedItem;

        // Remove from equipped cosmetics
        const updatedEquippedCosmetics = { ...inventory.equippedCosmetics };
        delete updatedEquippedCosmetics[equippedType];

        // Filter out null entries before saving
        const filteredItems = newItems.filter(item => item !== null) as OutgameItem[];

        onInventoryChange({
          ...inventory,
          items: filteredItems,
          equippedCosmetics: updatedEquippedCosmetics
        });
      }
    }
    // Handle item swapping within inventory
    else {
      const sourceIndex = dragSourceSlot + (currentPage * ITEMS_PER_PAGE);

        // Allow dropping on any slot, even empty ones at the end
        if (sourceIndex !== targetIndex && sourceIndex < inventory.items.length) {
          const newItems: (OutgameItem | null)[] = [...inventory.items];

          // If target is beyond current items, extend the array
          while (newItems.length <= targetIndex) {
            newItems.push(null);
          }

          // Swap the items
          const temp = newItems[sourceIndex];
          newItems[sourceIndex] = newItems[targetIndex] || null;
          newItems[targetIndex] = temp;

          // Remove null entries at the end only
          while (newItems.length > 0 && newItems[newItems.length - 1] === null) {
            newItems.pop();
          }

          // Filter out null entries before saving
          const filteredItems = newItems.filter(item => item !== null) as OutgameItem[];

          onInventoryChange({
            ...inventory,
            items: filteredItems
          });
        }
      }

    setDraggedItem(null);
    setDragSourceSlot(null);
  }, [draggedItem, dragSourceSlot, currentPage, inventory, onInventoryChange]);

  // Render item tooltip
  const renderItemTooltip = (item: OutgameItem) => {
    const getItemTypeLabel = (type: OutgameItemType) => {
      switch (type) {
        case OutgameItemType.COSMETIC: return 'Cosmetic';
        case OutgameItemType.RUNE: return 'Rune';
        case OutgameItemType.TOOL: return 'Tool';
        case OutgameItemType.COLLECTIBLE: return 'Collectible';
        default: return 'Unknown';
      }
    };

    const getRarityLabel = (rarity: number) => {
      const labels = ['', 'Common', 'Uncommon', 'Rare', 'Epic', 'Legendary'];
      return labels[rarity] || 'Unknown';
    };

    return (
      <div style={{ padding: '16px', maxWidth: '300px' }}>
        <div style={{
          fontSize: '18px',
          fontWeight: 'bold',
          color: '#ffffff',
          marginBottom: '8px',
          borderBottom: `2px solid ${RARITY_COLORS[item.rarity as keyof typeof RARITY_COLORS]}`,
          paddingBottom: '4px'
        }}>
          {getDisplayName(item)}
        </div>

        <div style={{
          fontSize: '12px',
          color: RARITY_COLORS[item.rarity as keyof typeof RARITY_COLORS],
          marginBottom: '8px',
          textTransform: 'uppercase',
          letterSpacing: '1px'
        }}>
          {getRarityLabel(item.rarity)} {getItemTypeLabel(item.type)}
        </div>

        <div style={{
          fontSize: '14px',
          color: '#cccccc',
          marginBottom: '16px',
          lineHeight: '1.4'
        }}>
          {item.description}
        </div>

        {/* Cosmetic-specific info */}
        {item.type === OutgameItemType.COSMETIC && (
          <div style={{ marginBottom: '16px' }}>
            <div style={{ fontSize: '12px', color: '#ffffff', marginBottom: '4px' }}>
              Rune Slots: {(item as Cosmetic).runeSlots}
            </div>
            <div style={{ fontSize: '12px', color: '#ffffff' }}>
              Infused Runes: {(item as Cosmetic).infusedRunes.filter(r => r !== null).length}/{(item as Cosmetic).runeSlots}
            </div>
          </div>
        )}

        {/* Rune-specific info */}
        {item.type === OutgameItemType.RUNE && (
          <div style={{ marginBottom: '16px' }}>
            <div style={{
              fontSize: '14px',
              color: '#4CAF50',
              fontWeight: 'bold'
            }}>
              {(item as Rune).effectDescription}
            </div>
          </div>
        )}

        {/* Tool-specific info */}
        {item.type === OutgameItemType.TOOL && (
          <div style={{ marginBottom: '16px' }}>
            {(item as Tool).charges !== undefined && (
              <div style={{ fontSize: '12px', color: '#ffffff' }}>
                Charges: {(item as Tool).charges}/{(item as Tool).maxCharges}
              </div>
            )}
            {(item as Tool).toolType === ToolType.PAINT_BUCKET && (item as Tool).color && (
              <div style={{ fontSize: '12px', color: '#ffffff' }}>
                Color: {(item as Tool).color}
              </div>
            )}
          </div>
        )}
      </div>
    );
  };

  // Render equipped cosmetics section
  const renderEquippedCosmetics = () => {
    const cosmeticSlots = [
      { type: CosmeticType.HAT, label: 'Hat', icon: '🎩' },
      { type: CosmeticType.FACE, label: 'Face', icon: '😊' },
      { type: CosmeticType.BACK, label: 'Back', icon: '🎒' }
    ];

    return (
      <div style={{
        display: 'flex',
        justifyContent: 'center',
        gap: '16px',
        flexWrap: 'wrap'
      }}>
        {cosmeticSlots.map(({ type, label, icon }) => {
          const equippedItem = inventory.equippedCosmetics[type];
          return (
            <div key={type} style={{ textAlign: 'center' }}>
              <div style={{
                fontSize: '14px',
                color: '#cccccc',
                marginBottom: '8px',
                fontWeight: 'bold'
              }}>
                {label}
              </div>
              <div style={{
                width: '120px',
                height: '120px'
              }}>
                <InventorySlot
                  item={equippedItem}
                  onClick={handleItemClick}
                  onDragStart={(item) => handleDragStart(item)}
                  onDragOver={handleDragOver}
                  onDrop={(e) => handleDropOnCosmetic(e, type)}
                  isEquipped={true}
                />
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  // Render inventory grid
  const renderInventoryGrid = () => {
    const currentItems = getCurrentPageItems();
    const slots = [];

    // Fill grid with items and empty slots
    for (let i = 0; i < ITEMS_PER_PAGE; i++) {
      const item = currentItems[i] || null;
      slots.push(
        <InventorySlot
          key={`slot-${i}`}
          item={item}
          onClick={handleItemClick}
          onDragStart={(item) => handleDragStart(item, i)}
          onDragOver={handleDragOver}
          onDrop={(e) => handleDrop(e, i)}
          slotIndex={i}
        />
      );
    }

    return (
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(4, 120px)',
          gridTemplateRows: 'repeat(4, 120px)',
          gap: '8px',
          width: 'fit-content',
          margin: '0 auto',
          justifyItems: 'center',
          alignItems: 'center'
        }}
      >
        {slots}
      </div>
    );
  };

  // Render pagination
  const renderPagination = () => {
    const totalPages = Math.max(1, Math.min(MAX_PAGES, Math.ceil(inventory.items.length / ITEMS_PER_PAGE) || 1));

    return (
      <div style={{
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        gap: '8px',
        marginTop: '8px',
        marginBottom: '8px'
      }}>
        <Button
          variant="secondary"
          size="small"
          onClick={() => setCurrentPage(Math.max(0, currentPage - 1))}
          disabled={currentPage === 0}
        >
          ‹ Previous
        </Button>

        <div style={{
          display: 'flex',
          gap: '4px',
          alignItems: 'center'
        }}>
          {Array.from({ length: totalPages }, (_, i) => (
            <Button
              key={i}
              variant={currentPage === i ? 'success' : 'secondary'}
              size="small"
              onClick={() => setCurrentPage(i)}
              style={{
                minWidth: '32px',
                height: '32px',
                padding: '0 8px'
              }}
            >
              {i + 1}
            </Button>
          ))}
        </div>

        <Button
          variant="secondary"
          size="small"
          onClick={() => setCurrentPage(Math.min(totalPages - 1, currentPage + 1))}
          disabled={currentPage >= totalPages - 1}
        >
          Next ›
        </Button>
      </div>
    );
  };

  // Handle tool usage
  const handleToolUsage = useCallback((tool: Tool, targetItem?: OutgameItem) => {
    switch (tool.toolType) {
      case ToolType.HAMMER:
        if (targetItem && targetItem.type === OutgameItemType.COSMETIC) {
          const cosmetic = targetItem as Cosmetic;
          // Extract runes and destroy cosmetic
          const extractedRunes = cosmetic.infusedRunes.filter(rune => rune !== null) as Rune[];
          const newInventory = removeItemFromInventory(inventory, cosmetic.id);

          // Add extracted runes to inventory
          let updatedInventory = newInventory;
          extractedRunes.forEach(rune => {
            updatedInventory = addItemToInventory(updatedInventory, rune);
          });

          onInventoryChange(updatedInventory);
          setSelectedItem(null);

          // Decrease hammer charges
          const hammerIndex = inventory.items.findIndex(item =>
            item.type === OutgameItemType.TOOL &&
            (item as Tool).toolType === ToolType.HAMMER
          );

          if (hammerIndex !== -1) {
            const updatedHammer = { ...tool };
            updatedHammer.charges = (updatedHammer.charges || 1) - 1;

            if (updatedHammer.charges <= 0) {
              // Remove hammer if no charges left
              updatedInventory = removeItemFromInventory(updatedInventory, tool.id);
            } else {
              // Update hammer charges
              updatedInventory.items[hammerIndex] = updatedHammer;
            }

            onInventoryChange(updatedInventory);
          }
        }
        break;

      case ToolType.PAINT_BUCKET:
        if (targetItem && targetItem.type === OutgameItemType.COSMETIC && tool.color) {
          const cosmetic = targetItem as Cosmetic;
          const updatedCosmetic = {
            ...cosmetic,
            color: tool.color,
            infusedRunes: [...cosmetic.infusedRunes] // Preserve infused runes
          };

          // Update cosmetic in inventory
          const cosmeticIndex = inventory.items.findIndex(item => item.id === cosmetic.id);
          if (cosmeticIndex !== -1) {
            const newInventory = { ...inventory };
            newInventory.items[cosmeticIndex] = updatedCosmetic;
            onInventoryChange(newInventory);
          }

          // Update equipped cosmetic if it's equipped
          const equippedType = Object.entries(inventory.equippedCosmetics).find(
            ([, equipped]) => equipped?.id === cosmetic.id
          )?.[0] as CosmeticType;

          if (equippedType) {
            const newEquippedCosmetics = { ...inventory.equippedCosmetics };
            newEquippedCosmetics[equippedType] = updatedCosmetic;
            const newInventory = { ...inventory, equippedCosmetics: newEquippedCosmetics };
            onInventoryChange(newInventory);
          }

          setSelectedItem(null);

          // Decrease paint bucket charges
          const bucketIndex = inventory.items.findIndex(item =>
            item.type === OutgameItemType.TOOL &&
            (item as Tool).toolType === ToolType.PAINT_BUCKET &&
            (item as Tool).color === tool.color
          );

          if (bucketIndex !== -1) {
            const updatedBucket = { ...tool };
            updatedBucket.charges = (updatedBucket.charges || 1) - 1;

            if (updatedBucket.charges <= 0) {
              // Remove paint bucket if no charges left
              const newInventory = removeItemFromInventory(inventory, tool.id);
              onInventoryChange(newInventory);
            } else {
              // Update paint bucket charges
              const newInventory = { ...inventory };
              newInventory.items[bucketIndex] = updatedBucket;
              onInventoryChange(newInventory);
            }
          }
        }
        break;

      case ToolType.NAME_TAG:
        // For now, just show a placeholder for name tag functionality
        alert('Name Tag functionality will be implemented in a future update!');
        break;
    }
  }, [inventory, onInventoryChange]);

  // Handle rune infusion
  const handleRuneInfusion = useCallback((rune: Rune) => {
    if (!runeInfusionTarget) return;

    const cosmetic = runeInfusionTarget;
    const emptySlotIndex = cosmetic.infusedRunes.findIndex(slot => slot === null);

    if (emptySlotIndex === -1) return;

    // Create updated cosmetic with infused rune
    const updatedCosmetic = {
      ...cosmetic,
      infusedRunes: [...cosmetic.infusedRunes]
    };
    updatedCosmetic.infusedRunes[emptySlotIndex] = rune;

    // Update cosmetic in inventory
    const cosmeticIndex = inventory.items.findIndex(item => item.id === cosmetic.id);
    if (cosmeticIndex !== -1) {
      const newInventory = { ...inventory };
      newInventory.items[cosmeticIndex] = updatedCosmetic;
      onInventoryChange(newInventory);
    }

    // Update equipped cosmetic if it's equipped
    const equippedType = Object.entries(inventory.equippedCosmetics).find(
      ([, equipped]) => equipped?.id === cosmetic.id
    )?.[0] as CosmeticType;

    if (equippedType) {
      const newEquippedCosmetics = { ...inventory.equippedCosmetics };
      newEquippedCosmetics[equippedType] = updatedCosmetic;
      const newInventory = { ...inventory, equippedCosmetics: newEquippedCosmetics };
      onInventoryChange(newInventory);
    }

    // Remove rune from inventory
    const newInventory = removeItemFromInventory(inventory, rune.id);
    onInventoryChange(newInventory);

    // Reset state
    setRuneInfusionTarget(null);
    setShowRuneSelection(false);
  }, [runeInfusionTarget, inventory, onInventoryChange]);

  // Render rune selection modal
  const renderRuneSelectionModal = () => {
    if (!showRuneSelection || !runeInfusionTarget) return null;

    const availableRunes = inventory.items.filter(item =>
      item.type === OutgameItemType.RUNE
    ) as Rune[];

    return (
      <Modal
        isOpen={showRuneSelection}
        onClose={() => {
          setShowRuneSelection(false);
          setRuneInfusionTarget(null);
        }}
        title={`Infuse Rune into ${runeInfusionTarget.name}`}
        size="medium"
      >
        <div style={{ display: 'flex', flexDirection: 'column', height: '100%', gap: '16px' }}>
          <Panel
            variant="secondary"
            size="medium"
          >
            <div style={{
              fontSize: '14px',
              color: '#cccccc',
              textAlign: 'center'
            }}>
              Select a rune to infuse into this cosmetic
            </div>
          </Panel>

          <Panel
            variant="dark"
            size="medium"
            fullHeight={true}
            style={{ flex: 1 }}
          >
            {availableRunes.length > 0 ? (
              <div style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
                gap: '12px',
                maxHeight: '100%',
                overflowY: 'auto'
              }}>
                {availableRunes.map(rune => (
                  <div
                    key={rune.id}
                    style={{
                      padding: '12px',
                      backgroundColor: 'rgba(255, 255, 255, 0.05)',
                      borderRadius: '4px',
                      border: `1px solid ${RARITY_COLORS[rune.rarity as keyof typeof RARITY_COLORS]}`,
                      cursor: 'pointer',
                      transition: 'all 0.2s ease'
                    }}
                    onClick={() => handleRuneInfusion(rune)}
                    onMouseEnter={(e) => {
                      e.currentTarget.style.backgroundColor = 'rgba(255, 255, 255, 0.1)';
                      e.currentTarget.style.transform = 'scale(1.02)';
                    }}
                    onMouseLeave={(e) => {
                      e.currentTarget.style.backgroundColor = 'rgba(255, 255, 255, 0.05)';
                      e.currentTarget.style.transform = 'scale(1)';
                    }}
                  >
                    <div style={{
                      fontSize: '16px',
                      fontWeight: 'bold',
                      color: '#ffffff',
                      marginBottom: '4px'
                    }}>
                      {rune.name}
                    </div>
                    <div style={{
                      fontSize: '12px',
                      color: RARITY_COLORS[rune.rarity as keyof typeof RARITY_COLORS],
                      marginBottom: '8px'
                    }}>
                      {rune.effectDescription}
                    </div>
                    <div style={{
                      fontSize: '11px',
                      color: '#cccccc'
                    }}>
                      {rune.description}
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div style={{
                textAlign: 'center',
                color: '#cccccc',
                fontSize: '14px',
                padding: '40px'
              }}>
                No runes available for infusion
              </div>
            )}
          </Panel>
        </div>
      </Modal>
    );
  };

  // Render item details modal
  const renderItemDetailsModal = () => {
    if (!selectedItem) return null;

    const getActionButtons = (item: OutgameItem) => {
      const buttons = [];

      if (item.type === OutgameItemType.COSMETIC) {
        const cosmetic = item as Cosmetic;
        const isEquipped = Object.values(inventory.equippedCosmetics).includes(cosmetic);

        if (isEquipped) {
          buttons.push(
            <Button
              key="unequip"
              variant="secondary"
              size="small"
              onClick={() => handleItemAction('unequip', item)}
            >
              Unequip
            </Button>
          );
        } else {
          buttons.push(
            <Button
              key="equip"
              variant="primary"
              size="small"
              onClick={() => handleItemAction('equip', item)}
            >
              Equip
            </Button>
          );
        }

        // Add rune infusion buttons for cosmetics
        const availableRunes = inventory.items.filter(item =>
          item.type === OutgameItemType.RUNE
        ) as Rune[];

        const emptySlots = cosmetic.infusedRunes
          .map((rune, index) => ({ rune, index }))
          .filter(({ rune }) => rune === null)
          .length;

        if (availableRunes.length > 0 && emptySlots > 0) {
          buttons.push(
            <Button
              key="infuse-rune"
              variant="success"
              size="small"
              onClick={() => {
                setRuneInfusionTarget(cosmetic);
                setShowRuneSelection(true);
                setSelectedItem(null);
              }}
            >
              Infuse Rune ({emptySlots} slots)
            </Button>
          );
        }

        // Add tool usage buttons for cosmetics
        const availableTools = inventory.items.filter(item =>
          item.type === OutgameItemType.TOOL
        ) as Tool[];

        availableTools.forEach(tool => {
          if (tool.charges && tool.charges > 0) {
            let buttonText = '';
            let canUse = false;

            switch (tool.toolType) {
              case ToolType.HAMMER:
                buttonText = `Use Hammer (${tool.charges})`;
                canUse = cosmetic.infusedRunes.some(rune => rune !== null);
                break;
              case ToolType.PAINT_BUCKET:
                buttonText = `Use ${tool.color} Paint (${tool.charges})`;
                canUse = true;
                break;
              case ToolType.NAME_TAG:
                buttonText = `Use Name Tag (${tool.charges})`;
                canUse = true;
                break;
            }

            if (canUse) {
              buttons.push(
                <Button
                  key={`use-${tool.id}`}
                  variant="accent"
                  size="small"
                  onClick={() => handleToolUsage(tool, item)}
                >
                  {buttonText}
                </Button>
              );
            }
          }
        });
      }

      buttons.push(
        <Button
          key="delete"
          variant="accent"
          size="small"
          onClick={() => handleItemAction('delete', item)}
        >
          Delete
        </Button>
      );

      return buttons;
    };

    return (
      <Modal
        isOpen={!!selectedItem}
        onClose={() => setSelectedItem(null)}
        title="Item Details"
        size="medium"
      >
        <div style={{ display: 'flex', flexDirection: 'column', height: '100%', gap: '16px' }}>
          <Panel
            variant="secondary"
            size="medium"
            fullHeight={true}
            style={{ flex: 1 }}
          >
            {renderItemTooltip(selectedItem)}
          </Panel>

          <Panel
            variant="dark"
            size="small"
            style={{ marginTop: 'auto' }}
          >
            <div style={{
              display: 'flex',
              gap: '8px',
              justifyContent: 'flex-end'
            }}>
              {getActionButtons(selectedItem)}
            </div>
          </Panel>
        </div>
      </Modal>
    );
  };

  return (
    <>
      {/* Inventory Side Panel */}
      {isOpen && (
        <div
          style={{
            position: 'fixed',
            top: '0px',
            left: 0,
            width: '30%',
            height: 'calc(100vh - 62px)',
            backgroundColor: '#1a1a1a',
            borderRight: '2px solid #333',
            zIndex: 1000,
            display: 'flex',
            flexDirection: 'column',
            overflow: 'hidden'
          }}
        >

          {/* Header */}
          <div style={{
            padding: '12px 16px',
            backgroundColor: '#2a2a2a',
            borderBottom: '1px solid #333',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center'
          }}>
            <h3 style={{
              margin: 0,
              color: '#ffffff',
              fontSize: '18px',
              fontWeight: 'bold'
            }}>
              Inventory
            </h3>
            <button
              onClick={onClose}
              style={{
                backgroundColor: 'transparent',
                border: 'none',
                color: '#ffffff',
                fontSize: '20px',
                cursor: 'pointer',
                padding: '4px',
                borderRadius: '4px'
              }}
              onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#3a3a3a'}
              onMouseLeave={(e) => e.currentTarget.style.backgroundColor = 'transparent'}
            >
              ×
            </button>
          </div>

          <div style={{
            flex: 1,
            display: 'flex',
            flexDirection: 'column',
            overflow: 'auto',
            padding: '16px',
            gap: '16px'
          }}>
            {/* Equipped Cosmetics Panel */}
            <Panel
              title="Equipped Cosmetics"
              variant="dark"
              size="small"
            >
              {renderEquippedCosmetics()}
            </Panel>

            {/* Inventory Grid */}
            <div style={{
              flex: 1,
              display: 'flex',
              flexDirection: 'column',
              gap: '16px',
              alignItems: 'center'
            }}>
              <div style={{
                fontSize: '14px',
                fontWeight: 'bold',
                color: '#ffffff',
                textAlign: 'center'
              }}>
                Items ({inventory.items.length})
              </div>

              {renderInventoryGrid()}
              {renderPagination()}
            </div>
          </div>
        </div>
      )}

      {/* Item Details Modal */}
      {renderItemDetailsModal()}

      {/* Rune Selection Modal */}
      {renderRuneSelectionModal()}
    </>
  );
};

export default Inventory;
