import { Segment } from "./Segment";
import { Enemy } from "./Enemy";

/*
SEGMENTED ENEMY CREATION GUIDE
==============================

This guide outlines the complete process for creating segmented enemies with proper movement behaviors and visual effects.

STEP 1: ENEMY DEFINITION (EnemyTypes.ts)
----------------------------------------
1. Add `isSegmented: true` to the enemy definition
2. Set appropriate behavior:
   - For Circle movement: `behavior: 'circle'` with `behaviorParams: { orbitRadius: 600, orbitSpeed: 0.1 }`
   - For S-motion: `behavior: 's-motion'` with `behaviorParams: { lineWidth: 400, slideSpeed: 1.2 }`
3. Ensure `radius` is set correctly (will be used for segment sizing)

STEP 2: ENEMY CLASS CREATION (Character.ts)
-------------------------------------------
1. Create class extending `SegmentedEntity`
2. Constructor parameters: (hp, armor, moveSpeed, attackDamage, attackSpeed, attackRange, magicResist, magicPower, evasion, xp, projectileScale, projectileSpeed)
3. Super call with:
   - enemyType: string (matches definition key)
   - segmentCount: number (8-45 based on enemy size)
   - segmentSpacing: number (should match enemy radius)
   - segmentRadius: number (should match enemy radius)
   - baseColor: number (should match enemy definition color)
   - ... all other stats from constructor parameters
4. BehaviorManager setup:
   - CircleBehavior: `new CircleBehavior(attackRange, moveSpeed, 600, 0.1, true, true)`
   - SMotionBehavior: `new SMotionBehavior(attackRange, moveSpeed, lineWidth, slideSpeed)`

STEP 3: GRADIENT IMPLEMENTATION
-------------------------------
1. Override `initializeSegments(scene: any, startX: number, startY: number)`
2. Create path history for smooth movement
3. Implement color gradient from master color to lighter shade:
   - Master color: Use enemy definition color
   - Light color: Choose lighter shade of same color family
   - Interpolate between colors using RGB components
4. Create segments with gradient colors
5. Set master segment with original color

STEP 4: ENEMY FACTORY INTEGRATION (EnemyTypes.ts)
-------------------------------------------------
1. Add import for new enemy class
2. Add case in `createEnemyFromDefinition` switch statement
3. Pass all stats from `finalDefinition` to constructor

SEGMENT COUNT GUIDELINES:
- Small enemies (radius < 30): 8-12 segments
- Medium enemies (radius 30-80): 15-25 segments  
- Large enemies (radius 80-200): 28-35 segments
- Boss enemies (radius > 200): 35-45 segments

COLOR GRADIENT PATTERNS:
- Green enemies: Forest green (0x228B22) → Light green (0x32CD32)
- Blue enemies: Dark blue → Light blue variants
- Red/Orange: Orange-red (0xFF4500) → Light orange (0xFF6633)
- Gold: Gold (0xFFD700) → Light gold (0xFFE55C)
- Brown: Saddle brown (0x8B4513) → Light brown (0xA0522D)
- Grey: Dark grey (0x2F2F2F) → Light grey (0x696969)

BEHAVIOR PARAMETERS:
- Circle: orbitRadius: 600, orbitSpeed: 0.1
- S-motion: lineWidth: 400-500, slideSpeed: 0.8-1.5

TROUBLESHOOTING:
- Ensure segment radius matches enemy definition radius
- Verify color matches between definition and class constructor
- Check that all imports are added to EnemyTypes.ts
- Confirm case statement is added to createEnemyFromDefinition
*/

// Base class for entities made of multiple connected segments

export class SegmentedEntity extends Enemy {
  segments: Segment[] = [];
  master: Segment | null = null;
  segmentCount: number;
  segmentRadius: number;
  segmentColor: number;
  pathHistory: { x: number; y: number; time: number }[] = [];
  maxPathLength: number = 200; // Increased path length for longer snakes

  constructor(
    type: string,
    segmentCount: number,
    segmentRadius: number = 12,
    segmentColor: number = 0x666666,
    hp: number = 50,
    armor: number = 0,
    moveSpeed: number = 1,
    attackDamage: number = 5,
    attackSpeed: number = 0.5,
    attackRange: number = 150,
    meleeRange: number = 0,
    meleeDamage: number = 30,
    magicResist: number = 0,
    magicPower: number = 0,
    cooldown: number = 0,
    aoe: number = 1,
    projectileSpeed: number = 4,
    projectileScale: number = 1,
    burstFire: number = 0,
    critChance: number = 0,
    critLevel: number = 0,
    lifesteal: number = 0,
    regen: number = 0,
    evasion: number = 0,
    xpBoost: number = 1,
    magnet: number = 1,
    luck: number = 0,
    goldFind: number = 1,
    flying: boolean = false
  ) {
    super(
      type,
      hp,
      armor,
      moveSpeed,
      attackDamage,
      attackSpeed,
      attackRange,
      meleeRange,
      meleeDamage,
      magicResist,
      magicPower,
      cooldown,
      aoe,
      projectileSpeed,
      projectileScale,
      burstFire,
      critChance,
      critLevel,
      lifesteal,
      regen,
      evasion,
      xpBoost,
      magnet,
      luck,
      goldFind,
      flying
    );
    this.segmentCount = segmentCount;
    this.segmentRadius = segmentRadius;
    this.segmentColor = segmentColor;
  }

  // Get the radius for a specific segment index (allows for tapering effects)
  getSegmentRadius(index: number): number {
    // Default implementation: all segments have the same radius
    // Override this method in subclasses to create tapering effects
    return this.segmentRadius;
  }

  // Get the spacing between segments based on the previous segment's radius
  getSegmentSpacing(previousSegmentIndex: number): number {
    // Use the radius of the previous segment (or base radius for the first segment)
    const previousRadius =
      previousSegmentIndex >= 0
        ? this.getSegmentRadius(previousSegmentIndex)
        : this.segmentRadius;
    return previousRadius; // Spacing equals the previous segment's radius
  }

  // Initialize segments - should be called after the entity is created in the scene
  initializeSegments(scene: any, startX: number, startY: number) {
    this.segments = [];

    // Create initial path history - a straight line behind the start position
    this.pathHistory = [];
    const currentTime = scene.time.now;

    // Calculate cumulative spacing for each segment
    let cumulativeSpacing = 0;
    const segmentSpacings: number[] = [];

    for (let i = 0; i < this.segmentCount; i++) {
      if (i === 0) {
        // First segment (head) has no spacing
        segmentSpacings.push(0);
      } else {
        // Each subsequent segment uses spacing based on previous segment's radius
        const spacing = this.getSegmentSpacing(i - 1);
        cumulativeSpacing += spacing;
        segmentSpacings.push(cumulativeSpacing);
      }
    }

    // Create path points going backwards from the start position
    for (let i = 0; i < this.segmentCount; i++) {
      const distanceFromStart = segmentSpacings[i];
      const pathPoint = {
        x: startX - distanceFromStart, // Go backwards in a straight line (so segments appear behind)
        y: startY,
        time: currentTime - i * 100, // Each point slightly older than the next
      };
      this.pathHistory.push(pathPoint); // Add to end to maintain chronological order (oldest first)
    }

    // Create body segments first (drawn behind) - positioned along the initial path
    for (let i = this.segmentCount - 1; i > 0; i--) {
      // Make segments slightly darker as they get further from the head
      const colorVariation = Math.max(0.3, 1 - i * 0.1);
      const segmentColor = this.adjustColor(this.segmentColor, colorVariation);

      // Get the radius for this specific segment
      const segmentRadius = this.getSegmentRadius(i);

      // Position segment along the initial path
      // Since pathHistory is oldest first, we need to access from the end
      const pathIndex = this.pathHistory.length - 1 - i; // Reverse the indexing
      const pathPoint = this.pathHistory[pathIndex];

      const segment = new Segment(
        pathPoint.x,
        pathPoint.y,
        segmentRadius,
        segmentColor,
        false
      );
      segment.setVisible(true); // All segments visible from start
      this.segments.push(segment);
    }

    // Create master segment (head for snake, body for tail) last (drawn on top)
    const masterRadius = this.getSegmentRadius(this.segmentCount - 1);
    const masterSegment = new Segment(
      startX,
      startY,
      masterRadius * 1.2,
      this.segmentColor,
      true
    );
    this.master = masterSegment;
    this.segments.push(masterSegment);
  }

  // Helper method to adjust color brightness
  private adjustColor(color: number, factor: number): number {
    const r = Math.floor(((color >> 16) & 0xff) * factor);
    const g = Math.floor(((color >> 8) & 0xff) * factor);
    const b = Math.floor((color & 0xff) * factor);
    return (r << 16) | (g << 8) | b;
  }

  // Update path history for smooth segment following
  updatePathHistory(x: number, y: number, time: number) {
    // Only add a new point if we've moved enough distance from the last point
    const minDistance = this.segmentRadius * 0.2; // Minimum distance between path points

    if (this.pathHistory.length === 0) {
      this.pathHistory.push({ x, y, time });
    } else {
      const lastPoint = this.pathHistory[this.pathHistory.length - 1];
      const distance = Math.sqrt(
        Math.pow(x - lastPoint.x, 2) + Math.pow(y - lastPoint.y, 2)
      );

      if (distance >= minDistance) {
        this.pathHistory.push({ x, y, time });
        if (this.pathHistory.length > this.maxPathLength) {
          this.pathHistory.shift();
        }
      }
    }
  }

  // Get target position for a segment based on its index
  getSegmentTarget(
    index: number,
    currentTime: number
  ): { x: number; y: number; shouldBeVisible: boolean } {
    // The last segment in the array is the head (master), so we need to reverse the logic
    const isHead = index === this.segments.length - 1;

    if (isHead) {
      // Master segment (head) follows current position
      return {
        x: this.master!.targetX,
        y: this.master!.targetY,
        shouldBeVisible: true,
      };
    }

    // Calculate cumulative spacing for this segment
    let cumulativeSpacing = 0;
    for (let i = 0; i < index; i++) {
      cumulativeSpacing += this.getSegmentSpacing(i);
    }

    // Find the path point that's closest to the target distance from the head
    if (this.pathHistory.length > 0) {
      // Walk backwards through the path history to find the point at the target distance
      let currentDistance = 0;
      let lastPoint = this.pathHistory[this.pathHistory.length - 1]; // Start from the head

      for (let i = this.pathHistory.length - 2; i >= 0; i--) {
        const point = this.pathHistory[i];
        const distance = Math.sqrt(
          Math.pow(lastPoint.x - point.x, 2) +
            Math.pow(lastPoint.y - point.y, 2)
        );
        currentDistance += distance;

        if (currentDistance >= cumulativeSpacing) {
          // We found the target point
          return { x: point.x, y: point.y, shouldBeVisible: true };
        }

        lastPoint = point;
      }

      // If we didn't find a point far enough back, use the oldest point
      const oldestPoint = this.pathHistory[0];
      return { x: oldestPoint.x, y: oldestPoint.y, shouldBeVisible: true };
    }

    // Fallback: position segments in a line behind the head
    const headX = this.master!.targetX;
    const headY = this.master!.targetY;
    const segmentX = headX - cumulativeSpacing;
    const segmentY = headY;

    return { x: segmentX, y: segmentY, shouldBeVisible: true };
  }

  // Update all segment positions
  updateSegments(currentTime: number) {
    for (let i = 0; i < this.segments.length; i++) {
      const target = this.getSegmentTarget(i, currentTime);
      this.segments[i].updatePosition(target.x, target.y);
      this.segments[i].updateSmoothPosition();
      this.segments[i].setVisible(target.shouldBeVisible);
    }
  }

  // Get the master segment for damage/attack purposes
  getMasterSegment(): Segment | null {
    return this.master;
  }

  // Check if a position collides with any segment
  checkCollision(x: number, y: number, radius: number = 0): boolean {
    for (const segment of this.segments) {
      const distance = Math.sqrt(
        Math.pow(x - segment.currentX, 2) + Math.pow(y - segment.currentY, 2)
      );
      if (distance < segment.radius + radius) {
        return true;
      }
    }
    return false;
  }
}
