// Outgame Items System - Comprehensive inventory and cosmetic management

export enum OutgameItemType {
  COSMETIC = 'cosmetic',
  RUNE = 'rune',
  TOOL = 'tool',
  COLLECTIBLE = 'collectible'
}

export enum CosmeticType {
  HAT = 'hat',
  FACE = 'face',
  BACK = 'back'
}

export enum ToolType {
  HAMMER = 'hammer',
  PAINT_BUCKET = 'paint_bucket',
  NAME_TAG = 'name_tag'
}

export enum RuneType {
  ATTACK_SPEED = 'attack_speed',
  MAGICAL_DAMAGE = 'magical_damage',
  HEALTH = 'health',
  DEFENSE = 'defense',
  MOVE_SPEED = 'move_speed',
  LUCK = 'luck'
}

// Color definitions for paint buckets and cosmetic tinting
export interface ColorDefinition {
  name: string;
  hex: string;
  rarity: number; // 1-3, affects cost
}

// Base item interface
export interface BaseOutgameItem {
  id: string;
  name: string;
  description: string;
  image: string; // Path to image asset
  type: OutgameItemType;
  rarity: number; // 1-5, affects color coding
  unlocked: boolean;
  customName?: string; // For renamed items
}

// Cosmetic item (extends base)
export interface Cosmetic extends BaseOutgameItem {
  type: OutgameItemType.COSMETIC;
  cosmeticType: CosmeticType;
  color: string; // Hex color for tinting
  runeSlots: number; // Max 5
  infusedRunes: (Rune | null)[]; // Array of infused runes, null for empty slots
  originalColor: string; // Original color before tinting
}

// Rune item
export interface Rune extends BaseOutgameItem {
  type: OutgameItemType.RUNE;
  runeType: RuneType;
  effectValue: number; // Stat boost amount
  effectDescription: string;
}

// Tool item
export interface Tool extends BaseOutgameItem {
  type: OutgameItemType.TOOL;
  toolType: ToolType;
  color?: string; // For paint buckets
  charges?: number; // For consumable tools
  maxCharges?: number;
}

// Collectible item
export interface Collectible extends BaseOutgameItem {
  type: OutgameItemType.COLLECTIBLE;
  collection: string; // Collection name (e.g., "Rare Artifacts", "Boss Trophies")
  collectionIndex: number; // Position in collection
}

// Union type for all items
export type OutgameItem = Cosmetic | Rune | Tool | Collectible;

// Player cosmetic slots
export interface CosmeticSlots {
  hat: Cosmetic | null;
  face: Cosmetic | null;
  back: Cosmetic | null;
}

// Player inventory
export interface PlayerInventory {
  items: OutgameItem[];
  equippedCosmetics: CosmeticSlots;
  maxPages: number;
}

