// Utility functions
export function createRune(runeType: RuneType, id?: string): Rune {
  const definition = RUNE_DEFINITIONS[runeType];
  return {
    ...definition,
    id: id || `rune_${runeType}_${Date.now()}`,
    unlocked: true
  };
}

export function createTool(toolType: ToolType, color?: string, id?: string): Tool {
  const definition = TOOL_DEFINITIONS[toolType];
  const tool: Tool = {
    ...definition,
    id: id || `tool_${toolType}_${Date.now()}`,
    unlocked: true
  };

  if (toolType === ToolType.PAINT_BUCKET && color) {
    tool.color = color;
    tool.name = `${color} Paint Bucket`;
  }

  return tool;
}

export function createCosmetic(
  name: string,
  description: string,
  cosmeticType: CosmeticType,
  image: string,
  rarity: number = 1,
  id?: string
): Cosmetic {
  return {
    id: id || `cosmetic_${cosmeticType}_${Date.now()}`,
    name,
    description,
    image,
    type: OutgameItemType.COSMETIC,
    rarity,
    unlocked: true,
    cosmeticType,
    color: '#ffffff', // Default white
    originalColor: '#ffffff',
    runeSlots: Math.min(5, rarity + 1), // More slots for rarer items
    infusedRunes: []
  };
}

export function createCollectible(
  name: string,
  description: string,
  collection: string,
  collectionIndex: number,
  image: string,
  rarity: number = 1,
  id?: string
): Collectible {
  return {
    id: id || `collectible_${Date.now()}`,
    name,
    description,
    image,
    type: OutgameItemType.COLLECTIBLE,
    rarity,
    unlocked: true,
    collection,
    collectionIndex
  };
}

// Inventory management functions
export function initializePlayerInventory(): PlayerInventory {
  return {
    items: [],
    equippedCosmetics: {
      hat: null,
      face: null,
      back: null
    },
    maxPages: 3
  };
}

export function addItemToInventory(inventory: PlayerInventory, item: OutgameItem): PlayerInventory {
  // Check if we can stack tools (paint buckets of same color)
  if (item.type === OutgameItemType.TOOL && (item as Tool).toolType === ToolType.PAINT_BUCKET) {
    const existingTool = inventory.items.find(existingItem =>
      existingItem.type === OutgameItemType.TOOL &&
      (existingItem as Tool).toolType === ToolType.PAINT_BUCKET &&
      (existingItem as Tool).color === (item as Tool).color
    ) as Tool;

    if (existingTool && existingTool.charges !== undefined && existingTool.maxCharges !== undefined) {
      existingTool.charges = Math.min(existingTool.maxCharges, existingTool.charges + ((item as Tool).charges || 1));
      return { ...inventory };
    }
  }

  return {
    ...inventory,
    items: [...inventory.items, item]
  };
}

export function removeItemFromInventory(inventory: PlayerInventory, itemId: string): PlayerInventory {
  return {
    ...inventory,
    items: inventory.items.filter(item => item.id !== itemId)
  };
}

export function equipCosmetic(inventory: PlayerInventory, cosmetic: Cosmetic): PlayerInventory {
  const newEquippedCosmetics = { ...inventory.equippedCosmetics };

  // Unequip any existing cosmetic of the same type
  if (newEquippedCosmetics[cosmetic.cosmeticType]) {
    // Add the old cosmetic back to inventory
    inventory.items.push(newEquippedCosmetics[cosmetic.cosmeticType]!);
  }

  // Equip the new cosmetic
  newEquippedCosmetics[cosmetic.cosmeticType] = cosmetic;

  // Remove from inventory
  const newItems = inventory.items.filter(item => item.id !== cosmetic.id);

  return {
    ...inventory,
    items: newItems,
    equippedCosmetics: newEquippedCosmetics
  };
}

export function unequipCosmetic(inventory: PlayerInventory, cosmeticType: CosmeticType): PlayerInventory {
  const cosmetic = inventory.equippedCosmetics[cosmeticType];
  if (!cosmetic) return inventory;

  const newEquippedCosmetics = { ...inventory.equippedCosmetics };
  newEquippedCosmetics[cosmeticType] = null;

  return {
    ...inventory,
    items: [...inventory.items, cosmetic],
    equippedCosmetics: newEquippedCosmetics
  };
}

// Local storage functions
export function saveInventoryToLocalStorage(inventory: PlayerInventory): void {
  try {
    localStorage.setItem('bulletHellInventory', JSON.stringify(inventory));
  } catch (error) {
    console.warn('Failed to save inventory to localStorage:', error);
  }
}

export function loadInventoryFromLocalStorage(): PlayerInventory {
  try {
    const saved = localStorage.getItem('bulletHellInventory');
    if (saved) {
      return JSON.parse(saved);
    }
  } catch (error) {
    console.warn('Failed to load inventory from localStorage:', error);
  }

  return initializePlayerInventory();
}

// Calculate total stat bonuses from equipped cosmetics
export function calculateCosmeticBonuses(inventory: PlayerInventory): Record<string, number> {
  const bonuses: Record<string, number> = {};

  Object.values(inventory.equippedCosmetics).forEach(cosmetic => {
    if (cosmetic) {
      cosmetic.infusedRunes.forEach((rune: Rune | null) => {
        if (rune) {
          const key = rune.runeType;
          bonuses[key] = (bonuses[key] || 0) + rune.effectValue;
        }
      });
    }
  });

  return bonuses;
}

// Get display name (handles renamed items)
export function getDisplayName(item: OutgameItem): string {
  return item.customName || item.name;
}
