import { MovementBehavior } from "./MovementBehavior";
import { Enemy } from "../entities/Enemy";

// Base class for movement behaviors with common functionality

export abstract class BaseMovementBehavior implements MovementBehavior {
  protected attackRange: number;
  protected moveSpeed: number;
  protected canAttackWhileMoving: boolean = false;

  constructor(
    attackRange: number,
    moveSpeed: number,
    canAttackWhileMoving: boolean = false
  ) {
    this.attackRange = attackRange;
    this.moveSpeed = moveSpeed;
    this.canAttackWhileMoving = canAttackWhileMoving;
  }

  abstract update(
    enemy: Enemy,
    playerX: number,
    playerY: number,
    deltaTime: number
  ): { targetX: number; targetY: number; shouldAttack: boolean };
  abstract getType(): string;

  protected getDistanceToPlayer(
    enemy: Enemy,
    playerX: number,
    playerY: number
  ): number {
    return Math.sqrt(
      Math.pow(enemy.x - playerX, 2) + Math.pow(enemy.y - playerY, 2)
    );
  }

  protected shouldAttack(
    enemy: Enemy,
    playerX: number,
    playerY: number
  ): boolean {
    const distance = this.getDistanceToPlayer(enemy, playerX, playerY);
    return distance <= this.attackRange;
  }

  public getCanAttackWhileMoving(): boolean {
    return this.canAttackWhileMoving;
  }
}
