import nipplejs from 'nipplejs';

let joystickInstance: any = null;
let root: HTMLElement | null = null;

// Simple mobile detection (memoized)
const MOBILE = /Android|iPhone|iPad|iPod|Opera Mini|IEMobile|WPDesktop/i.test(navigator.userAgent);

export function initVirtualJoystick(onMove: (data: { angle: number; force: number }) => void, onEnd?: () => void, size: number = 200) {
  if (!MOBILE) return;
  root = document.getElementById('joystick-root');
  if (!root) return;
  // Prevent duplicate joysticks
  if (joystickInstance) return;

  // Style the root div for dynamic mode (full screen, no border)
  root.style.position = 'fixed';
  root.style.right = '0';
  root.style.bottom = '0';
  root.style.width = '100vw'; // full screen
  root.style.height = '100vh';
  root.style.zIndex = '10'; // UI overlays should use z-index > 10 to be clickable above joystick
  root.style.touchAction = 'none';
  root.style.background = 'transparent'; // fully transparent
  root.style.border = 'none';
  root.style.borderRadius = '0';
  root.style.display = 'block';
  root.style.pointerEvents = 'auto'; // always allow joystick to receive touches

  joystickInstance = nipplejs.create({
    zone: root,
    mode: 'dynamic', // dynamic mode: appears where user touches
    color: 'white',
    size,
    restOpacity: 0.5,
    restJoystick: true,
    lockX: false,
    lockY: false,
  });
  // Listen to all events for debug
  const events = ['start', 'move', 'end', 'dir', 'plain', 'shown', 'hidden', 'destroyed'];
  events.forEach(event => {
    joystickInstance.on(event, (evt: any, data: any) => {
      console.log(`Joystick event: ${event}`, data);
    });
  });
  joystickInstance.on('move', (evt: any, data: any) => {
    if (data && data.angle && data.force) {
      onMove({ angle: data.angle.radian, force: data.force });
    }
  });
  joystickInstance.on('end', () => {
    if (onEnd) onEnd();
  });
}

export function destroyVirtualJoystick() {
  if (joystickInstance) {
    joystickInstance.destroy();
    joystickInstance = null;
  }
  if (root) {
    root.innerHTML = '';
    root.removeAttribute('style');
    root = null;
  }
}
