import React from 'react';
import { toRoman } from '../../App';
import { UPGRADE_COLORS, UPGRADE_ICONS } from '../../game/upgrades';
import { MiniTooltip } from './MiniTooltip';

// Mini condensed version of upgrade cards for bottom screen display

export const MiniUpgradeCard = ({ upgrade, level, cooldown, onClick }: {
  upgrade: any;
  level: number;
  cooldown?: number;
  onClick?: () => void;
}) => {
  const rarity = upgrade.rarity || 1;
  const rarityColors = {
    1: '#ffffff', // White for tier 1
    2: '#ffd700', // Gold for tier 2
    3: '#ff6b6b' // Red for tier 3
  };

  // Check if this upgrade has cooldown functionality
  const hasCooldown = upgrade.name === 'Lava Shot' || upgrade.name === 'Ice Shard';
  const isReady = !hasCooldown || (cooldown !== undefined && cooldown <= 0);

  return (
    <MiniTooltip content={`${upgrade.name}: ${upgrade.longdescription}`} upgrade={upgrade}>
      <div
        role={onClick ? 'button' : undefined}
        tabIndex={onClick ? 0 : undefined}
        onClick={onClick}
        onKeyDown={onClick ? (e) => { if (e.key === 'Enter' || e.key === ' ') onClick(); } : undefined}
        style={{
          cursor: onClick ? 'pointer' : 'default',
          background: `linear-gradient(15deg, ${UPGRADE_COLORS[upgrade.category as keyof typeof UPGRADE_COLORS]}33 0%, ${UPGRADE_COLORS[upgrade.category as keyof typeof UPGRADE_COLORS]} 100%)`,
          border: 'none',
          borderRadius: '50%',
          width: 45,
          height: 45,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          position: 'relative',
          boxShadow: '0 4px 12px rgba(0,0,0,0.3)',
          outline: 'none',
          transition: 'transform 0.15s, box-shadow 0.15s',
          margin: '0 6px',
        }}
        onMouseDown={e => e.currentTarget.style.transform = 'scale(0.95)'}
        onMouseUp={e => e.currentTarget.style.transform = ''}
      >
        {/* Icon in center */}
        <div style={{
          fontSize: '1.35rem',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          color: '#fff',
          filter: isReady ? 'none' : 'grayscale(0.7) brightness(0.6)'
        }}>
          {UPGRADE_ICONS[upgrade.name] || '✨'}
        </div>

        {/* Roman numeral count overlay */}
        <div style={{
          position: 'absolute',
          top: -6,
          right: -6,
          background: '#23232b',
          color: '#fff',
          borderRadius: '50%',
          width: 18,
          height: 18,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: '0.55rem',
          fontWeight: 'bold',
          border: '1.5px solid #fff',
          boxShadow: '0 2px 4px rgba(0,0,0,0.3)'
        }}>
          {toRoman(level)}
        </div>

        {/* Cooldown timer overlay */}
        {hasCooldown && cooldown !== undefined && cooldown > 0 && (
          <div style={{
            position: 'absolute',
            top: -6,
            left: -6,
            background: '#ff4444',
            color: '#fff',
            borderRadius: '3px',
            padding: '1px 3px',
            fontSize: '0.45rem',
            fontWeight: 'bold',
            minWidth: '15px',
            textAlign: 'center',
            boxShadow: '0 2px 4px rgba(0,0,0,0.3)'
          }}>
            {(cooldown / 1000).toFixed(1)}
          </div>
        )}

        {/* Rarity indicator - small dots */}
        <div style={{
          position: 'absolute',
          bottom: -3,
          left: '50%',
          transform: 'translateX(-50%)',
          display: 'flex',
          gap: '1.5px'
        }}>
          {Array.from({ length: rarity }, (_, i) => (
            <div
              key={i}
              style={{
                width: '3px',
                height: '3px',
                borderRadius: '50%',
                background: rarityColors[rarity as keyof typeof rarityColors],
                boxShadow: '0 1px 2px rgba(0,0,0,0.3)'
              }} />
          ))}
        </div>
      </div>
    </MiniTooltip>
  );
};
