import React, { useState, useRef, useEffect } from 'react';
import { generateRandomWheelSlices } from './Wheel';

// Wheel of Fortune component
export const WheelOfFortune = ({
  isOpen, onClose, onReward
}: {
  isOpen: boolean;
  onClose: () => void;
  onReward: (reward: any) => void;
}) => {
  const [isSpinning, setIsSpinning] = useState(false);
  const [rotation, setRotation] = useState(0);
  const [selectedSlice, setSelectedSlice] = useState<number | null>(null);
  const [showReward, setShowReward] = useState(false);
  const [wonReward, setWonReward] = useState<any>(null);
  const wheelRef = useRef<HTMLDivElement>(null);
  const [wheelSlices, setWheelSlices] = useState<any[]>([]);

  // Generate random wheel slices when component opens
  useEffect(() => {
    if (isOpen) {
      const newSlices = generateRandomWheelSlices();
      console.log('Generated wheel slices:', newSlices.map(slice => ({ title: slice.title, color: slice.color, type: slice.type })));
      setWheelSlices(newSlices);
    }
  }, [isOpen]);

  const spinWheel = () => {
    if (isSpinning || wheelSlices.length === 0) return;

    setIsSpinning(true);

    // Choose the target slice first
    const randomSlice = Math.floor(Math.random() * wheelSlices.length);
    setSelectedSlice(randomSlice);

    // Calculate the final target rotation
    const sliceAngle = 360 / wheelSlices.length;
    const targetAngle = 270 - (randomSlice * sliceAngle + sliceAngle / 2);
    const spins = 6 + Math.random() * 2;
    const finalRotation = rotation + (spins * 360) + targetAngle;

    // Apply the final rotation directly
    setRotation(finalRotation);

    // Stop spinning after animation
    setTimeout(() => {
      setIsSpinning(false);

      // Find which dot is rightmost (closest to the arrow)
      const normalizedRotation = finalRotation % 360;
      const sliceAngle = 360 / wheelSlices.length;

      // Calculate the position of each dot after rotation
      let rightmostIndex = 0;
      let rightmostX = -Infinity;

      wheelSlices.forEach((_, index) => {
        const sliceAngle = 360 / wheelSlices.length;
        const centerAngle = (index * sliceAngle) + (sliceAngle / 2);
        const rotatedAngle = (centerAngle + normalizedRotation) * (Math.PI / 180);

        // Calculate X position of the dot (rightmost = highest X)
        const dotX = Math.cos(rotatedAngle) * 400; // 400px radius
        if (dotX > rightmostX) {
          rightmostX = dotX;
          rightmostIndex = index;
        }
      });

      const selectedIndex = rightmostIndex;

      // Use the calculated slice
      const reward = wheelSlices[selectedIndex].reward;
      setWonReward(reward);
      setShowReward(true);

      // Apply reward and close after display
      setTimeout(() => {
        onReward(reward);
        setShowReward(false);
        setWonReward(null);
        onClose();
      }, 4000); // Show reward for 4 seconds
    }, 6500); // 6.5 seconds for main spin
  };

  if (!isOpen) return null;

  return (
    <div style={{
      position: 'fixed',
      top: 0,
      left: 0,
      width: '100vw',
      height: '100vh',
      background: 'rgba(0,0,0,0.8)',
      zIndex: 3000,
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
    }}>
      <div style={{
        color: '#fff',
        fontSize: '2.5rem',
        fontWeight: 900,
        marginBottom: 32,
        letterSpacing: '0.1em',
        textAlign: 'center',
        textShadow: '0 0 20px rgba(255,255,255,0.5)'
      }}>
        WHEEL OF FORTUNE
      </div>

      <div style={{
        position: 'relative',
        width: '800px',
        height: '800px',
        marginBottom: 32
      }}>
        {/* Arrow pointer */}
        <div style={{
          position: 'absolute',
          right: '-40px',
          top: '50%',
          transform: 'translateY(-50%)',
          width: 0,
          height: 0,
          borderTop: '40px solid transparent',
          borderBottom: '40px solid transparent',
          borderRight: '60px solid #fff',
          zIndex: 10,
          filter: 'drop-shadow(0 0 20px rgba(255,255,255,0.5))'
        }} />

        {/* Wheel */}
        <div
          ref={wheelRef}
          style={{
            width: '100%',
            height: '100%',
            borderRadius: '50%',
            position: 'relative',
            transform: `rotate(${rotation}deg)`,
            transition: isSpinning ? 'transform 6.5s cubic-bezier(0.1, 0.1, 0.1, 1)' : 'none',
            boxShadow: '0 0 50px rgba(255,255,255,0.3)',
            border: '4px solid #fff',
            background: `conic-gradient(${wheelSlices.map((slice, index) => {
              const startAngle = (360 / wheelSlices.length) * index;
              const endAngle = (360 / wheelSlices.length) * (index + 1);
              console.log(`Slice ${index}: ${slice.title} - Color: ${slice.color} - Angle: ${startAngle}deg to ${endAngle}deg`);
              return `${slice.color} ${startAngle}deg ${endAngle}deg`;
            }).join(', ')})`
          }}
          onClick={spinWheel}
        >
          {/* Slice dividers */}
          {wheelSlices.map((_, index) => {
            const sliceAngle = 360 / wheelSlices.length;
            const startAngle = sliceAngle * index;

            return (
              <div
                key={`divider-${index}`}
                style={{
                  position: 'absolute',
                  left: '50%',
                  top: '50%',
                  width: '4px',
                  height: '800px',
                  background: 'rgba(255,255,255,1)',
                  transform: `translate(-50%, -50%) rotate(${startAngle}deg)`,
                  transformOrigin: 'center center',
                  zIndex: 2
                }} />
            );
          })}

          {/* Text and icons overlay */}
          {wheelSlices.map((slice, index) => {
            const sliceAngle = 360 / wheelSlices.length;
            const startAngle = sliceAngle * index;
            const centerAngle = startAngle + sliceAngle / 2;
            const radius = 70; // Distance from center

            return (
              <div
                key={index}
                style={{
                  position: 'absolute',
                  left: '50%',
                  top: '50%',
                  transform: `translate(-50%, -50%) rotate(${centerAngle}deg)`,
                  transformOrigin: 'center',
                  cursor: isSpinning ? 'default' : 'pointer',
                  pointerEvents: 'none'
                }}
              >
                {/* Container for text and icon aligned with slice */}
                <div style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'flex-end',
                  width: '200px',
                  transform: `translateY(-10%) translateX(280px)`,
                  gap: '12px',
                  height: '60px'
                }}>
                  {/* Text (name) */}
                  <div style={{
                    color: '#fff',
                    textShadow: '3px 3px 6px rgba(0,0,0,0.9)',
                    fontSize: '1.12rem',
                    fontWeight: 'bold',
                    whiteSpace: 'nowrap',
                    overflow: 'visible',
                    maxWidth: '120px',
                    textAlign: 'left',
                    order: 1
                  }}>
                    {slice.title}
                  </div>
                  {/* Icon (closest to edge) */}
                  <div style={{
                    fontSize: '2rem',
                    filter: 'drop-shadow(3px 3px 6px rgba(0,0,0,0.9))',
                    flexShrink: 0,
                    order: 2
                  }}>
                    {slice.icon}
                  </div>
                </div>

                {/* Winner dot - positioned at the edge of each slice (hidden) */}
                <div style={{
                  position: 'absolute',
                  left: '50%',
                  top: '50%',
                  width: '8px',
                  height: '8px',
                  backgroundColor: 'red',
                  borderRadius: '50%',
                  transform: `translate(-50%, -50%) translateX(400px)`,
                  transformOrigin: 'center',
                  zIndex: 5,
                  opacity: 0 // Hidden but still functional for calculations
                }} />
              </div>
            );
          })}
        </div>

        {/* Center button */}
        <div
          style={{
            position: 'absolute',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            width: '80px',
            height: '80px',
            borderRadius: '50%',
            background: 'linear-gradient(45deg, #ffd700, #ffed4e)',
            border: '4px solid #fff',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            cursor: isSpinning ? 'default' : 'pointer',
            boxShadow: '0 0 20px rgba(243, 156, 18, 0.5)',
            fontSize: '1.5rem',
            fontWeight: 'bold',
            color: '#333',
            zIndex: 5
          }}
          onClick={spinWheel}
        >
          {isSpinning ? '🎲' : 'SPIN!'}
        </div>
      </div>

      <div style={{
        color: '#ccc',
        fontSize: '1rem',
        textAlign: 'center',
        marginBottom: 24
      }}>
        Click the wheel or center button to spin!
      </div>

      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }
        @keyframes scaleIn {
          from { transform: scale(0.5); opacity: 0; }
          to { transform: scale(1); opacity: 1; }
        }
        @keyframes bounce {
          0%, 20%, 50%, 80%, 100% { transform: translateY(0); }
          40% { transform: translateY(-10px); }
          60% { transform: translateY(-5px); }
        }
      `}</style>

      <button
        onClick={onClose}
        style={{
          background: '#666',
          color: '#fff',
          border: 'none',
          borderRadius: 8,
          padding: '12px 24px',
          fontSize: '1rem',
          cursor: 'pointer',
          fontWeight: 600
        }}
      >
        Close
      </button>

      {/* Reward Display Overlay */}
      {showReward && wonReward && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          width: '100vw',
          height: '100vh',
          background: 'rgba(0,0,0,0.9)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          zIndex: 4000,
          animation: 'fadeIn 0.3s ease-in'
        }}>
          <div style={{
            background: 'linear-gradient(135deg, #2c3e50, #34495e)',
            border: '3px solid #f39c12',
            borderRadius: '20px',
            padding: '40px',
            textAlign: 'center',
            boxShadow: '0 0 50px rgba(243, 156, 18, 0.5)',
            animation: 'scaleIn 0.5s ease-out'
          }}>
            <div style={{
              fontSize: '3rem',
              marginBottom: '20px',
              animation: 'bounce 1s ease-in-out'
            }}>
              🎉
            </div>
            <div style={{
              color: '#f39c12',
              fontSize: '2rem',
              fontWeight: 'bold',
              marginBottom: '15px'
            }}>
              YOU WON!
            </div>
            <div style={{
              color: '#fff',
              fontSize: '1.5rem',
              fontWeight: 'bold',
              marginBottom: '10px'
            }}>
              {wonReward.type === 'gold' && `${wonReward.amount} Gold`}
              {wonReward.type === 'health' && `${wonReward.amount} Health`}
              {wonReward.type === 'armor' && `${wonReward.amount} Armor`}
              {wonReward.type === 'speed' && `${wonReward.amount} Speed`}
              {wonReward.type === 'damage' && `${wonReward.amount} Damage`}
              {wonReward.type === 'xp' && `${wonReward.amount} XP`}
              {wonReward.type === 'specific_upgrade' && wonReward.upgradeName}
              {wonReward.type === 'boss_spawn' && `${wonReward.bossName || 'Boss'} ${wonReward.bossIcon || '👹'}`}
              {wonReward.type === 'lucky_spin' && 'Lucky Spin!'}
              {wonReward.type === 'random_upgrade' && 'Random Upgrade!'}
            </div>
            <div style={{
              color: '#bdc3c7',
              fontSize: '1rem',
              marginTop: '10px'
            }}>
              Press any key to continue...
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
