import React from 'react';

export interface TabProps {
  children?: React.ReactNode;
  label: string;
  isActive?: boolean;
  onClick?: () => void;
  icon?: string;
  rotated?: boolean;
  className?: string;
  style?: React.CSSProperties;
}

export const Tab: React.FC<TabProps> = ({
  children,
  label,
  isActive = false,
  onClick,
  icon,
  rotated = false,
  className = '',
  style = {},
}) => {
  const tabStyle: React.CSSProperties = {
    padding: rotated ? '16px 8px' : '12px 16px',
    backgroundColor: isActive ? '#8a8a8a' : '#6a6a6a',
    color: '#ffffff',
    border: 'none',
    cursor: 'pointer',
    fontSize: '14px',
    fontWeight: 'bold',
    textTransform: 'uppercase',
    letterSpacing: '0.5px',
    transition: 'all 0.2s ease',
    display: 'flex',
    alignItems: 'center',
    justifyContent: rotated ? 'center' : 'flex-start',
    gap: rotated ? '4px' : '8px',
    width: rotated ? 'auto' : '100%',
    height: rotated ? 'auto' : 'auto',
    minHeight: rotated ? '120px' : 'auto',
    textAlign: rotated ? 'center' : 'left',
    writingMode: rotated ? 'vertical-rl' : 'horizontal-tb',
    textOrientation: rotated ? 'mixed' : 'mixed',
    transform: rotated ? 'rotate(180deg)' : 'none',
    ...style,
  };

  const handleMouseEnter = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (!isActive) {
      e.currentTarget.style.backgroundColor = '#7a7a7a';
    }
  };

  const handleMouseLeave = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (!isActive) {
      e.currentTarget.style.backgroundColor = '#6a6a6a';
    }
  };

  return (
    <button
      className={`ui-tab ${isActive ? 'ui-tab-active' : ''} ${className}`}
      style={tabStyle}
      onClick={onClick}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      {icon && <span style={{ fontSize: '16px' }}>{icon}</span>}
      {label}
    </button>
  );
};

export interface TabPanelProps {
  children: React.ReactNode;
  isActive?: boolean;
  className?: string;
  style?: React.CSSProperties;
}

export const TabPanel: React.FC<TabPanelProps> = ({
  children,
  isActive = false,
  className = '',
  style = {},
}) => {
  if (!isActive) return null;

  return (
    <div
      className={`ui-tab-panel ${className}`}
      style={{
        padding: '16px',
        backgroundColor: '#7a7a7a',
        flex: 1,
        overflowY: 'auto',
        ...style,
      }}
    >
      {children}
    </div>
  );
};

export interface TabContainerProps {
  children: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
}

export const TabContainer: React.FC<TabContainerProps> = ({
  children,
  className = '',
  style = {},
}) => {
  return (
    <div
      className={`ui-tab-container ${className}`}
      style={{
        display: 'flex',
        flexDirection: 'column',
        height: '100%',
        ...style,
      }}
    >
      {children}
    </div>
  );
};
