const SlotMachine: React.FC<SlotMachineProps> = ({ isOpen, onClose, onWin, upgrades }) => {
  const [isSpinning, setIsSpinning] = useState(false);
  const [result, setResult] = useState<Card | null>(null);
  const [showResult, setShowResult] = useState(false);
  const [currentPositions, setCurrentPositions] = useState<number[]>([0, 0, 0, 0, 0]); // Live position tracking
  const [finalPositions, setFinalPositions] = useState<number[]>([0, 0, 0, 0, 0]); // Final positions after animation
  const reelRefs = useRef<(HTMLDivElement | null)[]>([]);
  const totalMovement = useRef<number[]>([0, 0, 0, 0, 0]); // Track total movement for each reel

  // Generate a single base sequence that all reels will use
  const generateBaseSequence = () => {
    const baseSequence = [];
    // Generate 40 cards for the base sequence
    for (let i = 0; i < 40; i++) {
      baseSequence.push(CARD_POOL[Math.floor(Math.random() * CARD_POOL.length)]);
    }
    return baseSequence;
  };

  // Generate reel cards using the same base sequence for consistency
  const generateReelCards = (baseSequence: Card[]) => {
    const cards = [];
    // Generate 3 sets of 40 cards to allow for continuous looping
    for (let set = 0; set < 3; set++) {
      for (let i = 0; i < 40; i++) {
        cards.push(baseSequence[i]);
      }
    }
    return cards; // 120 cards total (3 x 40)
  };

  const [reelCards] = useState(() => {
    const baseSequence = generateBaseSequence();
    return [
      generateReelCards(baseSequence),
      generateReelCards(baseSequence),
      generateReelCards(baseSequence),
      generateReelCards(baseSequence),
      generateReelCards(baseSequence)
    ];
  });

  const spin = () => {
    if (isSpinning) return;
    
    setIsSpinning(true);
    setShowResult(false);
    setResult(null);

    // Generate random final positions for each reel (true random outcome)
    const calculatedFinalPositions = Array.from({ length: 5 }, () => {
      // Each reel moves 40-59 full loops + random amount (0-39)
      return 40 + Math.floor(Math.random() * 20) + Math.floor(Math.random() * 40);
    });

    // Store the final positions for debugging
    setFinalPositions(calculatedFinalPositions);

    // Calculate animation distances for each reel (all going down)
    // Cap the distance to ensure we don't go beyond the visible area
    const animationDistances = calculatedFinalPositions.map(totalCards => {
      const maxDistance = 80 * 168; // Maximum distance (80 cards = 2 full loops)
      return Math.min(totalCards * 168, maxDistance);
    });

    console.log('Random final positions:', calculatedFinalPositions);
    console.log('Animation distances:', animationDistances);

    // Start the spinning animation with calculated distances
    reelRefs.current.forEach((reel, index) => {
      if (reel) {
        reel.style.animation = 'none';
        reel.style.transition = 'none';
        // Trigger reflow to ensure animation reset
        void reel.offsetHeight;
        // Reset to starting position
        reel.style.transform = 'translateY(0)';
        // Trigger reflow again
        void reel.offsetHeight;
        // Apply the downward animation (negative translateY moves cards down)
        reel.style.transition = 'transform 3s ease-out';
        reel.style.transform = `translateY(-${animationDistances[index]}px)`;
        
        // Update total movement for this reel
        totalMovement.current[index] = animationDistances[index];
      }
    });

    // Set final positions immediately for winner detection
    setCurrentPositions(animationDistances);

    // Stop spinning after 3 seconds and determine winner based on actual positions
    setTimeout(() => {
      setIsSpinning(false);

      // Determine winner based on which cards actually landed at center
      const centerCards = reelRefs.current.map((reel, reelIndex) => {
        if (!reel) return null;

        // Get the current transform value to find exact position
        const transform = reel.style.transform || 'translateY(0)';
        const match = transform.match(/translateY\((-?\d+)px\)/);
        const currentY = match ? parseInt(match[1]) : 0;

        // Calculate which card is at the center line
        const cardHeight = 168; // Each card is 168px tall

        // Calculate which card is at the center line position (250px from top)
        // If translateY(-distance), then distance pixels of content has scrolled off the top
        // So the card at center (250px from top) was originally at position distance + 250
        const centerPosition = Math.abs(currentY) + 250; // 250px is center line from top
        const cardIndex = Math.floor(centerPosition / cardHeight);

        // Ensure index is within bounds (0-119)
        const boundedIndex = Math.max(0, Math.min(119, cardIndex));
        const centerCard = reelCards[reelIndex][boundedIndex];

        console.log(`Reel ${reelIndex}: transform=${transform}, currentY=${currentY}, centerPosition=${centerPosition}, cardIndex=${cardIndex}, boundedIndex=${boundedIndex}, centerCard=${centerCard?.name}`);

        return centerCard;
      });

      // Check if any 3 reels have matching cards across all 5 reels
      const checkForWin = (centerCards: (Card | null)[]) => {
        // Get all valid cards (non-null)
        const validCards = centerCards.filter(card => card !== null);

        // Check all combinations of 3 cards from the 5 reels
        for (let i = 0; i < centerCards.length - 2; i++) {
          for (let j = i + 1; j < centerCards.length - 1; j++) {
            for (let k = j + 1; k < centerCards.length; k++) {
              const card1 = centerCards[i];
              const card2 = centerCards[j];
              const card3 = centerCards[k];

              // If all three cards exist and match
              if (card1 && card2 && card3 &&
                  card1.id === card2.id && card2.id === card3.id) {
                return { hasWin: true, winningCard: card1 };
              }
            }
          }
        }

        return { hasWin: false, winningCard: null };
      };

      const winResult = checkForWin(centerCards);
      const hasThreeMatch = winResult.hasWin;

      console.log('Center cards:', centerCards.map(c => c?.name));
      console.log('Win result:', winResult);

      // Wait 2 seconds to appreciate the 5 slots before showing result
      setTimeout(() => {
        if (hasThreeMatch && winResult.winningCard) {
          setResult(winResult.winningCard); // Winning card result
          setShowResult(true);

          // Call onWin with the result after showing the winner screen
          setTimeout(() => {
            if (winResult.winningCard) {
              onWin(winResult.winningCard);
            }
          }, 1000);
        } else {
          // Show a "try again" message for losses
          setResult(null);
          setShowResult(true);

          // Close after showing the loss message
          setTimeout(() => {
            setShowResult(false);
          }, 2000);
        }
      }, 2000);
    }, 3000);
  };

  if (!isOpen) return null;

  return (
    <div style={{
      position: 'fixed',
      top: 0,
      left: 0,
      width: '100vw',
      height: '100vh',
      background: 'rgba(0,0,0,0.9)',
      zIndex: 2100,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      fontFamily: 'Arial, sans-serif',
    }}>


      <div style={{
        background: 'linear-gradient(145deg, #2a2a2a, #1a1a1a)',
        borderRadius: '20px',
        padding: '30px',
        boxShadow: '0 20px 40px rgba(0,0,0,0.5)',
        border: '3px solid #444',
        maxWidth: '90vw',
        maxHeight: '90vh',
        overflow: 'hidden',
      }}>
        {/* Header */}
        <div style={{
          textAlign: 'center',
          marginBottom: '20px',
          color: '#fff',
        }}>
          <h1 style={{ margin: '0 0 10px 0', fontSize: '2.5rem', color: '#ffd700' }}>
            🎰 UPGRADE SLOT MACHINE 🎰
          </h1>
          <p style={{ margin: 0, fontSize: '1.1rem', color: '#ccc' }}>
            Spin to win powerful upgrades!
          </p>
        </div>

        {/* Slot Machine Body */}
        <div style={{
          display: 'flex',
          gap: '10px',
          marginBottom: '30px',
          justifyContent: 'center',
        }}>
          {/* Reels */}
          <div style={{
            display: 'flex',
            gap: '10px',
            background: '#333',
            padding: '20px',
            borderRadius: '15px',
            border: '3px solid #555',
          }}>
            {[0, 1, 2, 3, 4].map((reelIndex) => (
              <div key={reelIndex} style={{
                width: '128px',
                height: '500px', // Show more cards in each reel window
                overflow: 'hidden',
                background: '#222',
                borderRadius: '10px',
                border: '2px solid #666',
                position: 'relative',
              }}>
                {/* Center indicator line */}
                <div style={{
                  position: 'absolute',
                  top: '50%',
                  left: 0,
                  right: 0,
                  height: '2px',
                  background: '#ffd700',
                  zIndex: 10,
                  transform: 'translateY(-50%)',
                  boxShadow: '0 0 8px #ffd700',
                }} />
                
                {/* Calculated center line for winner detection */}
                <div style={{
                  position: 'absolute',
                  top: '250px', // Center of 500px height
                  left: 0,
                  right: 0,
                  height: '2px',
                  background: '#ff0000',
                  zIndex: 10,
                  boxShadow: '0 0 8px #ff0000',
                }} />
                
                {/* Visual indicators disabled for now - focusing on winner detection */}
                <div
                  ref={(el) => {
                    reelRefs.current[reelIndex] = el;
                  }}
                  style={{
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    width: '100%',
                  }}
                >
                  {reelCards[reelIndex].map((card, cardIndex) => (
                    <ReelCard key={cardIndex} card={card} />
                  ))}
                </div>
                
                {/* Debug: Show center card after animation */}
                {!isSpinning && (
                  <div style={{
                    position: 'absolute',
                    top: '50%',
                    left: '50%',
                    transform: 'translate(-50%, -50%)',
                    backgroundColor: 'rgba(0,0,0,0.9)',
                    color: 'white',
                    padding: '4px 8px',
                    borderRadius: '4px',
                    fontSize: '10px',
                    zIndex: 20,
                    pointerEvents: 'none',
                    border: '1px solid white'
                  }}>
                                        Center: {(() => {
                      // Try a different approach - find which card is actually at the center
                      const reel = reelRefs.current[reelIndex];
                      if (!reel) return 'Unknown';

                      const transform = reel.style.transform || 'translateY(0)';
                      const match = transform.match(/translateY\((-?\d+)px\)/);
                      const currentY = match ? parseInt(match[1]) : 0;

                      const cardHeight = 168;

                      // Get all card elements in this reel
                      const cardElements = reel.querySelectorAll('[style*="height: 160"]'); // Find card divs

                      let centerCardName = 'Unknown';
                      cardElements.forEach((cardEl, index) => {
                        const cardRect = cardEl.getBoundingClientRect();
                        const reelRect = reel.getBoundingClientRect();

                        // Check if this card overlaps with the center line (reel top + 250px)
                        const cardTop = cardRect.top - reelRect.top;
                        const cardBottom = cardTop + cardHeight;

                        if (cardTop <= 250 && cardBottom > 250) {
                          // This card is at the center line
                          const cardIndex = Math.floor(Math.abs(currentY) / cardHeight) + index;
                          const boundedIndex = Math.max(0, Math.min(119, cardIndex));
                          const actualCard = reelCards[reelIndex][boundedIndex];
                          centerCardName = actualCard?.name || 'Unknown';

                          console.log(`Reel ${reelIndex} Visual check: cardTop=${cardTop}, cardBottom=${cardBottom}, overlaps center, cardIndex=${cardIndex}, boundedIndex=${boundedIndex}, centerCard=${centerCardName}`);
                        }
                      });

                      return centerCardName;
                    })()}
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>

        {/* Controls */}
        <div style={{
          textAlign: 'center',
          marginBottom: '20px',
        }}>
          <button
            onClick={spin}
            disabled={isSpinning}
            style={{
              background: isSpinning ? '#666' : 'linear-gradient(145deg, #ffd700, #ffed4e)',
              color: isSpinning ? '#999' : '#000',
              border: 'none',
              borderRadius: '25px',
              padding: '15px 40px',
              fontSize: '1.2rem',
              fontWeight: 'bold',
              cursor: isSpinning ? 'not-allowed' : 'pointer',
              boxShadow: '0 5px 15px rgba(0,0,0,0.3)',
              transition: 'all 0.3s ease',
              marginRight: '15px',
            }}
            onMouseEnter={(e) => {
              if (!isSpinning) {
                e.currentTarget.style.transform = 'scale(1.05)';
              }
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = 'scale(1)';
            }}
          >
            {isSpinning ? '🎰 SPINNING... 🎰' : '🎰 SPIN! 🎰'}
          </button>

          <button
            onClick={onClose}
            style={{
              background: 'linear-gradient(145deg, #ff4444, #ff6666)',
              color: '#fff',
              border: 'none',
              borderRadius: '25px',
              padding: '15px 30px',
              fontSize: '1.1rem',
              fontWeight: 'bold',
              cursor: 'pointer',
              boxShadow: '0 5px 15px rgba(0,0,0,0.3)',
              transition: 'all 0.3s ease',
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.transform = 'scale(1.05)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = 'scale(1)';
            }}
          >
            ❌ CLOSE
          </button>
        </div>

        {/* Result Display */}
        {showResult && (
          <div style={{
            position: 'fixed',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            zIndex: 2200,
            animation: 'fadeIn 0.5s ease-in',
          }}>
            <div style={{
              background: 'rgba(0,0,0,0.95)',
              padding: '30px',
              borderRadius: '20px',
              border: result ? '3px solid #ffd700' : '3px solid #ff4444',
              boxShadow: '0 20px 40px rgba(0,0,0,0.8)',
              textAlign: 'center',
            }}>
              {result ? (
                <>
                  <h2 style={{ color: '#ffd700', margin: '0 0 20px 0', fontSize: '1.8rem' }}>
                    🎉 YOU WON! 🎉
                  </h2>
                  <UpgradeCard card={result} />
                  <p style={{ color: '#fff', margin: '20px 0 0 0', fontSize: '1.1rem' }}>
                    Press SPIN again or CLOSE to continue
                  </p>
                </>
              ) : (
                <>
                  <h2 style={{ color: '#ff4444', margin: '0 0 20px 0', fontSize: '1.8rem' }}>
                    😔 NO MATCH! 😔
                  </h2>
                  <p style={{ color: '#fff', margin: '0 0 20px 0', fontSize: '1.5rem' }}>
                    Try again to win an upgrade!
                  </p>
                  <p style={{ color: '#ccc', margin: '0', fontSize: '1rem' }}>
                    Need 3 matching cards to win
                  </p>
                </>
              )}
            </div>
          </div>
        )}

        <style>
          {`
            @keyframes fadeIn {
              from { opacity: 0; transform: translate(-50%, -50%) scale(0.8); }
              to { opacity: 1; transform: translate(-50%, -50%) scale(1); }
            }
          `}
        </style>
      </div>
    </div>
  );
};

export default SlotMachine;
