import React, { useState } from 'react';
import { Panel, ProgressBar } from './index';

export interface EnemyCount {
  name: string;
  count: number;
  maxCount: number;
  color: string;
  isCurrentStage: boolean;
  type?: string; // Add type for icon display
}

export interface StageInformationPanelProps {
  title?: string;
  enemyCounts: EnemyCount[];
  stageName?: string;
  leftoverEnemiesCount?: number;
  isCollapsed?: boolean;
  onToggleCollapse?: () => void;
  className?: string;
  style?: React.CSSProperties;
}

export const StageInformationPanel: React.FC<StageInformationPanelProps> = ({
  title = 'Stage Information',
  enemyCounts,
  stageName,
  leftoverEnemiesCount = 0,
  isCollapsed = false,
  onToggleCollapse,
  className = '',
  style = {},
}) => {
  const [internalCollapsed, setInternalCollapsed] = useState(false);
  
  const collapsed = isCollapsed !== undefined ? isCollapsed : internalCollapsed;
  const handleToggle = onToggleCollapse || (() => setInternalCollapsed(!internalCollapsed));

  // Calculate total enemy count for max value
  const totalEnemies = enemyCounts.reduce((sum, enemy) => sum + enemy.count, 0);

  const panelStyle: React.CSSProperties = {
    position: 'fixed',
    top: '24px',
    right: '200px', // Position between middle and right side
    zIndex: 2001,
    minWidth: '320px',
    maxWidth: '360px',
    opacity: 0.5, // 50% transparent
    ...style,
  };

  const headerStyle: React.CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    cursor: 'pointer',
    padding: '8px 0',
    borderBottom: '1px solid rgba(255, 255, 255, 0.2)',
    marginBottom: '12px',
  };

  const toggleIconStyle: React.CSSProperties = {
    fontSize: '16px',
    transition: 'transform 0.2s ease',
    transform: collapsed ? 'rotate(-90deg)' : 'rotate(0deg)',
  };

  const contentStyle: React.CSSProperties = {
    maxHeight: collapsed ? '0' : '500px',
    overflow: 'hidden',
    transition: 'max-height 0.3s ease',
  };

  const enemyRowStyle: React.CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    marginBottom: '8px',
    padding: '4px 0',
  };

  const enemyNameStyle: React.CSSProperties = {
    fontSize: '12px',
    fontWeight: 'bold',
    color: '#ffffff',
    width: '120px', // Fixed width for alignment
    textAlign: 'left',
    overflow: 'hidden',
    textOverflow: 'ellipsis',
    whiteSpace: 'nowrap',
  };

  const enemyCountStyle: React.CSSProperties = {
    fontSize: '11px',
    color: '#cccccc',
    width: '40px', // Fixed width for alignment
    textAlign: 'center',
    fontFamily: 'monospace',
  };

  const progressContainerStyle: React.CSSProperties = {
    flex: 1,
    minWidth: '120px',
  };

  // Helper function to get icon for enemy type
  const getEnemyTypeIcon = (type?: string): string => {
    switch (type?.toLowerCase()) {
      case 'boss':
        return '👑'; // Boss icon
      case 'special':
        return '🧙‍♂️'; // Special icon
      case 'normal':
      default:
        return '🧟'; // Normal zombie icon
    }
  };

  return (
    <div className={`stage-information-panel ${className}`} style={panelStyle}>
      <Panel
        title=""
        variant="dark"
        size="small"
        style={{ padding: '12px' }}
      >
        <div style={headerStyle} onClick={handleToggle}>
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start' }}>
                         <span style={{ fontSize: '14px', fontWeight: 'bold', color: '#ffffff' }}>
               (T) {title}
             </span>
            {stageName && (
              <span style={{ fontSize: '11px', color: '#cccccc', marginTop: '2px' }}>
                {stageName}
              </span>
            )}
          </div>
                     <div style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
             <span style={{ fontSize: '10px', color: '#888888' }}>T</span>
             <span style={toggleIconStyle}>▼</span>
           </div>
        </div>
        
        <div style={contentStyle}>
          {enemyCounts.length === 0 ? (
            <div style={{ 
              fontSize: '12px', 
              color: '#888888', 
              textAlign: 'center', 
              fontStyle: 'italic',
              padding: '8px 0'
            }}>
              No enemies detected
            </div>
          ) : (
            <>
                             {/* Total enemies row */}
               <div style={{
                 ...enemyRowStyle,
                 borderBottom: '1px solid rgba(255, 255, 255, 0.1)',
                 paddingBottom: '8px',
                 marginBottom: '12px'
               }}>
                 <div style={{
                   ...enemyNameStyle,
                   color: '#ffff00',
                   fontWeight: 'bold'
                 }}>
                   TOTAL ENEMIES
                 </div>
                 <div style={{
                   ...enemyCountStyle,
                   color: '#ffff00',
                   fontWeight: 'bold'
                 }}>
                   {totalEnemies}
                 </div>
                                   <div style={progressContainerStyle}>
                    <div style={{
                      height: '10px',
                      backgroundColor: '#444444',
                      borderRadius: '5px',
                      width: '100%',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center'
                    }}>
                      <span style={{
                        fontSize: '8px',
                        color: '#888888',
                        fontWeight: 'bold'
                      }}>
                        TOTAL
                      </span>
                    </div>
                  </div>
                               </div>
                
                {/* Left over enemies row */}
                <div style={{
                  ...enemyRowStyle,
                  borderBottom: '1px solid rgba(255, 255, 255, 0.05)',
                  paddingBottom: '8px',
                  marginBottom: '8px'
                }}>
                  <div style={{
                    ...enemyNameStyle,
                    color: '#888888',
                    fontSize: '10px'
                  }}>
                    LEFT OVER ENEMIES
                  </div>
                  <div style={{
                    ...enemyCountStyle,
                    color: '#888888',
                    fontSize: '10px'
                  }}>
                    {leftoverEnemiesCount}
                  </div>
                  <div style={progressContainerStyle}>
                    <div style={{
                      height: '6px',
                      backgroundColor: '#444444',
                      borderRadius: '3px',
                      width: '100%'
                    }} />
                  </div>
                </div>
                
                {/* Individual enemy rows */}
                               {enemyCounts.map((enemy, index) => (
                  <div key={`${enemy.name}-${index}`} style={enemyRowStyle}>
                    <div style={{
                      ...enemyNameStyle,
                      color: enemy.count === 0 ? '#ff4444' : 
                             !enemy.isCurrentStage ? '#888888' : '#ffffff' // Red if count is 0, gray if leftover, white if current stage
                    }}>
                      <span style={{ marginRight: '6px', fontSize: '14px' }}>
                        {getEnemyTypeIcon(enemy.type)}
                      </span>
                      {enemy.name}
                    </div>
                    <div style={{
                      ...enemyCountStyle,
                      color: enemy.count === 0 ? '#ff4444' : 
                             !enemy.isCurrentStage ? '#888888' : '#cccccc' // Red if count is 0, gray if leftover, light gray if current stage
                    }}>
                      {enemy.count}
                    </div>
                    <div style={progressContainerStyle}>
                      <ProgressBar
                        value={enemy.count}
                        max={Math.max(totalEnemies, 1)}
                        variant="primary"
                        size="small"
                        fullWidth
                        style={{ 
                          height: '8px',
                          '--progress-color': !enemy.isCurrentStage ? '#666666' : enemy.color // Gray for leftover enemies
                        } as React.CSSProperties}
                      />
                    </div>
                  </div>
                ))}
            </>
          )}
        </div>
      </Panel>
    </div>
  );
};
