import React, { useState, useEffect } from 'react';
import { Panel, Button } from './index';
import { ItemTooltip } from './ItemTooltip';
import { ITEMS, ITEM_COLORS, ITEM_ICONS } from '../../game/items';

interface MerchantShopProps {
  isOpen: boolean;
  playerGold: number;
  playerItems: string[];
  onBuyItem: (itemName: string) => void;
  onClose: () => void;
  discountedItems?: string[];
  getDiscountedPrice?: (itemName: string, originalPrice: number) => number;
}

export const MerchantShop = ({
  isOpen,
  playerGold,
  playerItems,
  onBuyItem,
  onClose,
  discountedItems = [],
  getDiscountedPrice
}: MerchantShopProps) => {
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [availableItems, setAvailableItems] = useState<any[]>([]);

  // Generate random items when shop opens
  useEffect(() => {
    if (isOpen) {
      generateShopItems();
    }
  }, [isOpen]);

  const generateShopItems = () => {
    console.log('🎲 Generating new random shop items...');

    // Get all items and shuffle them
    const allItems = [...ITEMS];
    const shuffledItems = allItems.sort(() => Math.random() - 0.5);

    // Select 6 random items (2 shelves × 3 items each)
    const selectedItems = shuffledItems.slice(0, 6);

    // Ensure we have exactly 6 items (pad with duplicates if needed)
    while (selectedItems.length < 6) {
      selectedItems.push(shuffledItems[selectedItems.length % shuffledItems.length]);
    }

    console.log('📦 New shop items:', selectedItems.map(item => item.name));
    setAvailableItems(selectedItems);
  };

  const handleBuyItem = (item: any) => {
    const finalPrice = getDiscountedPrice ? getDiscountedPrice(item.name, item.price) : item.price;
    if (playerGold >= finalPrice && !playerItems.includes(item.name)) {
      onBuyItem(item.name);
      setSelectedItem(null);
    }
  };

  const getItemCard = (item: any, index: number) => {
    const isOwned = playerItems.includes(item.name);
    const originalPrice = item.price;
    const finalPrice = getDiscountedPrice ? getDiscountedPrice(item.name, originalPrice) : originalPrice;
    const isDiscounted = discountedItems.includes(item.name);
    const canAfford = playerGold >= finalPrice;
    const isSelected = selectedItem === item.name;

    return (
      <ItemTooltip key={index} content={item.longDescription} item={item}>
        <div
          style={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            gap: '8px',
            cursor: isOwned || !canAfford ? 'not-allowed' : 'pointer',
            opacity: isOwned ? 0.4 : 1,
            transition: 'all 0.2s'
          }}
          onClick={() => {
            if (!isOwned && canAfford) {
              if (isSelected) {
                // If already selected, deselect it
                setSelectedItem(null);
              } else {
                // Select the item to show buy button
                setSelectedItem(item.name);
              }
            }
          }}
        >
          {/* Item name above with tape background */}
          <div style={{
            position: 'relative',
            display: 'flex',
            justifyContent: 'center',
            marginBottom: '4px'
          }}>
            <div style={{
              background: 'linear-gradient(135deg, #8b4513, #654321)',
              border: '1px solid #654321',
              borderRadius: '4px',
              padding: '4px 8px',
              transform: 'rotate(-3deg)',
              boxShadow: '0 2px 4px rgba(0,0,0,0.3)',
              minWidth: '90px'
            }}>
              <div style={{
                fontSize: '13px',
                fontWeight: 'bold',
                color: '#ffffff',
                textAlign: 'center',
                textTransform: 'uppercase',
                textShadow: '0 1px 2px rgba(0,0,0,0.8)',
                whiteSpace: 'nowrap',
                overflow: 'hidden',
                textOverflow: 'ellipsis'
              }}>
                {item.name}
              </div>
            </div>
          </div>

          {/* Item icon */}
          <div
            style={{
              background: `linear-gradient(15deg, ${ITEM_COLORS[item.category as keyof typeof ITEM_COLORS]}33 0%, #23232b 100%)`,
              border: isSelected ? '2px solid #ffd700' : 'none',
              borderRadius: '50%',
              width: 90,
              height: 90,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              position: 'relative',
              boxShadow: isSelected ? '0 0 20px rgba(255, 215, 0, 0.6)' : '0 6px 16px rgba(0,0,0,0.4)',
              outline: 'none',
              transition: 'all 0.1s',
              zIndex: 10
            }}
          >
            <div style={{
              fontSize: '2.5rem',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: '#fff',
              filter: 'brightness(0.95)'
            }}>
              {item.icon || ITEM_ICONS[item.name] || '🎒'}
            </div>
          </div>

          {/* Price tag - different styling for discounted items */}
          <div style={{
            position: 'absolute',
            top: '120px',
            left: '60px',
            transform: 'rotate(25deg)',
            background: isDiscounted ? '#ff6b35' : '#0f5132', // Orange/red for discounted
            color: '#ffffff', // White text for better contrast
            borderRadius: '8px 20px 20px 20px',
            padding: '6px 12px',
            fontSize: '16px',
            fontWeight: 'bold',
            boxShadow: isDiscounted ? '0 4px 12px rgba(255,107,53,0.8)' : '0 4px 12px rgba(0,0,0,0.6)',
            border: `2px solid ${isDiscounted ? '#ff4500' : '#0f5132'}`, // Bright orange border for discounted
            minWidth: '70px',
            maxWidth: '95px', // Slightly wider for discount text
            textAlign: 'center',
            zIndex: 10,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            whiteSpace: 'nowrap',
            animation: isDiscounted ? 'pulse 1.5s infinite' : 'none'
          }}>
            <div style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              marginBottom: isDiscounted ? '2px' : '0'
            }}>
              <span style={{ fontSize: '18px', marginRight: '2px' }}>💰</span>
              <span style={{
                textDecoration: isDiscounted ? 'line-through' : 'none',
                opacity: isDiscounted ? 0.6 : 1,
                fontSize: isDiscounted ? '14px' : '16px'
              }}>
                {isDiscounted ? originalPrice : finalPrice}
              </span>
            </div>
            {isDiscounted && (
              <div style={{
                fontSize: '12px',
                color: '#ffff00',
                fontWeight: 'bold',
                textShadow: '0 1px 2px rgba(0,0,0,0.8)'
              }}>
                {finalPrice} SALE!
              </div>
            )}
          </div>

          {/* BUY tape - appears above item name tape when selected */}
          <div style={{
            position: 'absolute',
            top: isSelected ? '-50px' : '-70px',
            left: '50%',
            transform: 'translateX(-50%)',
            zIndex: 12,
            opacity: isSelected ? 1 : 0,
            transition: 'all 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55)',
            pointerEvents: isSelected ? 'auto' : 'none'
          }}>
            <div style={{
              background: 'linear-gradient(135deg, #22c55e, #16a34a)',
              border: '2px solid #15803d',
              borderRadius: '6px',
              padding: '8px 16px',
              boxShadow: '0 4px 12px rgba(0,0,0,0.4)',
              cursor: 'pointer',
              transition: 'all 0.2s ease',
              minWidth: '70px'
            }}
            onClick={(e) => {
              e.stopPropagation();
              handleBuyItem(item);
              setSelectedItem(null); // Deselect after buying
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.transform = 'scale(1.05)';
              e.currentTarget.style.boxShadow = '0 6px 16px rgba(0,0,0,0.6)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = 'scale(1)';
              e.currentTarget.style.boxShadow = '0 4px 12px rgba(0,0,0,0.4)';
            }}
            >
              <div style={{
                fontSize: '14px',
                fontWeight: 'bold',
                color: '#ffffff',
                textAlign: 'center',
                textShadow: '0 1px 2px rgba(0,0,0,0.8)',
                textTransform: 'uppercase',
                letterSpacing: '1px'
              }}>
                BUY
              </div>
            </div>
          </div>

          {/* Rarity indicator - dots at bottom */}
          <div style={{
            position: 'absolute',
            bottom: -35,
            left: '50%',
            transform: 'translateX(-50%)',
            display: 'flex',
            gap: '3px'
          }}>
            {Array.from({ length: item.rarity }, (_, i) => (
              <div
                key={i}
                style={{
                  width: '4px',
                  height: '4px',
                  borderRadius: '50%',
                  background: '#ffd700',
                  boxShadow: '0 1px 2px rgba(0,0,0,0.3)'
                }} />
            ))}
          </div>

          {/* Status indicators */}
          {isOwned && (
            <div style={{
              position: 'absolute',
              top: 4,
              right: 4,
              background: '#00ff00',
              color: '#000',
              borderRadius: '50%',
              width: '16px',
              height: '16px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '10px',
              fontWeight: 'bold'
            }}>
              ✓
            </div>
          )}


        </div>
      </ItemTooltip>
    );
  };

  if (!isOpen) return null;

  return (
    <div style={{
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      width: '100vw',
      height: '100vh',
      background: 'rgba(0, 0, 0, 0.4)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      zIndex: 10000,
      boxSizing: 'border-box',
      pointerEvents: 'none'
    }}>
      <Panel
        variant="dark"
        size="large"
        style={{
          width: '95vw',
          maxWidth: '1200px',
          height: '68vh',
          maxHeight: '800px',
          position: 'relative',
          background: `
            linear-gradient(90deg,
              #D2B48C 0%, #BC9867 25%, #D2B48C 50%, #BC9867 75%, #D2B48C 100%),
            linear-gradient(0deg,
              rgba(178, 136, 92, 0.5) 0%,
              rgba(210, 180, 140, 0.5) 50%,
              rgba(178, 136, 92, 0.5) 100%),
            repeating-linear-gradient(
              90deg,
              rgba(160, 120, 80, 0.15) 0px,
              rgba(160, 120, 80, 0.15) 4px,
              rgba(178, 136, 92, 0.2) 4px,
              rgba(178, 136, 92, 0.2) 8px
            )
          `,
          backgroundSize: '100% 100%, 100% 100%, 40px 100%',
          border: '4px solid #8B7355',
          borderRadius: '12px',
          boxShadow: '0 8px 32px rgba(0,0,0,0.8), inset 0 2px 8px rgba(255,255,255,0.1)',
          pointerEvents: 'auto',
          overflow: 'hidden'
        }}
      >
        <style>
          {`
            @keyframes pulse {
              0%, 100% {
                transform: scale(1) rotate(25deg);
              }
              50% {
                transform: scale(1.1) rotate(25deg);
              }
            }
          `}
        </style>
        {/* Towel Banner Covering Most of Panel (50% bigger) */}
        <div style={{
          position: 'absolute',
          top: '-2%',
          left: '-1%',
          transform: 'rotate(-5deg)',
          zIndex: 5,
          width: '103%',
          height: '103%',
          background: `
            linear-gradient(135deg,
              #8B4513 0%,
              #A0522D 25%,
              #CD853F 50%,
              #D2691E 75%,
              #8B4513 100%
            ),
            radial-gradient(circle at 30% 30%, rgba(255,255,255,0.1) 0%, transparent 70%),
            radial-gradient(circle at 70% 70%, rgba(255,255,255,0.08) 0%, transparent 70%),
            radial-gradient(circle at 20% 80%, rgba(0,0,0,0.4) 0%, transparent 50%),
            radial-gradient(circle at 80% 20%, rgba(0,0,0,0.3) 0%, transparent 50%)
          `,
          borderRadius: '15px',
          boxShadow: '0 8px 32px rgba(0,0,0,0.8), inset 0 2px 12px rgba(0,0,0,0.4)',
          border: '4px solid #654321',
          opacity: 0.85
        }}>
        </div>

        {/* Floating close button in corner */}
        <div style={{
          position: 'absolute',
          top: '10px',
          right: '10px',
          zIndex: 30
        }}>
          <Button
            variant="secondary"
            size="small"
            onClick={onClose}
            style={{
              fontSize: '36px',
              background: 'linear-gradient(135deg, #8B4513, #654321)',
              border: '1px solid #654321',
              color: '#ffffff',
              padding: '3px',
              borderRadius: '6px',
              cursor: 'pointer',
              boxShadow: '0 2px 4px rgba(0,0,0,0.3)',
              width: '60px',
              height: '60px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              transform: 'rotate(3deg)'
            }}
          >
            ❌
          </Button>
        </div>

        {/* Compact title with tape background */}
        <div style={{
          position: 'absolute',
          top: '15px',
          left: '50%',
          transform: 'translateX(-50%)',
          zIndex: 25,
          pointerEvents: 'none'
        }}>
          <div style={{
            background: 'linear-gradient(135deg, #8B4513, #654321)',
            border: '1px solid #654321',
            borderRadius: '4px',
            padding: '2px 8px',
            transform: 'rotate(2deg)',
            boxShadow: '0 2px 4px rgba(0,0,0,0.3)'
          }}>
            <div style={{
              fontSize: '40px',
              fontWeight: 'bold',
              color: '#ffffff',
              textAlign: 'center',
              textTransform: 'uppercase',
              letterSpacing: '0.1em'
            }}>
              Wanderer's Wagon
            </div>
          </div>
        </div>

        {/* Wagon Interior */}
        <div style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '45px',
          padding: '60px 15px 30px 15px',
          height: 'calc(100% - 60px)',
          justifyContent: 'center',
          alignItems: 'center',
          position: 'relative',
          zIndex: 20,
          overflow: 'visible'
        }}>


          {/* First row of items */}
          <div style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            gap: '180px',
            position: 'relative',
            padding: '40px 20px 30px 20px',
            minHeight: '160px',
            width: '100%'
          }}>
            {availableItems.slice(0, 3).map((item, index) => getItemCard(item, index))}
          </div>

          {/* Second row of items */}
          <div style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            gap: '180px',
            position: 'relative',
            padding: '40px 20px 30px 20px',
            minHeight: '160px',
            width: '100%'
          }}>
            {availableItems.slice(3, 6).map((item, index) => getItemCard(item, index + 3))}
          </div>
        </div>



        {/* Instructions */}
        <div style={{
          position: 'absolute',
          bottom: '8px',
          right: '16px',
          fontSize: '11px',
          color: '#888',
          textAlign: 'right'
        }}>
          Click items to select • Click [BUY] to purchase • Click selected item to deselect • Click ❌ to close
        </div>
      </Panel>
    </div>
  );
};
