import Phaser from 'phaser';
import {
  Cosmetic,
  CosmeticType,
  CosmeticSlots,
  RARITY_COLORS,
  PlayerInventory
} from '../game/outgameItems';

export class CosmeticManager {
  private scene: Phaser.Scene;
  private cosmeticSprites: Map<string, Phaser.GameObjects.Sprite | Phaser.GameObjects.Shape> = new Map();
  private equippedCosmetics: CosmeticSlots = {
    hat: null,
    face: null,
    back: null
  };

  // Offset positions for different cosmetic types (relative to player center)
  private static readonly COSMETIC_OFFSETS = {
    [CosmeticType.HAT]: { x: 0, y: -25 },
    [CosmeticType.FACE]: { x: 0, y: 0 },
    [CosmeticType.BACK]: { x: 0, y: 10 }
  };

  // Scale factors for cosmetics
  private static readonly COSMETIC_SCALES = {
    [CosmeticType.HAT]: 0.8,
    [CosmeticType.FACE]: 0.6,
    [CosmeticType.BACK]: 0.9
  };

  constructor(scene: Phaser.Scene) {
    this.scene = scene;
  }

  /**
   * Equip a cosmetic and create its visual representation
   */
  equipCosmetic(cosmetic: Cosmetic): void {
    const existingCosmetic = this.equippedCosmetics[cosmetic.cosmeticType];
    if (existingCosmetic) {
      this.unequipCosmetic(cosmetic.cosmeticType);
    }

    this.equippedCosmetics[cosmetic.cosmeticType] = cosmetic;
    this.createCosmeticSprite(cosmetic);
  }

  /**
   * Unequip a cosmetic and remove its visual representation
   */
  unequipCosmetic(cosmeticType: CosmeticType): void {
    const cosmetic = this.equippedCosmetics[cosmeticType];
    if (!cosmetic) return;

    this.destroyCosmeticSprite(cosmetic.id);
    this.equippedCosmetics[cosmeticType] = null;
  }

  /**
   * Update equipped cosmetics from inventory data
   */
  updateFromInventory(inventory: PlayerInventory): void {
    // Clear all existing cosmetics
    Object.values(CosmeticType).forEach(type => {
      this.unequipCosmetic(type);
    });

    // Equip cosmetics from inventory
    Object.entries(inventory.equippedCosmetics).forEach(([type, cosmetic]) => {
      if (cosmetic) {
        this.equipCosmetic(cosmetic);
      }
    });
  }

  /**
   * Update cosmetic positions and rotations to follow the player
   */
  update(playerX: number, playerY: number, playerRotation: number = 0): void {
    this.cosmeticSprites.forEach((sprite, cosmeticId) => {
      const cosmetic = this.getCosmeticById(cosmeticId);
      if (!cosmetic) return;

      const offset = CosmeticManager.COSMETIC_OFFSETS[cosmetic.cosmeticType];
      const scale = CosmeticManager.COSMETIC_SCALES[cosmetic.cosmeticType];

      // Calculate position relative to player
      const cos = Math.cos(playerRotation);
      const sin = Math.sin(playerRotation);

      // Rotate the offset around the player
      const rotatedX = offset.x * cos - offset.y * sin;
      const rotatedY = offset.x * sin + offset.y * cos;

      // Apply position and rotation
      sprite.setPosition(playerX + rotatedX, playerY + rotatedY);
      sprite.setRotation(playerRotation);

      // Apply cosmetic tint if specified
      if (cosmetic.color && cosmetic.color !== '#ffffff') {
        const color = Phaser.Display.Color.HexStringToColor(cosmetic.color);
        (sprite as Phaser.GameObjects.Sprite).setTint(color.color);
      } else {
        (sprite as Phaser.GameObjects.Sprite).clearTint();
      }

      // Apply rarity-based glow effect
      this.applyRarityEffect(sprite as Phaser.GameObjects.Sprite, cosmetic.rarity);
    });
  }

  /**
   * Get currently equipped cosmetics
   */
  getEquippedCosmetics(): CosmeticSlots {
    return { ...this.equippedCosmetics };
  }

  /**
   * Get cosmetic by ID
   */
  private getCosmeticById(id: string): Cosmetic | null {
    return Object.values(this.equippedCosmetics).find(cosmetic => cosmetic?.id === id) || null;
  }

  /**
   * Create sprite for a cosmetic
   */
  private createCosmeticSprite(cosmetic: Cosmetic): void {
    const offset = CosmeticManager.COSMETIC_OFFSETS[cosmetic.cosmeticType];
    const scale = CosmeticManager.COSMETIC_SCALES[cosmetic.cosmeticType];

    try {
      // Try to load the actual PNG image
      const sprite = this.scene.add.sprite(0, 0, cosmetic.image);

      // Set the origin to center for proper positioning
      sprite.setOrigin(0.5, 0.5);
      sprite.setScale(scale);
      sprite.setDepth(100); // Above player but below UI

      // Store reference
      this.cosmeticSprites.set(cosmetic.id, sprite);
    } catch (error) {
      // Fallback to colored rectangle if image fails to load
      console.warn(`Failed to load cosmetic image: ${cosmetic.image}, using placeholder`);
      const fallbackSprite = this.scene.add.rectangle(
        0, // Will be set in update
        0, // Will be set in update
        20, // Width
        20, // Height
        this.getPlaceholderColor(cosmetic.cosmeticType),
        1
      );
      fallbackSprite.setScale(scale);
      fallbackSprite.setDepth(100); // Above player but below UI

      // Store reference
      this.cosmeticSprites.set(cosmetic.id, fallbackSprite);
    }
  }

  /**
   * Destroy cosmetic sprite
   */
  private destroyCosmeticSprite(cosmeticId: string): void {
    const sprite = this.cosmeticSprites.get(cosmeticId);
    if (sprite) {
      sprite.destroy();
      this.cosmeticSprites.delete(cosmeticId);
    }
  }

  /**
   * Get placeholder color for cosmetic type
   */
  private getPlaceholderColor(cosmeticType: CosmeticType): number {
    const colors = {
      [CosmeticType.HAT]: 0xffd700, // Gold for hat
      [CosmeticType.FACE]: 0x87ceeb, // Sky blue for face
      [CosmeticType.BACK]: 0x8b4513  // Brown for back
    };
    return colors[cosmeticType];
  }

  /**
   * Apply rarity-based visual effects
   */
  private applyRarityEffect(sprite: Phaser.GameObjects.Sprite, rarity: number): void {
    // Remove existing effects
    if (sprite.preFX) {
      sprite.preFX.clear();
    }

    // Apply glow effect based on rarity
    if (rarity >= 3) {
      const glowColor = RARITY_COLORS[rarity as keyof typeof RARITY_COLORS] || '#cccccc';
      const color = Phaser.Display.Color.HexStringToColor(glowColor);

      // Add glow effect
      sprite.preFX?.addGlow(color.color, 2, 0, false, 0.1, 4);
    }
  }

  /**
   * Clean up all cosmetic sprites
   */
  destroy(): void {
    this.cosmeticSprites.forEach(sprite => sprite.destroy());
    this.cosmeticSprites.clear();
  }

  /**
   * Set visibility of all cosmetics
   */
  setVisible(visible: boolean): void {
    this.cosmeticSprites.forEach(sprite => sprite.setVisible(visible));
  }
}
