import { Character } from "./Character";
import { Team } from "../game/Team";
import { BehaviorManager } from "../behaviours/BehaviorManager";

// Basic Enemy class, inherits from Character and sets team to Enemy by default
export class Enemy extends Character {
  type: string;
  x: number = 0;
  y: number = 0;
  behaviorManager?: BehaviorManager;
  flying: boolean = false;
  // Gold drops are now handled by chance system, not stored on enemy
  constructor(
    type: string,
    hp: number = 50,
    armor: number = 0,
    moveSpeed: number = 1,
    attackDamage: number = 5,
    attackSpeed: number = 0.5,
    attackRange: number = 150,
    meleeRange: number = 0,
    meleeDamage: number = 30,
    magicResist: number = 0,
    magicPower: number = 0,
    cooldown: number = 0,
    aoe: number = 1,
    projectileSpeed: number = 4,
    projectileScale: number = 1,
    burstFire: number = 0,
    critChance: number = 0,
    critLevel: number = 0,
    lifesteal: number = 0,
    regen: number = 0,
    evasion: number = 0,
    xpBoost: number = 1,
    magnet: number = 1,
    luck: number = 0,
    goldFind: number = 1,
    flying: boolean = false
  ) {
    super(
      hp,
      armor,
      moveSpeed,
      Team.Enemy,
      attackDamage,
      attackSpeed,
      attackRange,
      meleeRange,
      meleeDamage,
      magicResist,
      magicPower,
      cooldown,
      aoe,
      projectileSpeed,
      projectileScale,
      burstFire,
      critChance,
      critLevel,
      lifesteal,
      regen,
      evasion,
      xpBoost,
      magnet,
      luck,
      goldFind
    );
    this.type = type;
    this.flying = flying;
  }
}
