import React, { useState, useRef, useEffect } from 'react';

// Import upgrade colors (this should match the colors defined in App.tsx)
const UPGRADE_COLORS = {
  Physical: '#ff4444',
  Magical: '#c388f7',
  Defensive: '#3ecf4a',
  Utility: '#44aaff',
};

export interface TooltipProps {
  children: React.ReactNode;
  content: React.ReactNode;
  position?: 'top' | 'bottom' | 'left' | 'right';
  delay?: number;
  className?: string;
  style?: React.CSSProperties;
  upgrade?: any; // Add upgrade object for enhanced tooltips
}

// NOTE: This Tooltip component must be maintained alongside the custom tooltip implementation in App.tsx for upgrade icons
export const Tooltip: React.FC<TooltipProps> = ({
  children,
  content,
  position = 'top',
  delay = 500,
  className = '',
  style = {},
  upgrade,
}) => {
  const [isVisible, setIsVisible] = useState(false);
  const [tooltipPosition, setTooltipPosition] = useState({ x: 0, y: 0 });
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);
  const triggerRef = useRef<HTMLDivElement>(null);
  const tooltipRef = useRef<HTMLDivElement>(null);

  const showTooltip = () => {
    timeoutRef.current = setTimeout(() => {
      setIsVisible(true);
    }, delay);
  };

  const hideTooltip = () => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }
    setIsVisible(false);
  };

  useEffect(() => {
    if (isVisible && triggerRef.current && tooltipRef.current) {
      const triggerRect = triggerRef.current.getBoundingClientRect();
      const tooltipRect = tooltipRef.current.getBoundingClientRect();
      
      let x = 0;
      let y = 0;

      switch (position) {
        case 'top':
          x = triggerRect.left + triggerRect.width / 2 - tooltipRect.width / 2;
          y = triggerRect.top - tooltipRect.height - 8;
          break;
        case 'bottom':
          x = triggerRect.left + triggerRect.width / 2 - tooltipRect.width / 2;
          y = triggerRect.bottom + 8;
          break;
        case 'left':
          x = triggerRect.left - tooltipRect.width - 8;
          y = triggerRect.top + triggerRect.height / 2 - tooltipRect.height / 2;
          break;
        case 'right':
          x = triggerRect.right + 8;
          y = triggerRect.top + triggerRect.height / 2 - tooltipRect.height / 2;
          break;
      }

      // Ensure tooltip stays within viewport
      x = Math.max(8, Math.min(x, window.innerWidth - tooltipRect.width - 8));
      y = Math.max(8, Math.min(y, window.innerHeight - tooltipRect.height - 8));

      setTooltipPosition({ x, y });
    }
  }, [isVisible, position]);

  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, []);

  const tooltipStyle: React.CSSProperties = {
    position: 'fixed',
    left: tooltipPosition.x,
    top: tooltipPosition.y,
    color: '#ffffff',
    zIndex: 1000,
    pointerEvents: 'none',
    opacity: isVisible ? 1 : 0,
    transition: 'opacity 0.2s ease',
    // Ensure arrow can extend outside the container
    overflow: 'visible',
  };

  // Create triangle arrow styles based on position
  const getTriangleStyle = (): React.CSSProperties => {
    const baseStyle: React.CSSProperties = {
      position: 'absolute',
      width: 0,
      height: 0,
      borderStyle: 'solid',
      opacity: 0.8,
    };

    // Get the background color from the tooltip style or use default (same as tooltip content)
    const backgroundColor = (style.backgroundColor as string) || '#1f1f1f';

    switch (position) {
      case 'top':
        // Tooltip is above element, arrow points DOWN toward element
        return {
          ...baseStyle,
          bottom: '-5px',
          left: '50%',
          transform: 'translateX(-50%)',
          borderWidth: '6px 6px 0 6px',
          borderColor: `${backgroundColor} transparent transparent transparent`,
        };
      case 'bottom':
        // Tooltip is below element, arrow points UP toward element
        return {
          ...baseStyle,
          top: '-5px',
          left: '50%',
          transform: 'translateX(-50%)',
          borderWidth: '0 6px 6px 6px',
          borderColor: `transparent transparent ${backgroundColor} transparent`,
        };
      case 'left':
        // Tooltip is to the left of element, arrow points RIGHT toward element
        return {
          ...baseStyle,
          right: '-5px',
          top: '50%',
          transform: 'translateY(-50%)',
          borderWidth: '6px 0 6px 6px',
          borderColor: `transparent transparent transparent ${backgroundColor}`,
        };
      case 'right':
        // Tooltip is to the right of element, arrow points LEFT toward element
        return {
          ...baseStyle,
          left: '-5px',
          top: '50%',
          transform: 'translateY(-50%)',
          borderWidth: '6px 6px 6px 0',
          borderColor: `transparent ${backgroundColor} transparent transparent`,
        };
      default:
        return baseStyle;
    }
  };

  // Parse content to handle the separator line
  const renderFormattedContent = () => {
    if (typeof content === 'string') {
      const parts = content.split('\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n');
      if (parts.length === 1) {
        // No separator, just render as plain text
        return <div style={{ whiteSpace: 'pre-wrap', lineHeight: '1.4' }}>{content}</div>;
      }
      
      return (
        <div style={{ whiteSpace: 'pre-wrap', lineHeight: '1.4' }}>
          <div style={{ marginBottom: '8px' }}>{parts[0]}</div>
          <div style={{ 
            height: '1px', 
            background: 'linear-gradient(90deg, transparent, #666, transparent)', 
            margin: '8px 0',
            opacity: 0.6
          }} />
          <div style={{ color: '#ccc', fontSize: '11px' }}>{parts[1]}</div>
        </div>
      );
    }
    
    // If content is not a string, render as is
    return content;
  };

  // Render tooltip header with title and category
  const renderTooltipHeader = () => {
    if (!upgrade) return null;
    
    return (
      <div style={{ marginBottom: '12px' }}>
        {/* Title */}
        <div style={{ 
          fontSize: '14px', 
          fontWeight: 'bold', 
          color: UPGRADE_COLORS[upgrade.category as keyof typeof UPGRADE_COLORS],
          marginBottom: '6px',
          textAlign: 'center'
        }}>
          {upgrade.name}
        </div>
                 {/* Category tag */}
         <div style={{
           fontSize: '10px',
           fontWeight: '700',
           background: UPGRADE_COLORS[upgrade.category as keyof typeof UPGRADE_COLORS],
           color: '#111',
           borderRadius: '3px',
           padding: '2px 6px',
           display: 'block',
           boxShadow: '0 1px 3px #0002',
           border: '1px solid #fff2',
           textAlign: 'center',
           width: 'fit-content',
           margin: '0 auto'
         }}>
           {upgrade.category}
         </div>
      </div>
    );
  };

  const triggerStyle: React.CSSProperties = {
    display: 'inline-block',
    cursor: 'help',
  };

  return (
    <>
      <div
        ref={triggerRef}
        className={`ui-tooltip-trigger ${className}`}
        style={triggerStyle}
        onMouseEnter={showTooltip}
        onMouseLeave={hideTooltip}
        onFocus={showTooltip}
        onBlur={hideTooltip}
      >
        {children}
      </div>
      <div
        ref={tooltipRef}
        className={`ui-tooltip ui-tooltip-${position}`}
        style={tooltipStyle}
      >
                 <div style={{ 
           backgroundColor: (style.backgroundColor as string) || '#1f1f1f',
           padding: '12px 16px',
           fontSize: '12px',
           fontWeight: 'normal',
           letterSpacing: '0.3px',
           opacity: 0.95,
           whiteSpace: 'normal',
           maxWidth: '280px',
           minWidth: '200px',
           borderRadius: '6px',
           boxShadow: '0 4px 12px rgba(0,0,0,0.7)',
           border: '1px solid rgba(255,255,255,0.3)'
                   }}>
                        {renderTooltipHeader()}
                        {renderFormattedContent()}
          </div>
        <div 
          className="ui-tooltip-arrow"
          style={getTriangleStyle()}
        />
      </div>
    </>
  );
};
