// Enemy type enum
export enum EnemyType {
  Normal = "normal",
  Special = "special",
  Boss = "boss",
}











// Base interface for enemy definitions
export interface EnemyDefinition {
  name: string;
  type: EnemyType;
  hp: number;
  armor: number;
  moveSpeed: number;
  attackDamage: number;
  attackSpeed: number;
  attackRange: number;
  meleeRange?: number;
  meleeDamage?: number;
  magicResist: number;
  magicPower: number;
  evasion: number;
  xp: number;
  color: number;
  radius: number;
  projectileColor?: number;
  projectileScale?: number;
  projectileSpeed?: number;
  behavior?: string;
  behaviorParams?: any;
  isSegmented?: boolean;
  segmentCount?: number;
  segmentRadius?: number;
  segmentColor?: number;
  abilities?: string[];
  flying?: boolean;
  description?: string;
  weight?: number; // Spawn weight for weighted selection (higher = more likely to spawn)
}

// Stage definition interface
export interface StageDefinition {
  name: string;
  emoji: string;
  startTime: number;
  endTime: number;
  backgroundColor: number;
  enemyTheme: string;
  welcomeMessage: string;
  normalEnemies: string[];
  specialEnemies: string[];
  bossEnemies: string[];
  spawnRampUp: number; // Time in seconds for spawn rate to reach maximum
  maxSpawnRate: number; // Maximum enemies per spawn cycle
  bossSpawnWindow: { start: number; end: number }; // Percentage of stage duration
  maxNormalEnemies: number; // Maximum normal enemies in play at once
  maxSpecialEnemies: number; // Maximum special enemies in play at once
  bossSpawnChances: { one: number; two: number; three: number }; // Boss spawn probabilities (should sum to 1.0)
}

