// ============================================================================
// SOPHISTICATED ENEMY SPAWNING SYSTEM
// ============================================================================

// New sophisticated spawn rate calculation
export function getSophisticatedSpawnRate(
  stage: StageDefinition,
  elapsedTime: number
): number {
  const stageElapsed = elapsedTime - stage.startTime;
  const stageDuration = stage.endTime - stage.startTime;
  const progress = stageElapsed / stageDuration;

  // 0-50%: Ramp up from 1 to maxSpawnRate
  if (progress <= 0.5) {
    const rampProgress = progress / 0.5;
    return Math.floor(1 + (stage.maxSpawnRate - 1) * rampProgress);
  }

  // 50-70%: Maintain maxSpawnRate
  if (progress <= 0.7) {
    return stage.maxSpawnRate;
  }

  // 70-90%: Gradually reduce spawn rate to 0
  if (progress <= 0.9) {
    const reductionProgress = (progress - 0.7) / 0.2; // 0 to 1
    return Math.floor(stage.maxSpawnRate * (1 - reductionProgress));
  }

  // 90-100%: No spawning, let player clear remaining enemies
  return 0;
}

// Boss-specific spawn rate that allows bosses to spawn during their window
export function getBossSpawnRate(
  stage: StageDefinition,
  elapsedTime: number
): number {
  const stageElapsed = elapsedTime - stage.startTime;
  const stageDuration = stage.endTime - stage.startTime;
  const progress = stageElapsed / stageDuration;

  // If we're in the boss spawn window (40%-60%), allow spawning
  if (
    progress >= stage.bossSpawnWindow.start &&
    progress <= stage.bossSpawnWindow.end
  ) {
    return 1; // Allow at least 1 spawn per cycle for bosses
  }

  return 0;
}

// Calculate special enemy ratio based on stage progress
export function getSpecialEnemyRatio(
  stage: StageDefinition,
  elapsedTime: number
): number {
  const stageElapsed = elapsedTime - stage.startTime;
  const stageDuration = stage.endTime - stage.startTime;
  const progress = stageElapsed / stageDuration;

  // 0-20%: Only normal enemies (0% special)
  if (progress <= 0.2) {
    return 0;
  }

  // 20-50%: Gradually ramp up to 30% special enemies
  if (progress <= 0.5) {
    const rampProgress = (progress - 0.2) / 0.3; // 0 to 1
    return 0.3 * rampProgress; // 0% to 30%
  }

  // 50-100%: Maintain 30% special enemy ratio
  return 0.3;
}

// Calculate effective max enemies based on stage progress (for the squashing effect)
export function getEffectiveMaxEnemies(
  stage: StageDefinition,
  elapsedTime: number,
  isSpecial: boolean
): number {
  const stageElapsed = elapsedTime - stage.startTime;
  const stageDuration = stage.endTime - stage.startTime;
  const progress = stageElapsed / stageDuration;

  const baseMax = isSpecial ? stage.maxSpecialEnemies : stage.maxNormalEnemies;

  // 0-70%: Full max enemies
  if (progress <= 0.7) {
    return baseMax;
  }

  // 70-90%: Gradually reduce max enemies to 0
  if (progress <= 0.9) {
    const reductionProgress = (progress - 0.7) / 0.2; // 0 to 1
    return Math.floor(baseMax * (1 - reductionProgress));
  }

  // 90-100%: No new enemies allowed
  return 0;
}

// Enhanced enemy limit checking that respects the squashing effect
export function canSpawnNormalEnemySophisticated(
  stage: StageDefinition,
  elapsedTime: number,
  currentNormalCount: number
): boolean {
  const effectiveMax = getEffectiveMaxEnemies(stage, elapsedTime, false);
  return currentNormalCount < effectiveMax;
}

export function canSpawnSpecialEnemySophisticated(
  stage: StageDefinition,
  elapsedTime: number,
  currentSpecialCount: number
): boolean {
  const effectiveMax = getEffectiveMaxEnemies(stage, elapsedTime, true);
  return currentSpecialCount < effectiveMax;
}

// Enhanced spawn distribution calculation
export interface SophisticatedSpawnDistribution {
  normalCount: number;
  specialCount: number;
  shouldSpawn: boolean;
}

export function getSophisticatedSpawnDistribution(
  stage: StageDefinition,
  elapsedTime: number,
  currentNormalCount: number,
  currentSpecialCount: number
): SophisticatedSpawnDistribution {
  const spawnRate = getSophisticatedSpawnRate(stage, elapsedTime);
  const specialRatio = getSpecialEnemyRatio(stage, elapsedTime);

  // Calculate target distribution
  let targetSpecialCount = Math.floor(spawnRate * specialRatio);
  let targetNormalCount = spawnRate - targetSpecialCount;

  // Calculate remaining capacity for each type
  const effectiveMaxNormal = getEffectiveMaxEnemies(stage, elapsedTime, false);
  const effectiveMaxSpecial = getEffectiveMaxEnemies(stage, elapsedTime, true);

  const remainingNormalCapacity = Math.max(
    0,
    effectiveMaxNormal - currentNormalCount
  );
  const remainingSpecialCapacity = Math.max(
    0,
    effectiveMaxSpecial - currentSpecialCount
  );

  // Clamp spawn counts to available capacity (spawn what we can, up to the limit)
  targetNormalCount = Math.min(targetNormalCount, remainingNormalCapacity);
  targetSpecialCount = Math.min(targetSpecialCount, remainingSpecialCapacity);

  // If we have leftover spawn "budget" and capacity in the other type, redistribute
  const originalTotal = spawnRate;
  const currentTotal = targetNormalCount + targetSpecialCount;
  const excess = originalTotal - currentTotal;

  if (excess > 0) {
    // Try to use excess for normal enemies first
    const additionalNormal = Math.min(
      excess,
      remainingNormalCapacity - targetNormalCount
    );
    targetNormalCount += additionalNormal;

    // Then try special enemies for any remaining excess
    const remainingExcess = excess - additionalNormal;
    if (remainingExcess > 0) {
      const additionalSpecial = Math.min(
        remainingExcess,
        remainingSpecialCapacity - targetSpecialCount
      );
      targetSpecialCount += additionalSpecial;
    }
  }

  const shouldSpawn = targetNormalCount + targetSpecialCount > 0;

  return {
    normalCount: targetNormalCount,
    specialCount: targetSpecialCount,
    shouldSpawn,
  };
}

// Weighted selection function for enemies
export function selectWeightedEnemy(enemyKeys: string[]): string {
  // Get enemy definitions and their weights
  const enemies = enemyKeys.map((key) => ({
    key,
    weight: ENEMY_DEFINITIONS[key]?.weight || 1, // Default weight of 1 if not specified
  }));

  // Calculate total weight
  const totalWeight = enemies.reduce((sum, enemy) => sum + enemy.weight, 0);

  // Generate random number between 0 and totalWeight
  let random = Math.random() * totalWeight;

  // Select enemy based on weight
  for (const enemy of enemies) {
    random -= enemy.weight;
    if (random <= 0) {
      return enemy.key;
    }
  }

  // Fallback to last enemy (shouldn't happen with proper weights)
  return enemies[enemies.length - 1].key;
}
