import React from 'react';
import { ItemTooltip } from './ItemTooltip';
import { ITEMS, ITEM_ICONS, ITEM_COLORS } from '../../game/items';

interface ItemBarProps {
  playerItems: string[];
  itemStacks?: Record<string, number>;
  onItemClick?: (itemName: string) => void;
  onSellItem?: (itemName: string) => void;
}

export interface ItemButtonProps {
  item: any;
  stackCount?: number;
  onClick?: () => void;
  tooltipContent?: string;
  size?: number;
  showTooltip?: boolean;
}

export const ItemBar = ({ playerItems, itemStacks = {}, onItemClick, onSellItem }: ItemBarProps) => {
  if (!playerItems || playerItems.length === 0) {
    return null;
  }

  return (
    <div style={{
      position: 'fixed',
      bottom: 85, // Position above the upgrade bar (which is at bottom: 15)
      left: '50%',
      transform: 'translateX(-50%)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      gap: '6px',
      zIndex: 2000,
      background: 'rgba(0,0,0,0.3)',
      borderRadius: '10px',
      padding: '9px',
      backdropFilter: 'blur(8px)',
      border: '1px solid rgba(255,255,255,0.1)',
      maxWidth: '90vw',
      overflowX: 'auto'
    }}>
      {playerItems.map((itemName) => {
        const item = ITEMS.find(i => i.name === itemName);
        if (!item) return null;

        const stackCount = itemStacks[itemName] || 1;
        const isConsumable = item.isConsumable;
        const canClick = isConsumable && onItemClick;

        return (
          <div
            key={itemName}
            onContextMenu={(e) => {
              e.preventDefault();
              if (onSellItem) {
                onSellItem(itemName);
              }
            }}
          >
            <ItemButton
              item={item}
              stackCount={stackCount}
              onClick={canClick ? () => onItemClick(itemName) : undefined}
              tooltipContent={`${item.longDescription}\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n💡 Left-click: Use item\n🖱️ Right-click: Sell for ${Math.floor(item.price / 2)} gold`}
            />
          </div>
        );
      })}
    </div>
  );
};

export const ItemButton = ({
  item,
  stackCount = 1,
  onClick,
  tooltipContent,
  size = 45,
  showTooltip = true
}: ItemButtonProps) => {
  const isConsumable = item.isConsumable;
  const canClick = onClick !== undefined;

  const buttonContent = (
    <div
      role={canClick ? 'button' : undefined}
      tabIndex={canClick ? 0 : undefined}
      onClick={onClick}
      onKeyDown={canClick ? (e) => { if (e.key === 'Enter' || e.key === ' ') onClick(); } : undefined}
      style={{
        cursor: canClick ? 'pointer' : 'default',
        background: `linear-gradient(15deg, ${ITEM_COLORS[item.category as keyof typeof ITEM_COLORS]}33 0%, #23232b 100%)`,
        border: 'none',
        borderRadius: '50%',
        width: size,
        height: size,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        position: 'relative',
        boxShadow: '0 4px 12px rgba(0,0,0,0.3)',
        outline: 'none',
        transition: 'transform 0.15s, box-shadow 0.15s',
        margin: '0 6px',
        flexShrink: 0
      }}
      onMouseDown={e => canClick && (e.currentTarget.style.transform = 'scale(0.95)')}
      onMouseUp={e => canClick && (e.currentTarget.style.transform = '')}
    >
      {/* Icon in center */}
      <div style={{
        fontSize: `${size * 0.3}px`,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        color: '#fff',
        filter: isConsumable ? 'none' : 'brightness(0.9)'
      }}>
        {item.icon || ITEM_ICONS[item.name] || '🎒'}
      </div>

      {/* Stack count overlay (for stackable items) */}
      {stackCount > 1 && (
        <div style={{
          position: 'absolute',
          top: -6,
          right: -6,
          background: '#23232b',
          color: '#fff',
          borderRadius: '50%',
          width: 18,
          height: 18,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: '0.55rem',
          fontWeight: 'bold',
          border: '1.5px solid #fff',
          boxShadow: '0 2px 4px rgba(0,0,0,0.3)'
        }}>
          {stackCount}
        </div>
      )}

      {/* Rarity indicator - small dots */}
      <div style={{
        position: 'absolute',
        bottom: -3,
        left: '50%',
        transform: 'translateX(-50%)',
        display: 'flex',
        gap: '1.5px'
      }}>
        {Array.from({ length: item.rarity }, (_, i) => (
          <div
            key={i}
            style={{
              width: '3px',
              height: '3px',
              borderRadius: '50%',
              background: item.rarity === 1 ? '#ffffff' :
                         item.rarity === 2 ? '#ffd700' : '#ff6b6b',
              boxShadow: '0 1px 2px rgba(0,0,0,0.3)'
            }} />
        ))}
      </div>

      {/* Consumable indicator */}
      {isConsumable && (
        <div style={{
          position: 'absolute',
          top: -3,
          left: -3,
          width: 8,
          height: 8,
          borderRadius: '50%',
          background: '#00ff00',
          border: '1px solid #fff',
          boxShadow: '0 1px 2px rgba(0,0,0,0.3)'
        }} />
      )}
    </div>
  );

  if (!showTooltip) {
    return buttonContent;
  }

  return (
    <ItemTooltip
      content={tooltipContent || `${item.longDescription}\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n💡 Left-click: Use item\n🖱️ Right-click: Sell for ${Math.floor(item.price / 2)} gold`}
      item={item}
    >
      {buttonContent}
    </ItemTooltip>
  );
};
