import React from 'react';
import { Modal } from './Modal';
import { Button } from './Button';
import { Panel } from './Panel';

export interface DeathPanelProps {
  isOpen: boolean;
  onClose: () => void;
  onBackToMenu: () => void;
  stats: {
    timeSurvived: number;
    enemiesKilled: number;
    level: number;
    xp: number;
    damageDealt: number;
    damageTaken: number;
    upgrades: Record<string, number>;
  };
}

export const DeathPanel: React.FC<DeathPanelProps> = ({
  isOpen,
  onClose,
  onBackToMenu,
  stats,
}) => {
  const formatTime = (seconds: number): string => {
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = Math.floor(seconds % 60);
    return `${minutes}:${remainingSeconds.toString().padStart(2, '0')}`;
  };

  const formatNumber = (num: number): string => {
    if (num >= 1000000) {
      return `${(num / 1000000).toFixed(1)}M`;
    } else if (num >= 1000) {
      return `${(num / 1000).toFixed(1)}K`;
    }
    return num.toString();
  };

  const getUpgradeCategoryColor = (category: string): string => {
    const colors = {
      Physical: '#ff4444',
      Magical: '#c388f7',
      Defensive: '#3ecf4a',
      Utility: '#44aaff',
    };
    return colors[category as keyof typeof colors] || '#ffffff';
  };

  const categorizeUpgrades = (upgrades: Record<string, number>) => {
    const categories = {
      Physical: [] as string[],
      Magical: [] as string[],
      Defensive: [] as string[],
      Utility: [] as string[],
    };

    Object.entries(upgrades).forEach(([upgrade, level]) => {
      // Map upgrade names to categories based on the game's upgrade definitions
      if (['Rapid Fire', 'Burst Fire', 'Piercing Bullets', 'Big Bullets', 'Homing Bullets', 'Shotgun Shot', 'Crit Chance', 'Ricochet'].includes(upgrade)) {
        categories.Physical.push(`${upgrade} (${level})`);
      } else if (['Explosive Rounds', 'Wisps', 'Lava Shot', 'Ice Shard'].includes(upgrade)) {
        categories.Magical.push(`${upgrade} (${level})`);
      } else if (['Lifesteal', 'Armor Up', 'Regeneration', 'Invulnerability', 'Max Health Up'].includes(upgrade)) {
        categories.Defensive.push(`${upgrade} (${level})`);
      } else if (['Move Speed Up', 'XP Boost', 'Magnet', 'Cooldown Reduction', 'Area Up', 'Luck Up', 'Gold Find'].includes(upgrade)) {
        categories.Utility.push(`${upgrade} (${level})`);
      } else {
        // Default to Utility for unknown upgrades
        categories.Utility.push(`${upgrade} (${level})`);
      }
    });

    return categories;
  };

  const categorizedUpgrades = categorizeUpgrades(stats.upgrades);

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title="GAME OVER"
      size="large"
      showCloseButton={false}
      closeOnBackdropClick={false}
      style={{
        background: 'linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%)',
        border: '2px solid #ff4444',
        borderRadius: '8px',
      }}
    >
      <div style={{ color: '#ffffff', textAlign: 'center' }}>
        {/* Death Message */}
        <div style={{ marginBottom: '24px' }}>
          <h1 style={{ 
            fontSize: '32px', 
            color: '#ff4444', 
            margin: '0 0 8px 0',
            textShadow: '2px 2px 4px rgba(0,0,0,0.5)'
          }}>
            YOU DIED
          </h1>
          <p style={{ fontSize: '16px', color: '#cccccc', margin: 0 }}>
            But you fought valiantly! Here's how you performed:
          </p>
        </div>

        {/* Stats Grid */}
        <div style={{ 
          display: 'grid', 
          gridTemplateColumns: 'repeat(2, 1fr)', 
          gap: '16px', 
          marginBottom: '24px' 
        }}>
          <Panel style={{ padding: '16px', textAlign: 'center' }}>
            <div style={{ fontSize: '16px', color: '#ffffff', marginBottom: '8px', fontWeight: 'bold' }}>⏱️ TIME SURVIVED</div>
            <div style={{ fontSize: '28px', fontWeight: 'bold', color: '#44aaff' }}>
              {formatTime(stats.timeSurvived)}
            </div>
            <div style={{ fontSize: '12px', color: '#888888', marginTop: '4px' }}>Minutes:Seconds</div>
          </Panel>
          
          <Panel style={{ padding: '16px', textAlign: 'center' }}>
            <div style={{ fontSize: '16px', color: '#ffffff', marginBottom: '8px', fontWeight: 'bold' }}>💀 ENEMIES KILLED</div>
            <div style={{ fontSize: '28px', fontWeight: 'bold', color: '#ff4444' }}>
              {formatNumber(stats.enemiesKilled)}
            </div>
            <div style={{ fontSize: '12px', color: '#888888', marginTop: '4px' }}>Total Defeated</div>
          </Panel>
          
          <Panel style={{ padding: '16px', textAlign: 'center' }}>
            <div style={{ fontSize: '16px', color: '#ffffff', marginBottom: '8px', fontWeight: 'bold' }}>⭐ LEVEL REACHED</div>
            <div style={{ fontSize: '28px', fontWeight: 'bold', color: '#3ecf4a' }}>
              {stats.level}
            </div>
            <div style={{ fontSize: '12px', color: '#888888', marginTop: '4px' }}>Character Level</div>
          </Panel>
          
          <Panel style={{ padding: '16px', textAlign: 'center' }}>
            <div style={{ fontSize: '16px', color: '#ffffff', marginBottom: '8px', fontWeight: 'bold' }}>✨ XP GAINED</div>
            <div style={{ fontSize: '28px', fontWeight: 'bold', color: '#c388f7' }}>
              {formatNumber(stats.xp)}
            </div>
            <div style={{ fontSize: '12px', color: '#888888', marginTop: '4px' }}>Experience Points</div>
          </Panel>
          
          <Panel style={{ padding: '16px', textAlign: 'center' }}>
            <div style={{ fontSize: '16px', color: '#ffffff', marginBottom: '8px', fontWeight: 'bold' }}>⚔️ DAMAGE DEALT</div>
            <div style={{ fontSize: '28px', fontWeight: 'bold', color: '#ffaa00' }}>
              {formatNumber(stats.damageDealt)}
            </div>
            <div style={{ fontSize: '12px', color: '#888888', marginTop: '4px' }}>Total Damage Output</div>
          </Panel>
          
          <Panel style={{ padding: '16px', textAlign: 'center' }}>
            <div style={{ fontSize: '16px', color: '#ffffff', marginBottom: '8px', fontWeight: 'bold' }}>🛡️ DAMAGE TAKEN</div>
            <div style={{ fontSize: '28px', fontWeight: 'bold', color: '#ff6666' }}>
              {formatNumber(stats.damageTaken)}
            </div>
            <div style={{ fontSize: '12px', color: '#888888', marginTop: '4px' }}>Total Damage Received</div>
          </Panel>
        </div>

        {/* Upgrade Build */}
        <div style={{ marginBottom: '24px' }}>
          <h3 style={{ 
            fontSize: '20px', 
            color: '#ffffff', 
            margin: '0 0 16px 0',
            textAlign: 'center'
          }}>
            🔧 Your Upgrade Build
          </h3>
          <p style={{ fontSize: '14px', color: '#cccccc', textAlign: 'center', marginBottom: '16px' }}>
            Here are all the upgrades you collected during your run:
          </p>
          
          <div style={{ 
            display: 'grid', 
            gridTemplateColumns: 'repeat(2, 1fr)', 
            gap: '12px' 
          }}>
            {Object.entries(categorizedUpgrades).map(([category, upgrades]) => (
              <div key={category} style={{ textAlign: 'left' }}>
                <h4 style={{ 
                  fontSize: '16px', 
                  color: getUpgradeCategoryColor(category), 
                  margin: '0 0 8px 0',
                  borderBottom: `2px solid ${getUpgradeCategoryColor(category)}`,
                  paddingBottom: '4px'
                }}>
                  {category}
                </h4>
                {upgrades.length > 0 ? (
                  <div style={{ fontSize: '14px', color: '#cccccc' }}>
                    {upgrades.map((upgrade, index) => (
                      <div key={index} style={{ marginBottom: '4px' }}>
                        • {upgrade}
                      </div>
                    ))}
                  </div>
                ) : (
                  <div style={{ fontSize: '14px', color: '#666666', fontStyle: 'italic' }}>
                    No {category} upgrades
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>

        {/* Action Buttons */}
        <div style={{ 
          display: 'flex', 
          gap: '16px', 
          justifyContent: 'center',
          marginTop: '24px'
        }}>
          <Button
            onClick={onBackToMenu}
            style={{
              backgroundColor: '#ff4444',
              color: '#ffffff',
              fontSize: '16px',
              padding: '12px 24px',
              border: 'none',
              borderRadius: '6px',
              cursor: 'pointer',
              fontWeight: 'bold',
              textTransform: 'uppercase',
              letterSpacing: '1px',
            }}
          >
            Back to Menu
          </Button>
        </div>
      </div>
    </Modal>
  );
};
